final_template:
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
  }
}

locals {
  tags = {
    Name        = "two-tier-sg"
    Environment = "dev"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "main-vpc"
  })
}

resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "alb-sg"
  })
}

resource "aws_security_group_rule" "alb_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "alb_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Security group for backend instances allowing traffic from ALB"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "allow-alb-sg"
  })
}

resource "aws_security_group_rule" "allow_alb_ingress_from_alb" {
  type                     = "ingress"
  from_port                = 80
  to_port                  = 80
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.alb.id
  security_group_id        = aws_security_group.allow_alb.id
}

resource "aws_security_group_rule" "allow_alb_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.allow_alb.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "test"
}

variable "project" {
  description = "Project name used for tagging."
  type        = string
  default     = "networking-sandbox"
}

variable "owner" {
  description = "Team or individual responsible for the environment."
  type        = string
  default     = "platform-team"
}

locals {
  common_tags = {
    Project     = var.project
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "Terraform"
  }

  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidr   = "10.0.1.0/24"
  private_subnet_cidr  = "10.0.2.0/24"
  ipv6_subnet_new_bits = 8
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = local.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_subnet_cidr
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, local.ipv6_subnet_new_bits, 1)
  availability_zone               = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.private_subnet_cidr
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, local.ipv6_subnet_new_bits, 2)
  availability_zone               = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-private-subnet"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-public-rt"
    Tier = "public"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-${var.environment}-private-rt"
    Tier = "private"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for all resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "List of CIDR blocks for each subnet, one per availability zone"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  count = length(var.subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "main-subnet-${count.index}"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Inputs
# ---------------------------------------------------------------------------

variable "tags" {
  description = "User-controlled metadata tags applied to every resource created by this configuration."
  type        = map(string)

  default = {
    Project   = "GlacierEFSEC2"
    ManagedBy = "Terraform"
  }
}

# ---------------------------------------------------------------------------
# Provider metadata (static lookups only - no pre-existing infrastructure)
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  common_tags = var.tags

  # ARN patterns built exclusively from provider metadata - no hardcoded
  # account IDs, regions or partitions.
  ec2_instance_arn   = "arn:${local.partition}:ec2:${local.region}:${local.account_id}:instance/*"
  ec2_volume_arn     = "arn:${local.partition}:ec2:${local.region}:${local.account_id}:volume/*"
  glacier_vaults_arn = "arn:${local.partition}:glacier:${local.region}:${local.account_id}:vaults/*"
}

# ---------------------------------------------------------------------------
# IAM user
# ---------------------------------------------------------------------------

resource "aws_iam_user" "tj" {
  name = "TJ"

  tags = merge(local.common_tags, {
    Name = "TJ"
  })
}

# ---------------------------------------------------------------------------
# Custom policy document: GlacierEFSEC2 (EC2 + EFS + Glacier)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "glacier_efs_ec2" {
  # EC2 describe/list APIs do not support resource-level permissions, so the
  # read-only surface is constrained by an explicit action list (never "*").
  statement {
    sid       = "EC2DescribeReadOnly"
    effect    = "Allow"
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }

  # ec2:RunInstances launches instances and therefore must be authorized
  # against launch-time dependencies (AMI, snapshot, subnet, security group,
  # key pair, volume) that do not exist yet and cannot be named in advance.
  # This is the only action that legitimately requires Resource = "*".
  statement {
    sid       = "EC2RunInstancesUnscoped"
    effect    = "Allow"
    actions   = ["ec2:RunInstances"]
    resources = ["*"]
  }

  # Instance lifecycle and volume attachment actions DO support resource-level
  # permissions, so they are scoped to this account's instance and volume ARNs.
  statement {
    sid    = "EC2InstanceAndVolumeManagement"
    effect = "Allow"

    actions = [
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:RebootInstances",
      "ec2:TerminateInstances",
      "ec2:ModifyInstanceAttribute",
      "ec2:AttachVolume",
      "ec2:DetachVolume",
      "ec2:CreateTags",
      "ec2:DeleteTags",
    ]

    resources = [
      local.ec2_instance_arn,
      local.ec2_volume_arn,
    ]
  }

  # EFS client-mount access, scoped to the file system created in this
  # configuration rather than "*".
  statement {
    sid    = "EFSClientMountAccess"
    effect = "Allow"

    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:DescribeFileSystems",
      "elasticfilesystem:DescribeMountTargets",
      "elasticfilesystem:DescribeAccessPoints",
    ]

    resources = [
      aws_efs_file_system.app.arn,
    ]
  }

  # Glacier vault management actions, scoped to this account's vaults.
  statement {
    sid    = "GlacierVaultManagement"
    effect = "Allow"

    actions = [
      "glacier:DeleteVault",
      "glacier:DescribeVault",
      "glacier:GetVaultAccessPolicy",
      "glacier:SetVaultAccessPolicy",
      "glacier:DeleteVaultAccessPolicy",
      "glacier:GetVaultLock",
      "glacier:SetVaultLock",
      "glacier:AbortVaultLock",
      "glacier:CompleteVaultLock",
      "glacier:AddTagsToVault",
      "glacier:ListTagsForVault",
      "glacier:RemoveTagsFromVault",
      "glacier:InitiateJob",
      "glacier:DescribeJob",
      "glacier:ListJobs",
      "glacier:GetJobOutput",
    ]

    resources = [
      local.glacier_vaults_arn,
    ]
  }

  # Glacier multipart upload actions, scoped to the vault owned by this
  # configuration plus this account's vault namespace.
  statement {
    sid    = "GlacierMultipartUpload"
    effect = "Allow"

    actions = [
      "glacier:InitiateMultipartUpload",
      "glacier:UploadMultipartPart",
      "glacier:CompleteMultipartUpload",
      "glacier:AbortMultipartUpload",
      "glacier:ListMultipartUploads",
      "glacier:ListParts",
    ]

    resources = [
      aws_glacier_vault.archive.arn,
      local.glacier_vaults_arn,
    ]
  }

  # glacier:CreateVault targets a vault that does not exist yet and
  # glacier:ListVaults must enumerate every vault in the account/Region.
  # Neither action supports resource-level permissions, so Resource must be
  # "*"; the action list is explicit and never "*".
  statement {
    sid       = "GlacierVaultCreateAndListUnscoped"
    effect    = "Allow"
    actions   = ["glacier:CreateVault", "glacier:ListVaults"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "glacier_efs_ec2" {
  name        = "GlacierEFSEC2"
  description = "Broad EC2 instance lifecycle and describe permissions, least-privilege EFS client-mount access scoped to the managed file system, and Glacier vault management plus multipart upload permissions scoped to the managed vault."

  policy = data.aws_iam_policy_document.glacier_efs_ec2.json

  tags = merge(local.common_tags, {
    Name = "GlacierEFSEC2"
  })
}

resource "aws_iam_user_policy_attachment" "tj_glacier_efs_ec2" {
  user       = aws_iam_user.tj.name
  policy_arn = aws_iam_policy.glacier_efs_ec2.arn
}

# ---------------------------------------------------------------------------
# EFS file system backing the EFS client-mount permissions
# ---------------------------------------------------------------------------

resource "aws_efs_file_system" "app" {
  creation_token = "tj-glacier-efsec2-app"
  encrypted      = true

  tags = merge(local.common_tags, {
    Name = "tj-glacier-efsec2-app"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Glacier vault backing the Glacier permissions
# ---------------------------------------------------------------------------

resource "aws_glacier_vault" "archive" {
  name = "tj-glacier-archive"

  tags = merge(local.common_tags, {
    Name = "tj-glacier-archive"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Programmatic access - credentials stored in Secrets Manager, never in
# plaintext configuration, variables or outputs.
# ---------------------------------------------------------------------------

resource "aws_iam_access_key" "tj" {
  user = aws_iam_user.tj.name
}

resource "aws_secretsmanager_secret" "tj_access_key" {
  name        = "TJ-access-key"
  description = "Programmatic access key material for the TJ IAM user. Rotate on a regular schedule."

  tags = merge(local.common_tags, {
    Name = "TJ-access-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "tj_access_key" {
  secret_id = aws_secretsmanager_secret.tj_access_key.id

  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.tj.id
    secret_access_key = aws_iam_access_key.tj.secret
    user_name         = aws_iam_user.tj.name
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for current account ID (used to construct ARNs where needed)
data "aws_caller_identity" "current" {}

# Variable for allowed Grafana accounts
variable "allowed_grafana_accounts" {
  description = "List of AWS accounts that can assume the Grafana query role via AWS Managed Grafana"
  type        = list(string)
  default     = ["123456789012"]
}

# Variable for the IAM role name
variable "grafana_role_name" {
  description = "Name of the IAM role for Grafana queries"
  type        = string
  default     = "GrafanaQueryRole"
}

# Variable for the custom IAM policy name
variable "grafana_policy_name" {
  description = "Name of the IAM policy for Grafana data sources"
  type        = string
  default     = "GrafanaDataSourcePolicy"
}

# Variable for AWS region (used only for reference, provider is injected)
variable "aws_region" {
  description = "AWS region for the resources"
  type        = string
  default     = "us-east-1"
}

# Variable for Amazon Managed Service for Prometheus workspace ARNs
variable "prometheus_workspace_arns" {
  description = "List of ARNs of AMP workspaces that Grafana is allowed to query"
  type        = list(string)
  default     = []
}

# IAM role for Grafana to assume
resource "aws_iam_role" "grafana_query" {
  name = var.grafana_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "grafana.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = var.allowed_grafana_accounts
          }
        }
      }
    ]
  })

  # Prevent accidental deletion in production
  lifecycle {
    prevent_destroy = true
  }
}

# Custom IAM policy for Grafana data source permissions
resource "aws_iam_policy" "grafana_data_source" {
  name        = var.grafana_policy_name
  description = "Policy allowing Grafana to query Amazon Managed Service for Prometheus and CloudWatch metrics"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowQueryAMP"
        Effect = "Allow"
        Action = [
          "aps:QueryMetrics",
          "aps:GetSeries",
          "aps:GetLabels",
          "aps:GetMetricMetadata"
        ]
        Resource = length(var.prometheus_workspace_arns) > 0 ? var.prometheus_workspace_arns : ["arn:aws:aps:*:${data.aws_caller_identity.current.account_id}:workspace/*"]
      },
      {
        Sid    = "AllowCloudWatchMetrics"
        Effect = "Allow"
        Action = [
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })

  # Prevent accidental deletion in production
  lifecycle {
    prevent_destroy = true
  }
}

# Attach the custom policy to the role
resource "aws_iam_role_policy_attachment" "grafana_attach" {
  role       = aws_iam_role.grafana_query.name
  policy_arn = aws_iam_policy.grafana_data_source.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

locals {
  common_tags = {
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "public-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "private-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "main-nat-gateway"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "main" {
  name        = "main-security-group"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 3000 from anywhere"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "PostgreSQL port 5432 from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "main-security-group"
  })
}

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = "service.local"
  description = "Private DNS namespace for containerized applications"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "service-local-namespace"
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

resource "aws_cognito_user_pool" "main" {
  name = "main-user-pool"

  mfa_configuration = "OFF"

  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "app_client" {
  name         = "app-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = true

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

resource "aws_secretsmanager_secret" "app_client_secret" {
  name_prefix = "cognito-app-client-secret-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "app_client_secret" {
  secret_id     = aws_secretsmanager_secret.app_client_secret.id
  secret_string = aws_cognito_user_pool_client.app_client.client_secret
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name = "main-identity-pool"

  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id     = aws_cognito_user_pool_client.app_client.id
    provider_name = aws_cognito_user_pool.main.endpoint
  }

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "cognito_authenticated_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }
  }
}

resource "aws_iam_role" "cognito_authenticated" {
  name               = "cognito-authenticated-role"
  assume_role_policy = data.aws_iam_policy_document.cognito_authenticated_trust.json
}

data "aws_iam_policy_document" "cognito_sync_access" {
  statement {
    actions = [
      "cognito-sync:ListRecords",
      "cognito-sync:UpdateRecords",
      "cognito-sync:DescribeDataset",
      "cognito-sync:SubscribeToDataset",
      "cognito-sync:UnsubscribeFromDataset",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cognito_sync_access" {
  name   = "cognito-sync-access"
  policy = data.aws_iam_policy_document.cognito_sync_access.json
}

data "aws_iam_policy_document" "mobile_analytics_access" {
  statement {
    actions   = ["mobileanalytics:PutEvents"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "mobile_analytics_access" {
  name   = "mobile-analytics-access"
  policy = data.aws_iam_policy_document.mobile_analytics_access.json
}

resource "aws_iam_role_policy_attachment" "cognito_sync_access" {
  role       = aws_iam_role.cognito_authenticated.name
  policy_arn = aws_iam_policy.cognito_sync_access.arn
}

resource "aws_iam_role_policy_attachment" "mobile_analytics_access" {
  role       = aws_iam_role.cognito_authenticated.name
  policy_arn = aws_iam_policy.mobile_analytics_access.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.cognito_authenticated.arn
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "creation_mode" {
  description = "Mutually exclusive flags to determine KMS key creation mode"
  type = object({
    standard          = bool
    external          = bool
    replica_standard  = bool
    replica_external  = bool
  })
  default = {
    standard          = true
    external          = false
    replica_standard  = false
    replica_external  = false
  }
  validation {
    condition     = length([for k, v in var.creation_mode : v if v]) == 1
    error_message = "Exactly one creation mode flag must be set to true."
  }
}

variable "key_usage" {
  description = "Intended use of the KMS key"
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Specification of the KMS key"
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "bypass_policy_lockout_safety_check" {
  description = "Bypass policy lockout safety check"
  type        = bool
  default     = false
}

variable "description" {
  description = "Description of the KMS key"
  type        = string
  default     = ""
}

variable "rotation_enabled" {
  description = "Enable automatic key rotation (only for standard keys)"
  type        = bool
  default     = false
}

variable "multi_region" {
  description = "Specify whether the key is multi-region (standard keys only)"
  type        = bool
  default     = false
}

variable "key_material_base64" {
  description = "Base64-encoded key material for external keys"
  type        = string
  default     = null
  sensitive   = true
}

variable "primary_key_arn" {
  description = "ARN of the primary key for replica keys"
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the primary external key for replica external keys"
  type        = string
  default     = null
}

variable "key_administrators" {
  description = "List of IAM ARNs for key administrators"
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "List of IAM ARNs for key users"
  type        = list(string)
  default     = []
}

variable "service_users" {
  description = "List of IAM ARNs for service integration users"
  type        = list(string)
  default     = []
}

variable "ec2_autoscale_roles" {
  description = "List of IAM role ARNs for EC2 Auto Scaling"
  type        = list(string)
  default     = []
}

variable "symmetric_crypto_usage_users" {
  description = "List of IAM ARNs for users needing symmetric crypto operations (Encrypt, Decrypt, GenerateDataKey)"
  type        = list(string)
  default     = []
}

variable "hmac_crypto_usage_users" {
  description = "List of IAM ARNs for users needing HMAC operations"
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_users" {
  description = "List of IAM ARNs for users needing asymmetric public key encryption (Encrypt, Decrypt)"
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "List of IAM ARNs for users needing asymmetric sign/verify operations"
  type        = list(string)
  default     = []
}

variable "dnssec_enabled" {
  description = "Whether to include Route 53 DNSSEC signing permission"
  type        = bool
  default     = false
}

variable "custom_policy_statements" {
  description = "List of custom policy statements to add"
  type = list(object({
    effect    = string
    actions   = list(string)
    principals = list(object({
      type        = string
      identifiers = list(string)
    }))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "policy_override_document" {
  description = "JSON string that replaces the entire key policy when set"
  type        = string
  default     = null
}

variable "target_key_arn_for_alias" {
  description = "ARN of the key to alias (defaults to the created key)"
  type        = string
  default     = null
}

variable "aliases" {
  description = "Map of alias definitions. Each key is the alias name; value is an object with optional target_key_arn, and either name or name_prefix"
  type = map(object({
    target_key_arn = optional(string)
    name           = optional(string)
    name_prefix    = optional(string)
  }))
  default = {}
}

variable "grants" {
  description = "List of KMS grant definitions"
  type = list(object({
    name                               = string
    grantee_principal                  = string
    allowed_operations                 = list(string)
    retiring_principal                 = optional(string)
    constraints_encryption_context_subset = optional(map(string))
  }))
  default = []
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

locals {
  key_arn = try(
    aws_kms_key.standard[0].arn,
    aws_kms_external_key.external[0].arn,
    aws_kms_replica_key.replica_standard[0].arn,
    aws_kms_replica_external_key.replica_external[0].arn,
    null
  )
  key_id = try(
    aws_kms_key.standard[0].key_id,
    aws_kms_external_key.external[0].id,
    aws_kms_replica_key.replica_standard[0].key_id,
    aws_kms_replica_external_key.replica_external[0].id,
    null
  )
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "key_policy" {
  count = var.policy_override_document != null ? 0 : 1

  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []
    content {
      sid    = "AllowKeyAdministrators"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
      actions = [
        "kms:Create*",
        "kms:Describe*",
        "kms:Enable*",
        "kms:List*",
        "kms:Put*",
        "kms:Update*",
        "kms:Revoke*",
        "kms:Disable*",
        "kms:Get*",
        "kms:Delete*",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:ScheduleKeyDeletion",
        "kms:CancelKeyDeletion"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []
    content {
      sid    = "AllowKeyUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.service_users) > 0 ? [1] : []
    content {
      sid    = "AllowServiceUsers"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.service_users
      }
      actions = [
        "kms:Decrypt",
        "kms:GenerateDataKey*"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.ec2_autoscale_roles) > 0 ? [1] : []
    content {
      sid    = "AllowAutoScalingRoles"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.ec2_autoscale_roles
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:GenerateDataKey*",
        "kms:ReEncrypt*",
        "kms:CreateGrant",
        "kms:ListGrants",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.symmetric_crypto_usage_users) > 0 ? [1] : []
    content {
      sid    = "AllowSymmetricCryptoUsage"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.symmetric_crypto_usage_users
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:GenerateDataKey",
        "kms:GenerateDataKeyWithoutPlaintext"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.hmac_crypto_usage_users) > 0 ? [1] : []
    content {
      sid    = "AllowHMACCryptoUsage"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.hmac_crypto_usage_users
      }
      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.asymmetric_public_encryption_users) > 0 ? [1] : []
    content {
      sid    = "AllowAsymmetricPublicEncryption"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_public_encryption_users
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = length(var.asymmetric_sign_verify_users) > 0 ? [1] : []
    content {
      sid    = "AllowAsymmetricSignVerify"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_sign_verify_users
      }
      actions = [
        "kms:Sign",
        "kms:Verify"
      ]
      resources = ["*"]
    }
  }

  dynamic "statement" {
    for_each = var.dnssec_enabled ? [1] : []
    content {
      sid    = "AllowRoute53DNSSECSigning"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["dnssec.amazonaws.com"]
      }
      actions   = ["kms:Sign"]
      resources = ["*"]
      condition {
        test     = "StringEquals"
        variable = "kms:ViaService"
        values   = ["route53.${data.aws_region.current.name}.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid    = "CustomStatement${statement.key}"
      effect = statement.value.effect
      principals {
        type        = statement.value.principals[0].type
        identifiers = statement.value.principals[0].identifiers
      }
      actions   = statement.value.actions
      resources = ["*"]
      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

# Standard KMS key with AWS-provided key material
resource "aws_kms_key" "standard" {
  count = var.creation_mode.standard ? 1 : 0

  description              = var.description
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  policy = var.policy_override_document != null ? var.policy_override_document : data.aws_iam_policy_document.key_policy[0].json
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  deletion_window_in_days            = 30
  enable_key_rotation                = var.rotation_enabled
  is_enabled                         = true
  multi_region                       = var.multi_region

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# External KMS key with imported key material
resource "aws_kms_external_key" "external" {
  count = var.creation_mode.external ? 1 : 0

  description             = var.description
  policy = var.policy_override_document != null ? var.policy_override_document : data.aws_iam_policy_document.key_policy[0].json
  deletion_window_in_days = 30
  enabled                 = true
  multi_region            = var.multi_region
  key_material_base64     = var.key_material_base64

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Multi-Region replica key (standard origin)
resource "aws_kms_replica_key" "replica_standard" {
  count = var.creation_mode.replica_standard ? 1 : 0

  description             = var.description
  policy = var.policy_override_document != null ? var.policy_override_document : data.aws_iam_policy_document.key_policy[0].json
  enabled                 = true
  primary_key_arn         = var.primary_key_arn

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Multi-Region replica key with external key material
resource "aws_kms_replica_external_key" "replica_external" {
  count = var.creation_mode.replica_external ? 1 : 0

  description             = var.description
  policy = var.policy_override_document != null ? var.policy_override_document : data.aws_iam_policy_document.key_policy[0].json
  enabled                 = true
  primary_key_arn         = var.primary_external_key_arn
  key_material_base64     = var.key_material_base64

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Alias resources
resource "aws_kms_alias" "this" {
  for_each = var.aliases

  name          = each.value.name != null ? each.value.name : null
  name_prefix   = each.value.name == null ? each.value.name_prefix : null
  target_key_id = coalesce(each.value.target_key_arn, var.target_key_arn_for_alias, local.key_id)

  depends_on = [
    aws_kms_key.standard,
    aws_kms_external_key.external,
    aws_kms_replica_key.replica_standard,
    aws_kms_replica_external_key.replica_external
  ]
}

# Grant resources
resource "aws_kms_grant" "this" {
  for_each = { for idx, grant in var.grants : grant.name => grant }

  name              = each.key
  key_id            = local.key_arn
  grantee_principal = each.value.grantee_principal
  operations        = each.value.allowed_operations
  retiring_principal = each.value.retiring_principal

  dynamic "constraints" {
    for_each = each.value.constraints_encryption_context_subset != null ? [1] : []
    content {
      encryption_context_subset = each.value.constraints_encryption_context_subset
    }
  }

  depends_on = [
    aws_kms_key.standard,
    aws_kms_external_key.external,
    aws_kms_replica_key.replica_standard,
    aws_kms_replica_external_key.replica_external
  ]
}

# Outputs
output "key_arn" {
  description = "ARN of the created KMS key"
  value       = local.key_arn
}

output "key_id" {
  description = "Key ID of the created KMS key"
  value       = local.key_id
}

output "alias_arns" {
  description = "Map of alias names to ARNs"
  value = {
    for name, alias in aws_kms_alias.this : name => alias.arn
  }
}

output "grant_tokens" {
  description = "List of grant tokens"
  value       = [for grant in aws_kms_grant.this : grant.grant_token]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "eks-blueprints-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = "10.0.0.0/16"

  azs             = local.azs
  private_subnets = [for i in range(3) : cidrsubnet("10.0.0.0/16", 4, i)]
  public_subnets  = [for i in range(3) : cidrsubnet("10.0.0.0/16", 8, 48 + i)]

  enable_nat_gateway = true
  single_nat_gateway = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

# Ingress rules: allow all traffic from the other cluster's security group
resource "aws_vpc_security_group_ingress_rule" "cluster1_ingress_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_ingress_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

# Egress rules: allow all traffic to the other cluster's security group
resource "aws_vpc_security_group_egress_rule" "cluster1_egress_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_egress_rule" "cluster2_egress_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

# ------------------------------------------------------------------------------
# Terraform configuration
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes that can be used as an alias for the user"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes that are auto-verified"
  type        = list(string)
  default     = []
}

variable "mfa_configuration" {
  description = "MFA configuration setting"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message template"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message template"
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  description = "Verification message template settings (link-based)"
  type        = map(string)
  default = {
    default_email_option = "CONFIRM_WITH_LINK"
    email_message_by_link = "Please click the link below to verify your email address. {##Click Here##}"
    email_subject_by_link = "Verify your email"
  }
}

variable "sms_configuration" {
  description = "SMS configuration parameters"
  type        = map(string)
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "account_recovery_setting" {
  description = "Account recovery mechanisms"
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    { name = "verified_email", priority = 2 },
    { name = "verified_phone_number", priority = 1 }
  ]
}

variable "admin_create_user_config" {
  description = "Admin create user configuration"
  type = object({
    invite_message_template = object({
      email_message = string
      email_subject = string
      sms_message   = string
    })
    allow_admin_create_user_only = bool
  })
  default = {
    invite_message_template = {
      email_message = "Your username is {username} and temporary password is {####}"
      email_subject = "Your temporary password"
      sms_message   = "Your username is {username} and temporary password is {####}"
    }
    allow_admin_create_user_only = false
  }
}

variable "software_token_mfa_enabled" {
  description = "Enable software token MFA"
  type        = bool
  default     = true
}

variable "case_sensitive" {
  description = "Username case sensitivity (null to skip)"
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Device tracking configuration (null to skip)"
  type = object({
    challenge_required_on_new_device      = bool
    device_only_remembered_on_user_prompt = bool
  })
  default = null
}

variable "lambda_config" {
  description = "Lambda trigger configuration"
  type        = map(string)
  default     = {}
}

variable "schema_attributes" {
  description = "Custom schema attributes"
  type = list(object({
    name                = string
    attribute_data_type = string
    required            = bool
    mutable             = bool
    string_attribute_constraints = optional(object({
      min_length = number
      max_length = number
    }))
  }))
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
      string_attribute_constraints = null
    }
  ]
}

variable "client_names" {
  description = "List of User Pool Client names"
  type        = list(string)
  default     = []
}

variable "client_config" {
  description = "Configuration for User Pool Clients"
  type = object({
    generate_secret                    = bool
    access_token_validity              = number
    id_token_validity                  = number
    refresh_token_validity             = number
    access_token_unit                  = string
    id_token_unit                      = string
    refresh_token_unit                 = string
    allowed_oauth_flows_user_pool_client = bool
    enable_token_revocation            = bool
    explicit_auth_flows                = list(string)
    prevent_user_existence_errors      = string
    read_attributes                    = list(string)
    write_attributes                   = list(string)
    callback_urls                      = list(string)
    logout_urls                        = list(string)
    allowed_oauth_flows                = list(string)
    allowed_oauth_scopes               = list(string)
    supported_identity_providers       = list(string)
  })
  default = {
    generate_secret                    = false
    access_token_validity              = 120
    id_token_validity                  = 120
    refresh_token_validity             = 7
    access_token_unit                  = "minutes"
    id_token_unit                      = "minutes"
    refresh_token_unit                 = "days"
    allowed_oauth_flows_user_pool_client = false
    enable_token_revocation            = true
    explicit_auth_flows                = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
    prevent_user_existence_errors      = "LEGACY"
    read_attributes                    = []
    write_attributes                   = []
    callback_urls                      = []
    logout_urls                        = []
    allowed_oauth_flows                = []
    allowed_oauth_scopes               = []
    supported_identity_providers       = []
  }
}

variable "group_name" {
  description = "Name of the Cognito User Group (empty to skip)"
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the group"
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "IAM role ARN for the group (optional)"
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Cognito User Pool domain name (empty to skip)"
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "ACM certificate ARN for the domain (optional)"
  type        = string
  default     = ""
}

variable "create_route53_record" {
  description = "Whether to create a Route53 A-record for the CloudFront distribution"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID (required if create_route53_record is true)"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Cognito User Pool
# ------------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name = var.pool_name

  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  verification_message_template {
    default_email_option = var.verification_message_template["default_email_option"]
    email_message_by_link = var.verification_message_template["email_message_by_link"]
    email_subject_by_link = var.verification_message_template["email_subject_by_link"]
  }

  dynamic "sms_configuration" {
    for_each = var.sms_configuration["external_id"] != "" && var.sms_configuration["sns_caller_arn"] != "" ? [1] : []
    content {
      external_id    = var.sms_configuration["external_id"]
      sns_caller_arn = var.sms_configuration["sns_caller_arn"]
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = var.account_recovery_setting[0].name
      priority = var.account_recovery_setting[0].priority
    }
    recovery_mechanism {
      name     = var.account_recovery_setting[1].name
      priority = var.account_recovery_setting[1].priority
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_config.allow_admin_create_user_only
    invite_message_template {
      email_message = var.admin_create_user_config.invite_message_template.email_message
      email_subject = var.admin_create_user_config.invite_message_template.email_subject
      sms_message   = var.admin_create_user_config.invite_message_template.sms_message
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "username_configuration" {
    for_each = var.case_sensitive != null ? [1] : []
    content {
      case_sensitive = var.case_sensitive
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [1] : []
    content {
      challenge_required_on_new_device      = var.device_configuration.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = var.device_configuration.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) > 0 ? [1] : []
    content {
      dynamic "custom_email_sender" {
        for_each = var.lambda_config["custom_email_sender"] != null ? [1] : []
        content {
          lambda_arn     = var.lambda_config["custom_email_sender"]
          lambda_version = "V1_0"
        }
      }
      pre_sign_up = lookup(var.lambda_config, "pre_sign_up", null)
    }
  }

  dynamic "schema" {
    for_each = var.schema_attributes
    content {
      name                = schema.value.name
      attribute_data_type = schema.value.attribute_data_type
      required            = schema.value.required
      mutable             = schema.value.mutable

      dynamic "string_attribute_constraints" {
        for_each = schema.value.string_attribute_constraints != null ? [1] : []
        content {
          min_length = schema.value.string_attribute_constraints.min_length
          max_length = schema.value.string_attribute_constraints.max_length
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Cognito User Pool Clients
# ------------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "clients" {
  for_each = toset(var.client_names)

  user_pool_id = aws_cognito_user_pool.main.id
  name         = each.value

  generate_secret                    = var.client_config.generate_secret
  access_token_validity              = var.client_config.access_token_validity
  id_token_validity                  = var.client_config.id_token_validity
  refresh_token_validity             = var.client_config.refresh_token_validity
  allowed_oauth_flows_user_pool_client = var.client_config.allowed_oauth_flows_user_pool_client
  enable_token_revocation            = var.client_config.enable_token_revocation
  explicit_auth_flows                = var.client_config.explicit_auth_flows
  prevent_user_existence_errors      = var.client_config.prevent_user_existence_errors
  read_attributes                    = var.client_config.read_attributes
  write_attributes                   = var.client_config.write_attributes
  callback_urls                      = var.client_config.callback_urls
  logout_urls                        = var.client_config.logout_urls
  allowed_oauth_flows                = var.client_config.allowed_oauth_flows
  allowed_oauth_scopes               = var.client_config.allowed_oauth_scopes
  supported_identity_providers       = var.client_config.supported_identity_providers

  token_validity_units {
    access_token  = var.client_config.access_token_unit
    id_token      = var.client_config.id_token_unit
    refresh_token = var.client_config.refresh_token_unit
  }
}

# ------------------------------------------------------------------------------
# Cognito User Group (conditional)
# ------------------------------------------------------------------------------
resource "aws_cognito_user_group" "group" {
  count = var.group_name != "" ? 1 : 0

  user_pool_id = aws_cognito_user_pool.main.id
  name         = var.group_name
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn != "" ? var.group_role_arn : null
}

# ------------------------------------------------------------------------------
# Cognito User Pool Domain (conditional)
# ------------------------------------------------------------------------------
resource "aws_cognito_user_pool_domain" "domain" {
  count = var.domain_name != "" ? 1 : 0

  domain          = var.domain_name
  user_pool_id    = aws_cognito_user_pool.main.id
  certificate_arn = var.domain_certificate_arn != "" ? var.domain_certificate_arn : null
}

# ------------------------------------------------------------------------------
# Route53 Alias Record (conditional)
# ------------------------------------------------------------------------------
resource "aws_route53_record" "cognito_alias" {
  count = var.create_route53_record && var.route53_zone_id != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool_name" {
  description = "Public IPv4 pool for the Elastic IP"
  type        = string
  default     = "amazon"
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = var.igw_name
  }
}

# Subnets
resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnet_c_name
  }
}

# Route Table
resource "aws_route_table" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = var.route_table_name
  }
}

# Default route to Internet Gateway
resource "aws_route" "default" {
  route_table_id         = aws_route_table.this.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

# Associate route table with Subnet A only
resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.this.id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "this" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool_name
}

# NAT Gateway in Subnet B
resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.this.id
  subnet_id     = aws_subnet.subnet_b.id

  depends_on = [aws_internet_gateway.this]

  tags = {
    Name = var.nat_gateway_name
  }
}

# Security Group
resource "aws_security_group" "default" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

# Egress rule allowing all traffic within VPC CIDR
resource "aws_vpc_security_group_egress_rule" "default" {
  security_group_id = aws_security_group.default.id
  cidr_ipv4         = aws_vpc.this.cidr_block
  ip_protocol       = "-1"
}

# Output NAT Gateway public IP
output "nat_gateway_public_ip" {
  value = aws_eip.this.public_ip
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "create" {
  description = "Toggle to create a new Transit Gateway (true) or use an existing one (false)"
  type        = bool
  default     = true
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Transit Gateway"
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Auto accept shared attachments (enable/disable)"
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "DNS support (enable/disable)"
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "VPN ECMP support (enable/disable)"
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "List of CIDR blocks (IPv4 or IPv6) to attach to the Transit Gateway"
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks :
      can(regex("^([0-9]{1,3}\\.){3}[0-9]{1,3}/[0-9]{1,2}$", cidr)) ||
      can(regex("^[0-9a-fA-F:]+/[0-9]{1,3}$", cidr))
    ])
    error_message = "Each element in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR notation."
  }
}

variable "id" {
  description = "ID of an existing Transit Gateway to use when create is false"
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag of an existing Transit Gateway to use when create is false and id is null"
  type        = string
  default     = null
}

variable "route_tables" {
  description = "Map of route tables to create or look up"
  type = map(object({
    create     = bool
    name       = string
    local_tags = map(string)
    id         = optional(string) # Not used in lookup; kept for flexibility
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of AWS principal identifiers (keys) to share the Transit Gateway with via RAM"
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Override name for the RAM resource share; defaults to the Transit Gateway name or 'transit-gateway-share'"
  type        = string
  default     = null
}

variable "tags" {
  description = "Global tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# Look up existing Transit Gateway by id when create=false and id is provided
data "aws_ec2_transit_gateway" "by_id" {
  count = var.create ? 0 : (var.id != null ? 1 : 0)
  id    = var.id
}

# Look up existing Transit Gateway by Name tag when create=false and id is null
data "aws_ec2_transit_gateway" "by_name" {
  count = var.create ? 0 : (var.id == null && var.name != null ? 1 : 0)
  filter {
    name   = "tag:Name"
    values = [var.name]
  }
}

# Look up existing route tables when create=false
data "aws_ec2_transit_gateway_route_table" "existing" {
  for_each = { for k, v in var.route_tables : k => v if !v.create }

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway_id]
  }

  filter {
    name   = "tag:Name"
    values = [each.value.name]
  }
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  # Determine Transit Gateway ID and ARN from creation or lookup
  transit_gateway_id = var.create ? (
    aws_ec2_transit_gateway.this[0].id
  ) : (
    var.id != null ? data.aws_ec2_transit_gateway.by_id[0].id : data.aws_ec2_transit_gateway.by_name[0].id
  )

  transit_gateway_arn = var.create ? (
    aws_ec2_transit_gateway.this[0].arn
  ) : (
    var.id != null ? data.aws_ec2_transit_gateway.by_id[0].arn : data.aws_ec2_transit_gateway.by_name[0].arn
  )

  # Combine route table IDs from created resources and data sources
  route_table_ids = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.existing : k => v.id }
  )
}

# ------------------------------------------------------------------------------
# TRANSIT GATEWAY
# ------------------------------------------------------------------------------

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.tags, {
    Name = var.name != null ? var.name : "transit-gateway"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# ROUTE TABLES
# ------------------------------------------------------------------------------

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.transit_gateway_id
  tags = merge(var.tags, each.value.local_tags, {
    Name = coalesce(each.value.name, var.name)
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# RAM RESOURCE SHARING
# ------------------------------------------------------------------------------

resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, var.name, "transit-gateway-share")
  allow_external_principals = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_share_arn = aws_ram_resource_share.this[0].arn
  resource_arn       = local.transit_gateway_arn
}

resource "aws_ram_principal_association" "this" {
  for_each = length(var.shared_principals) > 0 ? var.shared_principals : {}

  resource_share_arn = aws_ram_resource_share.this[0].arn
  principal          = each.key
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Explicit name for the S3 bucket. When null a DNS compliant name is generated from `corebucket-<4 byte hex>`."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true an additional random suffix is appended to the resolved bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Who pays for the data transfer: BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"

  validation {
    condition     = contains(["BucketOwner", "Requester"], var.request_payer)
    error_message = "request_payer must be either \"BucketOwner\" or \"Requester\"."
  }
}

variable "encryption" {
  description = "Expose the encryption switch of the module interface. Server side encryption is always applied using SSE-KMS."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an existing customer managed KMS key. When empty the module creates its own rotating customer managed key."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable bucket versioning. It is force enabled when object lock or replication rules are supplied."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete on the bucket (requires versioning)."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Delete all objects when the bucket is destroyed."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Optional canned ACL applied through a dedicated aws_s3_bucket_acl resource. Never set inline on aws_s3_bucket."
  type        = string
  default     = null
}

variable "policy" {
  description = "Optional JSON bucket policy document."
  type        = string
  default     = null

  validation {
    condition     = var.policy == null ? true : can(jsondecode(var.policy))
    error_message = "policy must be a valid JSON document."
  }
}

variable "grants" {
  description = "Optional access control policy grants used to build the bucket ACL."
  type = list(object({
    type         = string
    permission   = string
    id           = optional(string)
    uri          = optional(string)
    display_name = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for grant in var.grants : contains(["CanonicalUser", "Group"], grant.type)
    ])
    error_message = "Each grant type must be one of CanonicalUser or Group."
  }

  validation {
    condition = alltrue([
      for grant in var.grants : contains(["READ", "WRITE", "READ_ACP", "WRITE_ACP", "FULL_CONTROL"], grant.permission)
    ])
    error_message = "Each grant permission must be one of READ, WRITE, READ_ACP, WRITE_ACP or FULL_CONTROL."
  }
}

variable "tags" {
  description = "User supplied tags propagated to every taggable resource created by the module."
  type        = map(string)
  default     = {}
}

variable "transfer_acceleration_status" {
  description = "Optional transfer acceleration status: Enabled or Suspended."
  type        = string
  default     = null

  validation {
    condition     = var.transfer_acceleration_status == null ? true : contains(["Enabled", "Suspended"], var.transfer_acceleration_status)
    error_message = "transfer_acceleration_status must be either \"Enabled\" or \"Suspended\"."
  }
}

variable "logging" {
  description = "Optional server access logging configuration. When target_bucket is omitted the module creates and configures a dedicated log delivery bucket."
  type = object({
    target_bucket = optional(string)
    target_prefix = optional(string, "logs/")
  })
  default = null
}

variable "website" {
  description = "Optional static website configuration supporting index/error documents, routing rules or redirect-all-requests."
  type = object({
    index_document = optional(string)
    error_document = optional(string)
    routing_rules  = optional(string)
    redirect_all_requests_to = optional(object({
      host_name = string
      protocol  = optional(string)
    }))
  })
  default = null
}

variable "cors_rules" {
  description = "Optional list of CORS rules."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "Optional list of lifecycle rules."
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    prefix = optional(string)
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      noncurrent_days           = optional(number)
      newer_noncurrent_versions = optional(number)
    }))
    transitions = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })), [])
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = optional(number)
      storage_class   = string
    })), [])
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Optional object lock configuration. When supplied, object lock is enabled at bucket creation and versioning is force enabled."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null

  validation {
    condition     = var.object_lock_configuration == null ? true : contains(["COMPLIANCE", "GOVERNANCE"], var.object_lock_configuration.mode)
    error_message = "object_lock_configuration.mode must be either \"COMPLIANCE\" or \"GOVERNANCE\"."
  }

  validation {
    condition     = var.object_lock_configuration == null ? true : (var.object_lock_configuration.days != null || var.object_lock_configuration.years != null)
    error_message = "object_lock_configuration requires at least one of days or years."
  }
}

variable "replication_rules" {
  description = "Optional cross region replication rules. When supplied the module enables versioning and configures replication."
  type = list(object({
    id       = optional(string)
    status   = optional(string, "Enabled")
    priority = optional(number)
    delete_marker_replication = optional(object({
      status = optional(string, "Enabled")
    }))
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination = object({
      bucket        = string
      storage_class = optional(string)
      account       = optional(string)
      access_control_translation = optional(object({
        owner = string
      }))
      encryption_configuration = optional(object({
        replica_kms_key_id = string
      }))
      metrics = optional(object({
        status = optional(string, "Enabled")
      }))
      replication_time = optional(object({
        status  = optional(string, "Enabled")
        minutes = optional(number, 15)
      }))
    })
  }))
  default = null
}

variable "replication_role" {
  description = "Optional external IAM role ARN used by the replication configuration. When null the module creates its own role."
  type        = string
  default     = null
}

###############################################################################
# Data sources (account-local / static lookups only)
###############################################################################

data "aws_canonical_user_id" "current" {}

###############################################################################
# Random name generation
###############################################################################

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "prefix_suffix" {
  count = var.prefix ? 1 : 0

  byte_length = 4
}

###############################################################################
# Locals
###############################################################################

locals {
  base_bucket_name = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket_suffix.hex}"

  prefixed_bucket_name = var.prefix ? "${local.base_bucket_name}-${random_id.prefix_suffix[0].hex}" : local.base_bucket_name

  sanitized_bucket_name = lower(replace(local.prefixed_bucket_name, "_", "-"))

  bucket_name = length(local.sanitized_bucket_name) > 63 ? substr(local.sanitized_bucket_name, 0, 63) : local.sanitized_bucket_name

  logs_bucket_name = substr("${local.bucket_name}-logs", 0, 63)

  versioning_enabled = var.versioning || var.object_lock_configuration != null || var.replication_rules != null

  mfa_delete_enabled = local.versioning_enabled && var.mfa_delete

  replication_requires_ownership_translation = length([
    for rule in coalesce(var.replication_rules, []) : rule
    if rule.destination.access_control_translation != null
  ]) > 0

  acls_required = var.acl != null || length(var.grants) > 0 || local.replication_requires_ownership_translation

  object_ownership = local.acls_required ? "BucketOwnerPreferred" : "ObjectWriter"

  replication_role_arn = var.replication_role != null ? var.replication_role : one(aws_iam_role.replication[*].arn)

  replication_destination_arns = distinct([
    for rule in coalesce(var.replication_rules, []) : "${rule.destination.bucket}/*"
  ])

  # `encryption` is part of the module interface. Server side encryption is
  # always applied with SSE-KMS; the flag keeps the interface contract while the
  # resolved algorithm remains "aws:kms" in both branches.
  sse_algorithm = var.encryption ? "aws:kms" : "aws:kms"

  # Normalised lifecycle rules: fold the legacy top-level `prefix` and the
  # structured `filter` into a single prefix/tags pair. Tag filtering is later
  # rendered as `tag`/`and` blocks (the provider has no flat tags map).
  lifecycle_rules_normalized = [
    for r in var.lifecycle_rules : {
      id     = r.id
      status = r.status
      prefix = (r.filter != null && r.filter.prefix != null) ? r.filter.prefix : r.prefix
      tags   = r.filter != null ? r.filter.tags : null
      expiration                             = r.expiration
      noncurrent_version_expiration          = r.noncurrent_version_expiration
      transitions                            = r.transitions
      noncurrent_version_transitions         = r.noncurrent_version_transitions
      abort_incomplete_multipart_upload_days = r.abort_incomplete_multipart_upload_days
    }
  ]

  # Normalised replication rules with the same prefix/tags fold.
  replication_rules_normalized = [
    for r in coalesce(var.replication_rules, []) : {
      id                        = r.id
      status                    = r.status
      priority                  = r.priority
      delete_marker_replication = r.delete_marker_replication
      prefix                    = r.filter != null ? r.filter.prefix : null
      tags                      = r.filter != null ? r.filter.tags : null
      destination               = r.destination
    }
  ]
}

###############################################################################
# Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_configuration != null
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Customer managed KMS key (only when no external key ARN is supplied)
###############################################################################

resource "aws_kms_key" "this" {
  count = var.kms_key == "" ? 1 : 0

  description             = "CoreS3 customer managed key for bucket ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count = var.kms_key == "" ? 1 : 0

  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_key != "" ? var.kms_key : one(aws_kms_key.this[*].arn)
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Versioning / ownership
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = local.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = local.mfa_delete_enabled ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = local.object_ownership
  }
}

###############################################################################
# ACL (canned ACL and/or explicit grants)
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = var.acl != null || length(var.grants) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = length(var.grants) > 0 ? null : var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []

    content {
      dynamic "grant" {
        for_each = var.grants

        content {
          permission = grant.value.permission

          grantee {
            type         = grant.value.type
            id           = grant.value.id
            uri          = grant.value.uri
            display_name = grant.value.display_name
          }
        }
      }

      owner {
        id = data.aws_canonical_user_id.current.id
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

###############################################################################
# Bucket policy
###############################################################################

resource "aws_s3_bucket_policy" "this" {
  count = var.policy != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = var.policy

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  routing_rules = var.website != null ? var.website.routing_rules : null

  dynamic "index_document" {
    for_each = var.website != null && var.website.index_document != null ? [var.website.index_document] : []

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website != null && var.website.error_document != null ? [var.website.error_document] : []

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website != null && var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : []

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = redirect_all_requests_to.value.protocol
    }
  }
}

###############################################################################
# Transfer acceleration
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration_status
}

###############################################################################
# Server access logging (target bucket is created in this configuration)
###############################################################################

resource "aws_s3_bucket" "logs" {
  count = var.logging != null ? 1 : 0

  bucket        = local.logs_bucket_name
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logs" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logs]
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging != null && var.logging.target_bucket != null ? var.logging.target_bucket : aws_s3_bucket.logs[0].bucket
  target_prefix = var.logging != null ? var.logging.target_prefix : "logs/"
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

###############################################################################
# Lifecycle management
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = local.lifecycle_rules_normalized

    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = (rule.value.prefix != null || rule.value.tags != null) ? [1] : []

        content {
          prefix = (rule.value.prefix != null && rule.value.tags == null) ? rule.value.prefix : null

          dynamic "tag" {
            for_each = (rule.value.tags != null && rule.value.prefix == null) ? rule.value.tags : {}

            content {
              key   = tag.key
              value = tag.value
            }
          }

          dynamic "and" {
            for_each = (rule.value.tags != null && rule.value.prefix != null) ? [1] : []

            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }
}

###############################################################################
# Object lock
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Replication
###############################################################################

resource "aws_iam_role" "replication" {
  count = var.replication_rules != null && var.replication_role == null ? 1 : 0

  name = substr("CoreS3ReplicationRole_${local.bucket_name}", 0, 64)

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ReplicationAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "s3.amazonaws.com" }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_rules != null && var.replication_role == null ? 1 : 0

  name = substr("CoreS3ReplicationPolicy_${local.bucket_name}", 0, 128)
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
        ]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Sid    = "SourceObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
        ]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Sid    = "DestinationBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = local.replication_destination_arns
      },
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.replication_rules != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = local.replication_rules_normalized

    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != null ? [rule.value.delete_marker_replication] : []

        content {
          status = delete_marker_replication.value.status
        }
      }

      dynamic "filter" {
        for_each = (rule.value.prefix != null || rule.value.tags != null) ? [1] : []

        content {
          prefix = (rule.value.prefix != null && rule.value.tags == null) ? rule.value.prefix : null

          dynamic "tag" {
            for_each = (rule.value.tags != null && rule.value.prefix == null) ? rule.value.tags : {}

            content {
              key   = tag.key
              value = tag.value
            }
          }

          dynamic "and" {
            for_each = (rule.value.tags != null && rule.value.prefix != null) ? [1] : []

            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class
        account       = rule.value.destination.account

        dynamic "access_control_translation" {
          for_each = rule.value.destination.access_control_translation != null ? [rule.value.destination.access_control_translation] : []

          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "encryption_configuration" {
          for_each = rule.value.destination.encryption_configuration != null ? [rule.value.destination.encryption_configuration] : []

          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }

        dynamic "metrics" {
          for_each = rule.value.destination.metrics != null ? [rule.value.destination.metrics] : []

          content {
            status = metrics.value.status
          }
        }

        dynamic "replication_time" {
          for_each = rule.value.destination.replication_time != null ? [rule.value.destination.replication_time] : []

          content {
            status = replication_time.value.status

            time {
              minutes = replication_time.value.minutes
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

variable "projectPrefix" {
  type    = string
  default = "f5-dcec"
}

variable "resourceOwner" {
  type    = string
  default = "f5-user"
}

variable "buildSuffix" {
  type    = string
  default = "YY"
}

variable "map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "awsRegion" {
  type    = string
  default = "us-east-1"
}

variable "awsAz1" {
  type    = string
  default = null
}

variable "awsAz2" {
  type    = string
  default = null
}

variable "vpcMainCidr" {
  type    = string
  default = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  type    = string
  default = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  type    = string
  default = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  type    = string
  default = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  type    = string
  default = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  type    = string
  default = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  type    = string
  default = "10.1.120.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az1 = var.awsAz1 != null ? var.awsAz1 : element(data.aws_availability_zones.available.names, 0)
  az2 = var.awsAz2 != null ? var.awsAz2 : (var.awsAz1 != null ? var.awsAz1 : element(data.aws_availability_zones.available.names, 1))
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name           = "${var.projectPrefix}_vpc_main"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name           = "${var.projectPrefix}_subnet_pub_a"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name           = "${var.projectPrefix}_subnet_pub_b"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = {
    Name           = "${var.projectPrefix}_subnet_mgmt_a"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = {
    Name           = "${var.projectPrefix}_subnet_mgmt_b"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = {
    Name           = "${var.projectPrefix}_subnet_priv_a"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = {
    Name           = "${var.projectPrefix}_subnet_priv_b"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name           = "${var.projectPrefix}_igw_main"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name           = "${var.projectPrefix}_rt_main"
    projectPrefix  = var.projectPrefix
    resourceOwner  = var.resourceOwner
    buildSuffix    = var.buildSuffix
  }
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "name" {
  description = "Name prefix applied to all resources created by this configuration."
  type        = string
  default     = "benchmark"
}

variable "region" {
  description = "AWS region in which to deploy the resources."
  type        = string
  default     = "us-east-1"
}

variable "listener_rule_count" {
  description = "Number of path-based listener rules to create."
  type        = number
  default     = 1
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Name = var.name
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.name
  })
}

resource "aws_subnet" "main" {
  count = length(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.name}-subnet-${count.index}"
  })
}

resource "aws_security_group" "alb" {
  name        = "${var.name}-alb-sg"
  description = "Internal ALB security group scoped to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic to within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-alb-sg"
  })
}

resource "aws_lb" "main" {
  name                       = "${var.name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.main[*].id

  tags = merge(local.common_tags, {
    Name = var.name
  })
}

resource "aws_lb_target_group" "tg" {
  name        = "${var.name}-tg"
  port        = 8080
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-tg"
  })
}

resource "tls_private_key" "key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "cert" {
  private_key_pem = tls_private_key.key.private_key_pem

  subject {
    common_name  = "internal.${var.name}.local"
    organization = var.name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]

  dns_names = [
    "internal.${var.name}.local",
    "${var.name}.local",
  ]
}

resource "aws_acm_certificate" "cert" {
  certificate_body = tls_self_signed_cert.cert.cert_pem
  private_key      = tls_private_key.key.private_key_pem

  tags = merge(local.common_tags, {
    Name = "${var.name}-cert"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.cert.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.tg.arn
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-https-listener"
  })
}

resource "aws_lb_listener_rule" "static" {
  count = var.listener_rule_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.tg.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.name}-rule-static-${count.index}"
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "VPC instance tenancy"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound NACL rules for private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 1024
      to_port     = 65535
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound NACL rules for private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 443
      to_port     = 443
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[0]
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name_prefix}-private-subnet-1"
  }
}

resource "aws_subnet" "private_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[1]
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name_prefix}-private-subnet-2"
  }
}

resource "aws_route_table" "private_1" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-rt-1"
  }
}

resource "aws_route_table" "private_2" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-rt-2"
  }
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private_1.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private_2.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private_1.id, aws_route_table.private_2.id]

  tags = {
    Name = "${var.name_prefix}-s3-gateway-endpoint"
  }
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_no    = ingress.value.rule_number
      protocol   = ingress.value.protocol
      from_port  = ingress.value.from_port
      to_port    = ingress.value.to_port
      cidr_block = ingress.value.cidr_block
      action     = ingress.value.action
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_no    = egress.value.rule_number
      protocol   = egress.value.protocol
      from_port  = egress.value.from_port
      to_port    = egress.value.to_port
      cidr_block = egress.value.cidr_block
      action     = egress.value.action
    }
  }

  tags = {
    Name = "${var.name_prefix}-private-nacl"
  }
}

resource "aws_network_acl_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  network_acl_id = aws_network_acl.private.id
}

resource "aws_network_acl_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  network_acl_id = aws_network_acl.private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# Variables
variable "create" {
  description = "Whether to create the primary SQS queue"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the primary queue. Provide either this or name_prefix."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the primary queue name. Provide either this or name."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queue is FIFO"
  type        = bool
  default     = false
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed server-side encryption. Ignored if kms_master_key_id is provided."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "KMS master key ID for SSE. If set, sqs_managed_sse_enabled is ignored."
  type        = string
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to attach a custom queue policy"
  type        = bool
  default     = false
}

variable "policy_source_document" {
  description = "JSON policy document to use as the source (merged with override)"
  type        = string
  default     = null
}

variable "policy_override_document" {
  description = "JSON policy document to override the source document"
  type        = string
  default     = null
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the DLQ"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  # Determine the base name for the primary queue
  base_name = var.name != null ? var.name : var.name_prefix

  # Append .fifo suffix if FIFO
  main_queue_name = var.fifo_queue ? "${local.base_name}.fifo" : local.base_name

  # DLQ name: base name + "-dlq" + .fifo if FIFO
  dlq_base_name = var.name != null ? "${var.name}-dlq" : (var.name_prefix != null ? "${var.name_prefix}-dlq" : null)
  dlq_name      = var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name

  # SSE configuration
  use_sqs_managed_sse = var.sqs_managed_sse_enabled && var.kms_master_key_id == null
  use_kms             = var.kms_master_key_id != null
}

# Primary SQS queue
resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name       = var.name != null ? local.main_queue_name : null
  name_prefix = var.name == null ? local.main_queue_name : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? true : null

  # SSE
  sqs_managed_sse_enabled = local.use_sqs_managed_sse ? true : null
  kms_master_key_id       = local.use_kms ? var.kms_master_key_id : null

  # Redrive policy (only when DLQ exists)
  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = 5
  }) : null

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Dead-letter queue
resource "aws_sqs_queue" "dlq" {
  count = var.create_dlq ? 1 : 0

  name       = var.name != null ? local.dlq_name : null
  name_prefix = var.name == null ? local.dlq_name : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? true : null

  # Inherit SSE settings from main queue
  sqs_managed_sse_enabled = local.use_sqs_managed_sse ? true : null
  kms_master_key_id       = local.use_kms ? var.kms_master_key_id : null

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Redrive allow policy on the DLQ (separate resource to avoid cycle)
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.main[0].arn]
  })
}

# Queue policy document (conditionally evaluated)
data "aws_iam_policy_document" "main_queue_policy" {
  count = var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.policy_source_document != null ? [var.policy_source_document] : []
  override_policy_documents = var.policy_override_document != null ? [var.policy_override_document] : []

  # Only add a default statement when neither source nor override is provided
  dynamic "statement" {
    for_each = (var.policy_source_document == null && var.policy_override_document == null) ? [1] : []
    content {
      sid    = "DefaultQueuePolicy"
      effect = "Allow"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions   = ["sqs:SendMessage"]
      resources = [try(aws_sqs_queue.main[0].arn, "*")]
    }
  }
}

# Attach queue policy to primary queue
resource "aws_sqs_queue_policy" "main" {
  count = var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].id
  policy    = data.aws_iam_policy_document.main_queue_policy[0].json
}

# Outputs
output "primary_queue_arn" {
  description = "ARN of the primary SQS queue"
  value       = try(aws_sqs_queue.main[0].arn, null)
}

output "primary_queue_url" {
  description = "URL of the primary SQS queue"
  value       = try(aws_sqs_queue.main[0].id, null)
}

output "dead_letter_queue_arn" {
  description = "ARN of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "URL of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "backup_name" {
  description = "Name used to identify the backup vault, backup plan and selections."
  type        = string
  default     = "aws-backup"
}

variable "account_type" {
  description = "Account pattern type: 'workload' provisions backup plan/role, 'backup' provisions vault only."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional customer-managed KMS key ARN used to encrypt the backup vault."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON access policy applied to the backup vault."
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention in days. When set, a vault lock is created."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Maximum retention in days for the vault lock."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Number of days the vault lock remains changeable."
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to enable vault notifications."
  type        = bool
  default     = false
}

variable "backup_vault_events" {
  description = "Backup vault events routed to the SNS topic."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "sns_topic_arn" {
  description = "SNS topic ARN used as the notification target."
  type        = string
  default     = null
}

variable "backup_schedule" {
  description = "Cron/rate expression for the backup rule schedule."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "copy_action_destination_vault_arn" {
  description = "Destination vault ARN for the cross-region/cross-account copy action. When null, no copy action is created."
  type        = string
  default     = null
}

variable "copy_action_cold_storage_after" {
  description = "Days after creation to move copied recovery points to cold storage."
  type        = number
  default     = null
}

variable "copy_action_delete_after" {
  description = "Days after creation to delete copied recovery points."
  type        = number
  default     = null
}

variable "selection_resources" {
  description = "Explicit resource ARNs for the resource-based backup selection."
  type        = list(string)
  default     = []
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  is_workload = var.account_type == "workload"

  tags = {
    Name        = var.backup_name
    AccountType = var.account_type
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# IAM trust policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowBackupServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# Backup vault
# ---------------------------------------------------------------------------

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

# ---------------------------------------------------------------------------
# Workload account resources
# ---------------------------------------------------------------------------

resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0

  name               = "aws-backup-${var.backup_name}"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = local.is_workload ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "this" {
  count = local.is_workload ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = "plan-${var.backup_name}-backup-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.backup_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      Backup = "true"
      Name   = var.backup_name
    }

    dynamic "copy_action" {
      for_each = var.copy_action_destination_vault_arn != null ? [1] : []
      content {
        destination_vault_arn = var.copy_action_destination_vault_arn

        lifecycle {
          cold_storage_after = var.copy_action_cold_storage_after
          delete_after       = var.copy_action_delete_after
        }
      }
    }
  }

  tags = local.tags
}

resource "aws_backup_selection" "tags" {
  count = local.is_workload ? 1 : 0

  name         = "plan-${var.backup_name}-backup-tags"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.this[0].id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resources" {
  count = local.is_workload && length(var.selection_resources) > 0 ? 1 : 0

  name         = "plan-${var.backup_name}-backup-resources"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.this[0].id
  resources    = var.selection_resources
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "config_name" {
  description = "Optional name for the Config stack; defaults to a random pet name"
  type        = string
  default     = null
}

resource "random_pet" "config_pet" {
  length = 2
}

locals {
  config_name_final = coalesce(var.config_name, random_pet.config_pet.id)
  role_name         = "${local.config_name_final}-config-role"
  sns_topic_name    = "${local.config_name_final}-config-notifications"
  bucket_name       = "config-snapshots-${random_pet.config_pet.id}"
}

data "aws_caller_identity" "current" {}

# IAM Role for AWS Config
resource "aws_iam_role" "config" {
  name = local.role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach AWS managed policy for Config
resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

# Inline policy for S3 PutObject
resource "aws_iam_role_policy" "config_s3" {
  name = "config-s3-put"
  role = aws_iam_role.config.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "s3:PutObject"
        Resource = [
          aws_s3_bucket.config_snapshot.arn,
          "${aws_s3_bucket.config_snapshot.arn}/*"
        ]
      }
    ]
  })
}

# Inline policy for SNS Publish
resource "aws_iam_role_policy" "config_sns" {
  name = "config-sns-publish"
  role = aws_iam_role.config.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sns:Publish"
        Resource = aws_sns_topic.config.arn
      }
    ]
  })
}

# S3 Bucket for Config snapshots
resource "aws_s3_bucket" "config_snapshot" {
  bucket        = local.bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "config_snapshot" {
  bucket                  = aws_s3_bucket.config_snapshot.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Customer-managed KMS key for S3 bucket encryption
resource "aws_kms_key" "config_s3" {
  description             = "Config S3 encryption key"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Config IAM role to use the key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.config.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "config_s3" {
  name          = "alias/config-s3-key"
  target_key_id = aws_kms_key.config_s3.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_s3.arn
    }
  }
  depends_on = [aws_kms_key.config_s3]
}

resource "aws_s3_bucket_versioning" "config_snapshot" {
  bucket = aws_s3_bucket.config_snapshot.id
  versioning_configuration {
    status = "Enabled"
  }
}

# KMS key for SNS topic encryption
resource "aws_kms_key" "config_sns" {
  description             = "Config SNS key"
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Config Service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow Config IAM role to use the key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.config.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "config_sns" {
  name          = "alias/config-sns-key"
  target_key_id = aws_kms_key.config_sns.key_id
}

# SNS Topic for Config notifications
resource "aws_sns_topic" "config" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.config_sns.arn
}

# SNS Topic policy to allow Config service and IAM role to publish
resource "aws_sns_topic_policy" "config" {
  arn = aws_sns_topic.config.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow Config Service to publish"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.config.arn
      },
      {
        Sid    = "Allow Config IAM role to publish"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.config.arn
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.config.arn
      }
    ]
  })
}

# AWS Config Configuration Recorder
resource "aws_config_configuration_recorder" "config" {
  name     = "${local.config_name_final}-recorder"
  role_arn = aws_iam_role.config.arn
  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

# AWS Config Delivery Channel
resource "aws_config_delivery_channel" "config" {
  name           = "${local.config_name_final}-delivery-channel"
  s3_bucket_name = aws_s3_bucket.config_snapshot.bucket
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.config.arn
  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }
  depends_on = [
    aws_config_configuration_recorder.config
  ]
}

# Managed Config Rules
resource "aws_config_config_rule" "cloudtrail_enabled" {
  name = "cloudtrail-enabled"
  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name = "iam-pw-policy"
  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_vpc" {
  name = "ec2-vpc"
  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name = "root-mfa-enabled"
  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name = "acm-expiration-check"
  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "ebs-inuse-check"
  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "ec2-imdsv2-check"
  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name = "rds-encrypted"
  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private" {
  name = "rds-private"
  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "rds-private-snapshots"
  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"
  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }
  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })
  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }
  maximum_execution_frequency = "TwentyFour_Hours"
  depends_on = [aws_config_configuration_recorder.config]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy" "agent_policy" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "failback_policy" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "conversion_server_policy" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "recovery_instance_policy" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "replication_server_policy" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

# Service roles under /service-role/

resource "aws_iam_role" "agent_role" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "failback_role" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "i-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "conversion_server_role" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "recovery_instance_role" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "replication_server_role" {
  name = "AWSElasticDisasterRecoveryReplicationServerRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "recovery_instance_with_launch_actions_role" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Policy attachments for service roles

resource "aws_iam_role_policy_attachment" "agent_policy_attachment" {
  role       = aws_iam_role.agent_role.name
  policy_arn = data.aws_iam_policy.agent_policy.arn
}

resource "aws_iam_role_policy_attachment" "failback_policy_attachment" {
  role       = aws_iam_role.failback_role.name
  policy_arn = data.aws_iam_policy.failback_policy.arn
}

resource "aws_iam_role_policy_attachment" "conversion_server_policy_attachment" {
  role       = aws_iam_role.conversion_server_role.name
  policy_arn = data.aws_iam_policy.conversion_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_policy_attachment" {
  role       = aws_iam_role.recovery_instance_role.name
  policy_arn = data.aws_iam_policy.recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "replication_server_policy_attachment" {
  role       = aws_iam_role.replication_server_role.name
  policy_arn = data.aws_iam_policy.replication_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_policy_attachment" {
  role       = aws_iam_role.recovery_instance_with_launch_actions_role.name
  policy_arn = data.aws_iam_policy.recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_ssm_attachment" {
  role       = aws_iam_role.recovery_instance_with_launch_actions_role.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance_core.arn
}

# Initializer role (root path)

resource "aws_iam_role" "initializer_role" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:userid" = data.aws_caller_identity.current.user_id
          }
        }
      }
    ]
  })
}

# Custom InitializePolicy

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  description = "Policy for DRS initializer role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "InitializeService"
        Effect = "Allow"
        Action = "drs:InitializeService"
        Resource = "*"
      },
      {
        Sid    = "CreateInstanceProfile"
        Effect = "Allow"
        Action = "iam:CreateInstanceProfile"
        Resource = "*"
      },
      {
        Sid    = "PassRoleToEC2AndDRS"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = ["ec2.amazonaws.com", "drs.amazonaws.com"]
          }
        }
      },
      {
        Sid    = "CreateServiceLinkedRoleForDRS"
        Effect = "Allow"
        Action = "iam:CreateServiceLinkedRole"
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = "drs.amazonaws.com"
          }
        }
      },
      {
        Sid    = "FullEC2Actions"
        Effect = "Allow"
        Action = "ec2:*"
        Resource = "*"
      },
      {
        Sid    = "AttachDRSManagedPolicies"
        Effect = "Allow"
        Action = "iam:AttachRolePolicy"
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:PolicyARN" = [
              data.aws_iam_policy.agent_policy.arn,
              data.aws_iam_policy.failback_policy.arn,
              data.aws_iam_policy.conversion_server_policy.arn,
              data.aws_iam_policy.recovery_instance_policy.arn,
              data.aws_iam_policy.replication_server_policy.arn
            ]
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "initialize_policy_attachment" {
  role       = aws_iam_role.initializer_role.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names = data.aws_availability_zones.available.names
}

# External VPC
resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  ingress = []
  egress  = []
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
  }

  egress {
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
  }

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_subnet" "external_subnet0" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.0.0/24"
  availability_zone = local.az_names[0]

  tags = {
    Name = "Subnet0-1a"
  }
}

resource "aws_subnet" "external_subnet1" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.1.0/24"
  availability_zone = local.az_names[1]

  tags = {
    Name = "Subnet1-1b"
  }
}

resource "aws_subnet" "external_subnet2" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.2.0/24"
  availability_zone = local.az_names[2]

  tags = {
    Name = "Subnet2-1c"
  }
}

resource "aws_subnet" "external_subnet3" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.3.0/24"
  availability_zone = local.az_names[3]

  tags = {
    Name = "Subnet3-1d"
  }
}

resource "aws_internet_gateway" "external_gw" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "External GW"
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external_gw.id
  }

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet0" {
  subnet_id      = aws_subnet.external_subnet0.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet1" {
  subnet_id      = aws_subnet.external_subnet1.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet2" {
  subnet_id      = aws_subnet.external_subnet2.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet3" {
  subnet_id      = aws_subnet.external_subnet3.id
  route_table_id = aws_route_table.external.id
}

# Internal VPC
resource "aws_vpc" "internal" {
  cidr_block       = "10.40.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  ingress = []
  egress  = []
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  egress {
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
  }

  egress {
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
  }

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_subnet" "internal_subnet0" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.0.0/24"
  availability_zone = local.az_names[0]

  tags = {
    Name = "Subnet0-1a"
  }
}

resource "aws_subnet" "internal_subnet1" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.1.0/24"
  availability_zone = local.az_names[1]

  tags = {
    Name = "Subnet1-1b"
  }
}

resource "aws_subnet" "internal_subnet2" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.2.0/24"
  availability_zone = local.az_names[2]

  tags = {
    Name = "Subnet2-1c"
  }
}

resource "aws_subnet" "internal_subnet3" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = "10.40.3.0/24"
  availability_zone = local.az_names[3]

  tags = {
    Name = "Subnet3-1d"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

############################################################
# Data Sources (static provider metadata only)
############################################################

data "aws_availability_zones" "available" {
  state = "available"
}

############################################################
# Variables
############################################################

variable "resource_prefix" {
  description = "Prefix applied to all resource names and tags."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN to use for the HTTPS listener. When null a self-signed certificate is generated and imported."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional override for the n8n WEBHOOK_URL. When null the public CloudFront endpoint is used."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Number of n8n tasks to run."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image for the n8n application."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider to use (FARGATE or FARGATE_SPOT)."
  type        = string
  default     = "FARGATE_SPOT"
}

############################################################
# Locals
############################################################

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  webhook_url = coalesce(var.url, "https://${aws_cloudfront_distribution.n8n.domain_name}")

  tags = {
    Project   = var.resource_prefix
    ManagedBy = "terraform"
  }
}

############################################################
# Networking - VPC
############################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-vpc"
  })
}

############################################################
# Private Subnets
############################################################

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-private-${count.index + 1}"
  })
}

############################################################
# Public Subnets
#
# NOTE: map_public_ip_on_launch intentionally left at its
# default (false) so instances launched here do not receive
# a public IP by default (AVD-AWS-0164). Fargate task public
# IPs are governed by the ECS service assign_public_ip flag.
############################################################

resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-public-${count.index + 1}"
  })
}

############################################################
# Internet Gateway & Route Tables
############################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

############################################################
# Security Groups
############################################################

resource "aws_security_group" "alb" {
  name        = "${var.resource_prefix}-alb"
  description = "Allow inbound HTTP/HTTPS to the load balancer."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-alb"
  })
}

resource "aws_security_group" "ecs_tasks" {
  name        = "${var.resource_prefix}-ecs-tasks"
  description = "Allow container traffic only from the load balancer."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n container port from the load balancer"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-ecs-tasks"
  })
}

resource "aws_security_group" "efs" {
  name        = "${var.resource_prefix}-efs"
  description = "Allow NFS traffic from within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-efs"
  })
}

############################################################
# EFS - Persistent storage
############################################################

resource "aws_efs_file_system" "n8n" {
  creation_token = "${var.resource_prefix}-efs"
  encrypted      = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-efs"
  })
}

resource "aws_efs_mount_target" "n8n" {
  count           = 3
  file_system_id  = aws_efs_file_system.n8n.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-ap"
  })
}

############################################################
# Self-signed certificate (only when no certificate is supplied)
############################################################

resource "tls_private_key" "n8n" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "n8n" {
  count           = var.certificate_arn == null ? 1 : 0
  private_key_pem = tls_private_key.n8n[0].private_key_pem

  subject {
    common_name  = "${var.resource_prefix}.local"
    organization = "n8n"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  private_key      = tls_private_key.n8n[0].private_key_pem
  certificate_body = tls_self_signed_cert.n8n[0].cert_pem

  lifecycle {
    create_before_destroy = true
  }
}

############################################################
# Internal Application Load Balancer
#
# internal = true (AVD-AWS-0053): the load balancer only has
# private addresses; public webhook ingress is provided by the
# CloudFront distribution below. Placement in the public
# subnets is preserved per the original request.
############################################################

resource "aws_lb" "n8n" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-alb"
  })
}

resource "aws_lb_target_group" "n8n" {
  name                 = "${var.resource_prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    matcher             = "200"
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-tg"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.n8n.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = coalesce(var.certificate_arn, one(aws_acm_certificate.self_signed[*].arn))

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-https"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.n8n.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-http"
  })
}

############################################################
# CloudFront as the public edge (custom origin -> internal ALB)
############################################################

resource "aws_cloudfront_distribution" "n8n" {
  enabled = true
  comment = "${var.resource_prefix} public webhook edge"

  origin {
    domain_name = aws_lb.n8n.dns_name
    origin_id   = "${var.resource_prefix}-origin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    target_origin_id       = "${var.resource_prefix}-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true
    min_ttl                = 0
    default_ttl            = 0
    max_ttl                = 0

    forwarded_values {
      query_string = true
      headers      = ["*"]
      cookies {
        forward = "all"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  web_acl_id = aws_wafv2_web_acl.n8n.arn

  tags = merge(local.tags, {
    Name = var.resource_prefix
  })
}

############################################################
# WAF protecting the public CloudFront edge
############################################################

resource "aws_wafv2_web_acl" "n8n" {
  name  = "${var.resource_prefix}-waf"
  scope = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "common-rule-set"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${var.resource_prefix}-waf"
    sampled_requests_enabled   = true
  }

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-waf"
  })
}

resource "aws_cloudwatch_log_group" "waf" {
  name              = "aws-waf-logs-${var.resource_prefix}"
  retention_in_days = 1

  tags = merge(local.tags, {
    Name = "aws-waf-logs-${var.resource_prefix}"
  })
}

resource "aws_wafv2_web_acl_logging_configuration" "n8n" {
  log_destination_configs = [aws_cloudwatch_log_group.waf.arn]
  resource_arn            = aws_wafv2_web_acl.n8n.arn
}

############################################################
# CloudWatch Logging
############################################################

resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.resource_prefix}-logs"
  retention_in_days = 1

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-logs"
  })
}

############################################################
# ECS Cluster
############################################################

resource "aws_ecs_cluster" "n8n" {
  name = var.resource_prefix

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = merge(local.tags, {
    Name = var.resource_prefix
  })
}

resource "aws_ecs_cluster_capacity_providers" "n8n" {
  cluster_name       = aws_ecs_cluster.n8n.name
  capacity_providers = ["FARGATE", "FARGATE_SPOT"]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

############################################################
# IAM - Task & Execution Roles
############################################################

resource "aws_iam_role" "task" {
  name = "${var.resource_prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-task-role"
  })
}

resource "aws_iam_role" "execution" {
  name = "${var.resource_prefix}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${var.resource_prefix}-execution-role"
  })
}

resource "aws_iam_role_policy" "task" {
  name = "${var.resource_prefix}-task-logs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:log-stream:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "execution" {
  name = "${var.resource_prefix}-execution-logs"
  role = aws_iam_role.execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:log-stream:*"
        ]
      }
    ]
  })
}

############################################################
# ECS Task Definition
############################################################

resource "aws_ecs_task_definition" "n8n" {
  family                   = var.resource_prefix
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  task_role_arn            = aws_iam_role.task.arn
  execution_role_arn       = aws_iam_role.execution.arn

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.n8n.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = var.resource_prefix
        }
      }
    }
  ])

  tags = merge(local.tags, {
    Name = var.resource_prefix
  })
}

############################################################
# ECS Service
############################################################

resource "aws_ecs_service" "n8n" {
  name            = var.resource_prefix
  cluster         = aws_ecs_cluster.n8n.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
    aws_efs_mount_target.n8n,
  ]

  tags = merge(local.tags, {
    Name = var.resource_prefix
  })
}

############################################################
# Outputs
############################################################

output "alb_dns_name" {
  description = "DNS name of the internal load balancer fronting n8n."
  value       = aws_lb.n8n.dns_name
}

output "cloudfront_domain_name" {
  description = "Public CloudFront domain name serving n8n."
  value       = aws_cloudfront_distribution.n8n.domain_name
}

output "webhook_base_url" {
  description = "Public HTTPS base URL for n8n webhooks."
  value       = "https://${aws_cloudfront_distribution.n8n.domain_name}"
}

output "efs_file_system_id" {
  description = "ID of the EFS file system used for n8n persistent data."
  value       = aws_efs_file_system.n8n.id
}

