terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "create" {
  description = "Global toggle to create all resources"
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function (default is a placeholder, override for real deployments)"
  type        = string
  default     = "my-lambda-function"
}

variable "alias_name" {
  description = "Alias of the Lambda function (default is a placeholder, override for real deployments)"
  type        = string
  default     = "prod"
}

variable "current_version" {
  description = "Current version of the Lambda function (default is a placeholder, override for real deployments)"
  type        = string
  default     = "$LATEST"
}

variable "target_version" {
  description = "Target version for the deployment (default is a placeholder, override for real deployments)"
  type        = string
  default     = "1"
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function for BeforeAllowTraffic hook"
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function for AfterAllowTraffic hook"
  type        = string
  default     = ""
}

variable "app_name" {
  description = "Name of the CodeDeploy application"
  type        = string
  default     = "lambda-app"
}

variable "create_app" {
  description = "Whether to create the CodeDeploy application"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use an existing CodeDeploy application"
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group"
  type        = string
  default     = "lambda-deployment-group"
}

variable "create_deployment_group" {
  description = "Whether to create the deployment group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use an existing deployment group"
  type        = bool
  default     = false
}

variable "deployment_config_name" {
  description = "Deployment configuration name"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_codedeploy_role" {
  description = "Whether to create the IAM role for CodeDeploy"
  type        = bool
  default     = true
}

variable "codedeploy_service_principal" {
  description = "Service principal for CodeDeploy"
  type        = string
  default     = "codedeploy.amazonaws.com"
}

variable "attach_hooks_policy" {
  description = "Whether to attach inline policy for Lambda invoke on hooks"
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach inline policy for SNS publish on triggers"
  type        = bool
  default     = false
}

variable "trigger_configuration" {
  description = "List of trigger configurations for the deployment group"
  type = list(object({
    trigger_name       = optional(string)
    trigger_events     = list(string)
    trigger_target_arn = string
  }))
  default = []
}

variable "alarm_configuration" {
  description = "List of CloudWatch alarm names to monitor"
  type        = list(string)
  default     = []
}

variable "create_deployment" {
  description = "Whether to generate deployment script and optionally run it"
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI command to use"
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Sleep interval in seconds between deployment status checks"
  type        = number
  default     = 5
}

variable "save_deploy_script" {
  description = "Whether to save the deployment script locally"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Whether to execute the deployment via null_resource provisioner"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  # Determine the application name (created or existing)
  app_name = var.create_app && !var.use_existing_app ? aws_codedeploy_app.lambda_app[0].name : var.app_name

  # Determine the deployment group name (created or existing)
  deployment_group_name = var.create_deployment_group && !var.use_existing_deployment_group ? aws_codedeploy_deployment_group.lambda_group[0].deployment_group_name : var.deployment_group_name

  # Build the AppSpec JSON
  appspec = jsonencode({
    version = 0
    Resources = [
      {
        myLambdaFunction = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
    Hooks = [
      for h in [
        var.before_allow_traffic_hook_arn != "" ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : null,
        var.after_allow_traffic_hook_arn != "" ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : null,
      ] : h if h != null
    ]
  })

  # Shell script content for deployment (inline heredoc)
  deploy_script_content = <<-EOF
#!/bin/bash
set -e
DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
  --application-name ${local.app_name} \
  --deployment-group-name ${local.deployment_group_name} \
  --revision '{"revisionType":"AppSpecContent","appSpecContent":{"content":"${replace(local.appspec, "\"", "\\\"")}"}}' \
  --query 'deploymentId' --output text)
echo "Deployment ID: $DEPLOYMENT_ID"
while true; do
  STATUS=$(${var.aws_cli_command} deploy get-deployment --deployment-id $DEPLOYMENT_ID --query 'deploymentInfo.status' --output text)
  echo "Status: $STATUS"
  if [ "$STATUS" = "Succeeded" ] || [ "$STATUS" = "Failed" ] || [ "$STATUS" = "Stopped" ]; then
    break
  fi
  sleep ${var.get_deployment_sleep_timer}
done
EOF
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "codedeploy_assume_role" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = [var.codedeploy_service_principal]
    }
  }
}

# ------------------------------------------------------------------------------
# IAM ROLE AND POLICIES
# ------------------------------------------------------------------------------

resource "aws_iam_role" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name               = "codedeploy-lambda-role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role[0].json
}

# Inline policy with equivalent permissions to AWSCodeDeployRoleForLambda
resource "aws_iam_role_policy" "codedeploy_lambda_inline" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name   = "codedeploy-lambda-policy"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.codedeploy_lambda_inline[0].json
}

data "aws_iam_policy_document" "codedeploy_lambda_inline" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    actions = [
      "codedeploy:*",
      "lambda:InvokeFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateAlias",
      "iam:PassRole"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "hooks_policy" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && (var.before_allow_traffic_hook_arn != "" || var.after_allow_traffic_hook_arn != "") ? 1 : 0

  name   = "codedeploy-hooks-invoke"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.hooks_policy[0].json
}

data "aws_iam_policy_document" "hooks_policy" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && (var.before_allow_traffic_hook_arn != "" || var.after_allow_traffic_hook_arn != "") ? 1 : 0

  statement {
    actions   = ["lambda:InvokeFunction"]
    resources = compact([var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn])
  }
}

resource "aws_iam_role_policy" "triggers_policy" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.trigger_configuration) > 0 ? 1 : 0

  name   = "codedeploy-triggers-sns"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.triggers_policy[0].json
}

data "aws_iam_policy_document" "triggers_policy" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.trigger_configuration) > 0 ? 1 : 0

  statement {
    actions   = ["sns:Publish"]
    resources = [for t in var.trigger_configuration : t.trigger_target_arn]
  }
}

# ------------------------------------------------------------------------------
# CODEDEPLOY APPLICATION
# ------------------------------------------------------------------------------

resource "aws_codedeploy_app" "lambda_app" {
  count = var.create && var.create_app && !var.use_existing_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"
}

# ------------------------------------------------------------------------------
# CODEDEPLOY DEPLOYMENT GROUP
# ------------------------------------------------------------------------------

resource "aws_codedeploy_deployment_group" "lambda_group" {
  count = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0

  app_name              = local.app_name
  deployment_group_name = var.deployment_group_name
  service_role_arn      = var.create_codedeploy_role ? aws_iam_role.codedeploy[0].arn : null
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarm_configuration) > 0 ? [1] : []
    content {
      alarms  = var.alarm_configuration
      enabled = true
    }
  }

  dynamic "trigger_configuration" {
    for_each = { for idx, t in var.trigger_configuration : idx => t }
    content {
      trigger_name     = "deployment-trigger-${var.deployment_group_name}-${trigger_configuration.key}"
      trigger_events   = trigger_configuration.value.trigger_events
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
    }
  }

  depends_on = [aws_codedeploy_app.lambda_app]
}

# ------------------------------------------------------------------------------
# DEPLOYMENT SCRIPT AND EXECUTION
# ------------------------------------------------------------------------------

resource "random_uuid" "force_deploy" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0
}

resource "local_file" "deploy_script" {
  count = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0

  filename = "${path.module}/deploy_lambda.sh"
  content  = local.deploy_script_content
}

resource "null_resource" "run_deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    force_deploy = random_uuid.force_deploy[0].result
  }

  provisioner "local-exec" {
    command = local.deploy_script_content
  }

  depends_on = [
    aws_codedeploy_app.lambda_app,
    aws_codedeploy_deployment_group.lambda_group,
    aws_iam_role.codedeploy,
    aws_iam_role_policy.codedeploy_lambda_inline,
    aws_iam_role_policy.hooks_policy,
    aws_iam_role_policy.triggers_policy,
  ]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "internal_domain_name" {
  description = "Internal DNS domain name used for the VPC DHCP options and the private Route 53 hosted zone."
  type        = string
  default     = "internal"
}

variable "admin_ssh_cidrs" {
  description = "List of administrator CIDR blocks permitted to reach the Home SSH security group over TCP/22."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "environment" {
  description = "Non-infrastructure environment label applied to every resource as a tag."
  type        = string
  default     = "dev"
}

variable "owner" {
  description = "Non-infrastructure owner label applied to every resource as a tag."
  type        = string
  default     = "platform-team"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Availability Zones
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# VPC, Internet Gateway, DHCP Options
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "ig"
  })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain_name
  domain_name_servers = ["AmazonProvidedDNS", "8.8.8.8"]

  tags = merge(local.common_tags, {
    Name = "main-dhcp-options"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

###############################################################################
# Private Route 53 Hosted Zone for the internal domain
###############################################################################

resource "aws_route53_zone" "internal" {
  name = var.internal_domain_name

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = merge(local.common_tags, {
    Name = var.internal_domain_name
  })
}

###############################################################################
# Subnets (none auto-assign public IPs on launch)
###############################################################################

resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "reserved"
  })
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "sandbox"
  })
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "web"
  })
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[3]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "database"
  })
}

resource "aws_subnet" "gameserver" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/22"
  availability_zone       = data.aws_availability_zones.available.names[4]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "gameserver"
  })
}

