###############################################################################
# Security Groups
###############################################################################

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from administrator CIDRs and from group members; egress restricted to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from administrator CIDR blocks"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_ssh_cidrs
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restrict all outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Home SSH"
  })
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from the VPC CIDR and from group members; egress restricted to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restrict all outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Packer SSH"
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Conditional IAM account alias data source
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

# Random suffix generator (conditional)
resource "random_id" "suffix" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

# Bucket name construction
locals {
  alias_prefix  = var.use_account_alias_prefix && try(data.aws_iam_account_alias.current[0].account_alias, "") != "" ? "${data.aws_iam_account_alias.current[0].account_alias}-" : ""
  random_suffix = var.use_random_suffix ? random_id.suffix[0].hex : ""
  bucket_name   = "${local.alias_prefix}${var.bucket_name}${local.random_suffix}"
}

# S3 Bucket
resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Public access block (conditional)
resource "aws_s3_bucket_public_access_block" "main" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Versioning
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    bucket_key_enabled = var.bucket_key_enabled

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }
  }
}

# Bucket policy
data "aws_iam_policy_document" "bucket_policy" {
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []

  statement {
    sid       = "DenyNonTLS"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "AllowS3ServiceInventoryAnalytics"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = [
      "${aws_s3_bucket.main.arn}/_AWSBucketInventory/*",
      "${aws_s3_bucket.main.arn}/_AWSBucketAnalytics/*"
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    id     = "abort_incomplete_multipart"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent_version_transition"
    status = "Enabled"

    filter {
      object_size_greater_than = 128000
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []
    content {
      id     = "analytics_expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketAnalytics/"
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []
    content {
      id     = "inventory_expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }
}

# Analytics configuration (conditional)
resource "aws_s3_bucket_analytics_configuration" "main" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.main.id
  name   = "BucketAnalytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.main.arn
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }
}

# Inventory configuration (conditional)
resource "aws_s3_bucket_inventory" "main" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.main.id
  name   = "BucketInventory"

  included_object_versions = "All"
  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.main.arn
      prefix     = "_AWSBucketInventory/"
    }
  }
}

# Logging (conditional)
resource "aws_s3_bucket_logging" "main" {
  count = var.logging_bucket != null ? 1 : 0

  bucket = aws_s3_bucket.main.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.main.id}/"
}

# Transfer acceleration (conditional)
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.main.id
  status = var.transfer_acceleration
}

# Bucket ACL (conditional)
resource "aws_s3_bucket_acl" "main" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.main.id
  acl    = var.s3_bucket_acl
}

# CORS configuration (conditional)
resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, [])
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the AWS IAM account alias"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Append a random hex suffix to the bucket name"
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Custom JSON bucket policy to extend (optional)"
  type        = string
  default     = ""
}

variable "enable_s3_public_access_block" {
  description = "Enable S3 public access block settings"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "KMS master key ID for SSE-KMS encryption. If null, uses AES256."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for SSE-KMS"
  type        = bool
  default     = false
}

variable "enable_versioning" {
  description = "Enable bucket versioning"
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if not empty"
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Enable storage class analytics"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable bucket inventory reports"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Target bucket name for server access logs (optional)"
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (Enabled / Suspended). Null to disable."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Bucket ACL (e.g., private, public-read). Null to use bucket policy default."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rule objects. Each must include allowed_methods, allowed_origins. Optionally allowed_headers, expose_headers, max_age_seconds."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

################################################################################
# Variables
################################################################################

variable "name" {
  description = "Name of the S3 bucket. Mutually exclusive with name_prefix."
  type        = string
  default     = null

  validation {
    condition     = var.name == null || length(var.name) <= 63
    error_message = "The S3 bucket name must be 63 characters or fewer."
  }
}

variable "name_prefix" {
  description = "Prefix used to generate a unique S3 bucket name. Mutually exclusive with name."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null || length(var.name_prefix) <= 37
    error_message = "The S3 bucket name prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "Destroy the bucket and all objects within it even when it is not empty."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket. ACLs are only created when set to ObjectWriter."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition = contains([
      "BucketOwnerEnforced",
      "ObjectWriter",
      "BucketOwnerPreferred",
    ], var.object_ownership)
    error_message = "object_ownership must be one of BucketOwnerEnforced, ObjectWriter or BucketOwnerPreferred."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies on the bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs placed on the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies on the bucket."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of a KMS CMK used for default bucket encryption. When null, AES256 is used."
  type        = string
  default     = null
}

variable "versioning_enabled" {
  description = "Whether bucket versioning is Enabled. When false, versioning is Suspended."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional JSON encoded bucket policy. Its statements are merged with the enforced statements."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "List of source bucket ARNs that are allowed to deliver server access logs into this bucket."
  type        = list(string)
  default     = []
}

variable "enable_eventbridge_notifications" {
  description = "Enable Amazon EventBridge notifications for the bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Name of the bucket that receives the server access logs of this bucket."
  type        = string
  default     = null
}

variable "logging_prefix" {
  description = "Prefix applied to the server access log objects delivered to the target bucket."
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket. Cannot be enabled on a server access log source bucket."
  type        = bool
  default     = false
}

variable "object_lock_retention_mode" {
  description = "Default Object Lock retention mode (GOVERNANCE or COMPLIANCE)."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_retention_mode)
    error_message = "object_lock_retention_mode must be either GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_retention_days" {
  description = "Default Object Lock retention period expressed in days. Mutually exclusive with years."
  type        = number
  default     = 30
}

variable "object_lock_retention_years" {
  description = "Default Object Lock retention period expressed in years. Mutually exclusive with days."
  type        = number
  default     = null
}

variable "replication_rules" {
  description = "Ordered set of cross region replication rules applied to the bucket."
  type = list(object({
    id                        = string
    priority                  = optional(number)
    prefix                    = optional(string)
    delete_marker_replication = optional(bool, false)
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
      replica_modifications = optional(object({
        status = string
      }))
    }))
    destination = object({
      bucket                           = string
      storage_class                    = optional(string, "STANDARD")
      account                          = optional(string)
      replica_kms_key_id               = optional(string)
      access_control_translation_owner = optional(string)
      metrics = optional(object({
        status = optional(string, "Enabled")
        event_threshold = optional(object({
          minutes = number
        }))
      }))
      replication_time = optional(object({
        status = optional(string, "Enabled")
        time = optional(object({
          minutes = number
        }))
      }))
    })
  }))
  default = []
}

variable "inventory_configurations" {
  description = "List of S3 Inventory configurations written to an encrypted Parquet or CSV destination."
  type = list(object({
    name                     = string
    included_object_versions = optional(string, "All")
    frequency                = optional(string, "Daily")
    destination = object({
      bucket_arn = string
      format     = optional(string, "Parquet")
      prefix     = optional(string)
      encryption = optional(object({
        sse_s3         = optional(bool, false)
        sse_kms_key_id = optional(string)
      }))
    })
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rules applied to the bucket. When empty, no CORS configuration is created."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules applied to the bucket. When empty, no lifecycle configuration is created."
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    prefix = optional(string, "")
    tags   = optional(map(string))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      noncurrent_days           = number
      newer_noncurrent_versions = optional(number)
    }))
    noncurrent_version_transition = optional(list(object({
      noncurrent_days           = number
      newer_noncurrent_versions = optional(number)
      storage_class             = string
    })))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

################################################################################
# Locals
################################################################################

locals {
  tags = {
    ManagedBy = "Terraform"
    Service   = "s3"
  }

  create_replication = length(var.replication_rules) > 0

  replication_role_name = "s3-replication-${substr(md5(aws_s3_bucket.this.bucket), 0, 16)}"

  replication_destination_resources = flatten([
    for rule in var.replication_rules : [
      rule.destination.bucket,
      "${rule.destination.bucket}/*",
    ]
  ])

  custom_policy_statements = try(
    tolist(jsondecode(var.custom_bucket_policy).Statement),
    try([jsondecode(var.custom_bucket_policy).Statement], [])
  )

  enforce_ssl_statement = {
    Sid       = "DenyInsecureConnections"
    Effect    = "Deny"
    Principal = "*"
    Action    = "s3:*"
    Resource = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
    Condition = {
      Bool = {
        "aws:SecureTransport" = "false"
      }
    }
  }

  logging_statement = {
    Sid    = "S3ServerAccessLogging"
    Effect = "Allow"
    Principal = {
      Service = "logging.s3.amazonaws.com"
    }
    Action   = "s3:PutObject"
    Resource = ["${aws_s3_bucket.this.arn}/*"]
    Condition = {
      ArnLike = {
        "aws:SourceArn" = var.logging_source_bucket_arns
      }
    }
  }

  logging_statements = length(var.logging_source_bucket_arns) > 0 ? [local.logging_statement] : []

  bucket_policy_statements = concat(
    local.custom_policy_statements,
    [local.enforce_ssl_statement],
    local.logging_statements,
  )
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  bucket        = var.name
  bucket_prefix = var.name_prefix
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_enabled

  tags = local.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = !(var.logging_target_bucket != null && var.object_lock_enabled)
      error_message = "Server access logging cannot be combined with S3 Object Lock."
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_acl" "this" {
  count = var.object_ownership == "ObjectWriter" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_arn == null ? "AES256" : "aws:kms"
      kms_master_key_id = var.kms_key_arn
    }

    bucket_key_enabled = var.kms_key_arn != null
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.bucket_policy_statements
  })

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_notification" "this" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_target_bucket != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_prefix

  lifecycle {
    precondition {
      condition     = !(var.logging_target_bucket != null && var.object_lock_enabled)
      error_message = "Server access logging cannot be combined with S3 Object Lock."
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_retention_mode
      days  = var.object_lock_retention_days
      years = var.object_lock_retention_years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = var.logging_target_bucket == null
      error_message = "Object Lock cannot be enabled on a bucket that is configured as a server access log source."
    }
  }
}

################################################################################
# Cross region replication
################################################################################

resource "aws_iam_role" "replication" {
  count = local.create_replication ? 1 : 0

  name = local.replication_role_name

  description = "Role assumed by Amazon S3 to replicate objects out of ${aws_s3_bucket.this.bucket}."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ReplicationAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_policy" "replication" {
  count = local.create_replication ? 1 : 0

  name        = local.replication_role_name
  description = "Least privilege replication policy for ${aws_s3_bucket.this.bucket}."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketReadPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
        ]
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*",
        ]
      },
      {
        Sid    = "DestinationBucketWritePermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
        ]
        Resource = local.replication_destination_resources
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_replication ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_replication ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      priority = try(rule.value.priority, null)
      status   = "Enabled"

      dynamic "filter" {
        for_each = (rule.value.prefix != null || try(rule.value.filter, null) != null) ? [1] : []

        content {
          prefix = try(rule.value.prefix, try(rule.value.filter.prefix, null))

          dynamic "tag" {
            for_each = try(rule.value.filter.tags, {})

            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []

            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }

          dynamic "replica_modifications" {
            for_each = source_selection_criteria.value.replica_modifications != null ? [source_selection_criteria.value.replica_modifications] : []

            content {
              status = replica_modifications.value.status
            }
          }
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication ? "Enabled" : "Disabled"
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, "STANDARD")
        account       = coalesce(try(rule.value.destination.account, null), data.aws_caller_identity.current.account_id)

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) != null ? [rule.value.destination.replica_kms_key_id] : []

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation_owner, null) != null ? [rule.value.destination.access_control_translation_owner] : []

          content {
            owner = access_control_translation.value
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics, null) != null ? [rule.value.destination.metrics] : []

          content {
            status = try(metrics.value.status, "Enabled")

            dynamic "event_threshold" {
              for_each = try(metrics.value.event_threshold, null) != null ? [metrics.value.event_threshold] : []

              content {
                minutes = event_threshold.value.minutes
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time, null) != null ? [rule.value.destination.replication_time] : []

          content {
            status = try(replication_time.value.status, "Enabled")

            dynamic "time" {
              for_each = try(replication_time.value.time, null) != null ? [replication_time.value.time] : []

              content {
                minutes = time.value.minutes
              }
            }
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_iam_role_policy_attachment.replication,
  ]
}

################################################################################
# Inventory
################################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = { for configuration in var.inventory_configurations : configuration.name => configuration }

  bucket                   = aws_s3_bucket.this.id
  name                     = each.value.name
  included_object_versions = try(each.value.included_object_versions, "All")

  schedule {
    frequency = try(each.value.frequency, "Daily")
  }

  destination {
    bucket {
      format     = try(each.value.destination.format, "Parquet")
      bucket_arn = each.value.destination.bucket_arn
      prefix     = try(each.value.destination.prefix, null)

      encryption {
        dynamic "sse_kms" {
          for_each = (
            !try(each.value.destination.encryption.sse_s3, false) &&
            coalesce(try(each.value.destination.encryption.sse_kms_key_id, null), var.kms_key_arn) != null
          ) ? [1] : []

          content {
            key_id = coalesce(try(each.value.destination.encryption.sse_kms_key_id, null), var.kms_key_arn)
          }
        }

        dynamic "sse_s3" {
          for_each = (
            try(each.value.destination.encryption.sse_s3, false) ||
            coalesce(try(each.value.destination.encryption.sse_kms_key_id, null), var.kms_key_arn) == null
          ) ? [1] : []

          content {}
        }
      }
    }
  }
}

################################################################################
# CORS
################################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

################################################################################
# Lifecycle
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = try(rule.value.status, "Enabled")

      filter {
        prefix = try(rule.value.prefix, "")

        dynamic "tag" {
          for_each = try(rule.value.tags, {})

          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []

        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []

        content {
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for current account ID
data "aws_caller_identity" "current" {}

# Variables
variable "group_name_prefix" {
  description = "Prefix for IAM group names"
  type        = string
  default     = "app"
}

variable "s3_allowed_region" {
  description = "The only AWS region where s3:CreateBucket is allowed for developers"
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket_name" {
  description = "Name of the remote state S3 bucket to which developers are denied all s3 access"
  type        = string
  default     = "my-remote-state-bucket"
}

# IAM Account Password Policy
resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
}

# S3 Account Public Access Block
resource "aws_s3_account_public_access_block" "this" {
  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

# KMS key for S3 encryption
resource "aws_kms_key" "s3" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })
}

# Data source for current region (allowed static metadata)
data "aws_region" "current" {}

# Remote state S3 bucket
resource "aws_s3_bucket" "remote_state" {
  bucket = var.remote_state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

# Per-bucket public access block
resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

# Server-side encryption configuration using KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

# IAM Groups
resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

# Attach AWS-managed policies to developer group
resource "aws_iam_group_policy_attachment" "developer_readonly" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# Custom policy: manage personal access keys
resource "aws_iam_group_policy" "developer_access_keys" {
  name   = "developer-manage-access-keys"
  group  = aws_iam_group.developer.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      }
    ]
  })
}

# Custom policy: virtual MFA management
resource "aws_iam_group_policy" "developer_virtual_mfa" {
  name   = "developer-virtual-mfa"
  group  = aws_iam_group.developer.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Custom policy: MFA-gated S3 access
resource "aws_iam_group_policy" "developer_s3_mfa" {
  name   = "developer-s3-mfa"
  group  = aws_iam_group.developer.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "s3:CreateBucket"
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.s3_allowed_region
          }
        }
      },
      {
        Effect   = "Deny"
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.remote_state.arn,
          "${aws_s3_bucket.remote_state.arn}/*"
        ]
      }
    ]
  })
}

# Custom policy: MFA-gated EC2, ELB, CloudWatch, AutoScaling
resource "aws_iam_group_policy" "developer_ec2_elb_cw_asg_mfa" {
  name   = "developer-ec2-elb-cw-asg-mfa"
  group  = aws_iam_group.developer.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ec2:Describe*",
          "ec2:Get*",
          "ec2:RebootInstances",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "elasticloadbalancing:Describe*",
          "elasticloadbalancing:Modify*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "cloudwatch:PutMetricData",
          "autoscaling:Describe*",
          "autoscaling:UpdateAutoScalingGroup",
          "autoscaling:SetDesiredCapacity",
          "autoscaling:TerminateInstanceInAutoScalingGroup"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "autoscaling:*"
        ]
        Resource = "arn:aws:iam::*:role/aws-service-role/*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Admin role
resource "aws_iam_role" "admin" {
  name = "admin"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

# Custom policy for admin role: full admin with MFA
resource "aws_iam_role_policy" "admin_full_access" {
  name   = "admin-full-access-mfa"
  role   = aws_iam_role.admin.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Admin group policy: allow assuming admin role with MFA
resource "aws_iam_group_policy" "admin_assume_role" {
  name   = "admin-assume-role-mfa"
  group  = aws_iam_group.admin.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "config" {
  type        = string
  default     = ""
  description = "YAML configuration for the CI/CD pipeline framework"
}

locals {
  parsed_config = try(yamldecode(var.config), {})

  # Top-level settings
  pipelines        = try(local.parsed_config.pipelines, {})
  source_providers = try(local.parsed_config.source_providers, [])

  # Common bucket suffix (static for greenfield)
  bucket_suffix = "terraforest"
}

# -------------------------------------------------------------------
# Data Sources
# -------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# -------------------------------------------------------------------
# KMS Key for S3 Encryption (Customer Managed Key)
# -------------------------------------------------------------------
resource "aws_kms_key" "s3_cmk" {
  description             = "CMK for S3 bucket encryption in Terraforest CI/CD"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_kms_alias" "s3_cmk" {
  name          = "alias/terraforest-s3-cmk"
  target_key_id = aws_kms_key.s3_cmk.id
}

# -------------------------------------------------------------------
# S3 Buckets for Artifacts and Build Cache
# -------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  bucket        = "codepipeline-artifacts-${local.bucket_suffix}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts_versioning" {
  bucket = aws_s3_bucket.artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts_encryption" {
  bucket = aws_s3_bucket.artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_cmk.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts_public_access" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "build_cache" {
  bucket        = "codebuild-cache-${local.bucket_suffix}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "build_cache_versioning" {
  bucket = aws_s3_bucket.build_cache.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache_encryption" {
  bucket = aws_s3_bucket.build_cache.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_cmk.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache_public_access" {
  bucket                  = aws_s3_bucket.build_cache.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -------------------------------------------------------------------
# Default CodePipeline IAM Role
# -------------------------------------------------------------------
resource "aws_iam_role" "codepipeline_default" {
  name        = "codepipeline-default-${local.bucket_suffix}"
  path        = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_default_policy" {
  name = "codepipeline-default-policy"
  role = aws_iam_role.codepipeline_default.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = "*"
        Condition = {
          StringEqualsIfExists = {
            "iam:PassedToService" = [
              "codebuild.amazonaws.com",
              "codepipeline.amazonaws.com"
            ]
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:UploadArchive",
          "codecommit:GetUploadArchiveStatus",
          "codecommit:CancelUploadArchive"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:PutImage"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.artifacts.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.artifacts.arn
      }
    ]
  })
}

# -------------------------------------------------------------------
# CodeStar Connections
# -------------------------------------------------------------------
resource "aws_codestarconnections_connection" "this" {
  for_each = toset(local.source_providers)

  name          = "codestar-${each.value}"
  provider_type = each.value

  depends_on = []
}

# -------------------------------------------------------------------
# Pipeline Resources (dynamic per pipeline)
# -------------------------------------------------------------------
resource "aws_codepipeline" "this" {
  for_each = local.pipelines

  name     = each.key
  role_arn = try(each.value.custom_role_arn, aws_iam_role.codepipeline_default.arn)

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"
  }

  dynamic "stage" {
    for_each = try(each.value.stages, [])
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = try(stage.value.actions, [])
        content {
          name     = action.value.name
          owner    = try(action.value.owner, "AWS")
          version  = try(action.value.version, "1")
          category = action.value.category
          provider = action.value.provider

          configuration = try(action.value.configuration, {})

          input_artifacts  = try(action.value.input_artifacts, [])
          output_artifacts = try(action.value.output_artifacts, [])

          run_order = try(action.value.run_order, null)
          region    = try(action.value.region, data.aws_region.current.name)

          namespace = try(action.value.namespace, null)

          # Role ARN for action - if provider is CodeBuild or Lambda, need appropriate role
          role_arn = try(action.value.role_arn, null)
        }
      }
    }
  }

  tags = try(each.value.tags, {})
}

# -------------------------------------------------------------------
# IAM Roles for EventBridge Triggers (terrabits-<pipeline>)
# -------------------------------------------------------------------
resource "aws_iam_role" "eventbridge_trigger" {
  for_each = local.pipelines

  name = "terrabits-${each.key}"
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "eventbridge_trigger" {
  for_each = local.pipelines

  name = "eventbridge-trigger-${each.key}"
  role = aws_iam_role.eventbridge_trigger[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "codepipeline:StartPipelineExecution"
        ]
        Resource = aws_codepipeline.this[each.key].arn
      }
    ]
  })
}

# -------------------------------------------------------------------
# EventBridge Rules and Targets per Pipeline Trigger
# -------------------------------------------------------------------
locals {
  pipeline_triggers = flatten([
    for p_name, p_config in local.pipelines : [
      for i, trigger in try(p_config.triggers, []) : {
        key              = "${p_name}-${i}"
        pipeline_name    = p_name
        trigger          = trigger
        pipeline_arn     = aws_codepipeline.this[p_name].arn
        event_role_arn   = aws_iam_role.eventbridge_trigger[p_name].arn
        event_pattern    = try(
          trigger.event_pattern,
          trigger.type == "codecommit_branch" ? jsonencode({
            source      = ["aws.codecommit"]
            "detail-type" = ["CodeCommit Repository State Change"]
            resources   = [try(trigger.repository_arn, "*")]
            detail = {
              referenceType = ["branch"]
              referenceName = try(trigger.branch_names, [])
            }
          }) : (
            trigger.type == "codecommit_tag" ? jsonencode({
              source      = ["aws.codecommit"]
              "detail-type" = ["CodeCommit Repository State Change"]
              resources   = [try(trigger.repository_arn, "*")]
              detail = {
                referenceType = ["tag"]
                referenceName = try(trigger.tag_names, [])
              }
            }) : null
          )
        )
      }
    ]
  ])
}

resource "aws_cloudwatch_event_rule" "trigger" {
  for_each = {
    for t in local.pipeline_triggers : t.key => t
  }

  name          = "trigger-${each.key}"
  description   = "Event rule for pipeline ${each.value.pipeline_name}"
  event_pattern = each.value.event_pattern
  schedule_expression = try(each.value.trigger.schedule_expression, null)
}

resource "aws_cloudwatch_event_target" "pipeline" {
  for_each = {
    for t in local.pipeline_triggers : t.key => t
  }

  rule     = aws_cloudwatch_event_rule.trigger[each.key].name
  arn       = each.value.pipeline_arn
  role_arn = each.value.event_role_arn
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.94.0"
    }
  }
}

provider "aws" {
  region                      = "us-east-1"
  skip_credentials_validation = true
  skip_requesting_account_id  = true
  skip_metadata_api_check     = true
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "create_module" {
  description = "Toggle to create the entire security‑group and prefix‑list logic"
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "When true, creates a new security group; otherwise use existing_security_group_id"
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group (used when create_security_group is false)"
  type        = string
  default     = ""
}

variable "lifecycle_create_before_destroy" {
  description = "Enable create‑before‑destroy lifecycle on the new security group"
  type        = bool
  default     = true
}

variable "revoke_rules_on_delete" {
  description = "Revoke all rules when the security group is deleted"
  type        = bool
  default     = true
}

variable "new_ingress_rules" {
  description = "List of ingress rule objects for a newly created security group"
  type = list(object({
    cidr_ipv4                = optional(string, "")
    cidr_ipv6                = optional(string, "")
    referenced_security_group_id = optional(string, "")
    prefix_list_id           = optional(string, "")
    from_port                = number
    to_port                  = number
    ip_protocol              = string
  }))
  default = []
}

variable "new_egress_rules" {
  description = "List of egress rule objects for a newly created security group"
  type = list(object({
    cidr_ipv4                = optional(string, "")
    cidr_ipv6                = optional(string, "")
    referenced_security_group_id = optional(string, "")
    prefix_list_id           = optional(string, "")
    from_port                = number
    to_port                  = number
    ip_protocol              = string
  }))
  default = []
}

variable "existing_ingress_rules" {
  description = "List of ingress rule objects for an existing security group"
  type = list(object({
    cidr_ipv4                = optional(string, "")
    cidr_ipv6                = optional(string, "")
    referenced_security_group_id = optional(string, "")
    prefix_list_id           = optional(string, "")
    from_port                = number
    to_port                  = number
    ip_protocol              = string
  }))
  default = []
}

variable "existing_egress_rules" {
  description = "List of egress rule objects for an existing security group"
  type = list(object({
    cidr_ipv4                = optional(string, "")
    cidr_ipv6                = optional(string, "")
    referenced_security_group_id = optional(string, "")
    prefix_list_id           = optional(string, "")
    from_port                = number
    to_port                  = number
    ip_protocol              = string
  }))
  default = []
}

variable "create_prefix_list" {
  description = "When true, create a customer‑managed EC2 prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family for the prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the prefix list"
  type        = number
  default     = 10
}

variable "prefix_list_cidr_entries" {
  description = "List of CIDR entries to populate the prefix list"
  type        = list(string)
  default     = []
}

variable "existing_prefix_list_id" {
  description = "Existing prefix list ID (overrides created prefix list if provided)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  common_tags = merge(var.tags, {})

  # Select the correct security group ID based on create_before_destroy setting
  new_sg_id = var.create_module && var.create_security_group ? (
    var.lifecycle_create_before_destroy ? aws_security_group.new_sg_cbd[0].id : aws_security_group.new_sg[0].id
  ) : ""
}

# ----------------------------------------------------------------------
# VPC (must exist for greenfield)
# ----------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.common_tags, { Name = "security-group-vpc" })
}

# ----------------------------------------------------------------------
# Security Group (new) – without create_before_destroy
# ----------------------------------------------------------------------
resource "aws_security_group" "new_sg" {
  count       = var.create_module && var.create_security_group && !var.lifecycle_create_before_destroy ? 1 : 0
  name_prefix = "new-sg-"
  description = "Security group created by Terraform module"
  vpc_id      = aws_vpc.main.id
  revoke_rules_on_delete = var.revoke_rules_on_delete
  tags        = merge(local.common_tags, { Name = "new-security-group" })
}

# ----------------------------------------------------------------------
# Security Group (new) – with create_before_destroy
# ----------------------------------------------------------------------
resource "aws_security_group" "new_sg_cbd" {
  count       = var.create_module && var.create_security_group && var.lifecycle_create_before_destroy ? 1 : 0
  name_prefix = "new-sg-cbd-"
  description = "Security group created by Terraform module with create_before_destroy"
  vpc_id      = aws_vpc.main.id
  revoke_rules_on_delete = var.revoke_rules_on_delete
  tags        = merge(local.common_tags, { Name = "new-security-group-cbd" })

  lifecycle {
    create_before_destroy = true
  }
}

# ----------------------------------------------------------------------
# Ingress rules for new security group
# ----------------------------------------------------------------------
resource "aws_security_group_rule" "new_ingress" {
  for_each = var.create_module && var.create_security_group ? { for idx, r in var.new_ingress_rules : idx => r } : {}

  type              = "ingress"
  security_group_id = local.new_sg_id
  protocol          = each.value.ip_protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != "" ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != "" ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != "" ? [each.value.prefix_list_id] : (
    var.existing_prefix_list_id != "" ? [var.existing_prefix_list_id] : (
      var.create_prefix_list ? [aws_ec2_managed_prefix_list.this[0].id] : null
    )
  )

  description = "New ingress rule ${each.key}"
}

# ----------------------------------------------------------------------
# Egress rules for new security group
# ----------------------------------------------------------------------
resource "aws_security_group_rule" "new_egress" {
  for_each = var.create_module && var.create_security_group ? { for idx, r in var.new_egress_rules : idx => r } : {}

  type              = "egress"
  security_group_id = local.new_sg_id
  protocol          = each.value.ip_protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != "" ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != "" ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != "" ? [each.value.prefix_list_id] : (
    var.existing_prefix_list_id != "" ? [var.existing_prefix_list_id] : (
      var.create_prefix_list ? [aws_ec2_managed_prefix_list.this[0].id] : null
    )
  )

  description = "New egress rule ${each.key}"
}

# ----------------------------------------------------------------------
# Ingress rules for existing security group
# ----------------------------------------------------------------------
resource "aws_security_group_rule" "existing_ingress" {
  for_each = var.create_module && !var.create_security_group ? { for idx, r in var.existing_ingress_rules : idx => r } : {}

  type              = "ingress"
  security_group_id = var.existing_security_group_id
  protocol          = each.value.ip_protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != "" ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != "" ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != "" ? [each.value.prefix_list_id] : (
    var.existing_prefix_list_id != "" ? [var.existing_prefix_list_id] : (
      var.create_prefix_list ? [aws_ec2_managed_prefix_list.this[0].id] : null
    )
  )

  description = "Existing ingress rule ${each.key}"
}

# ----------------------------------------------------------------------
# Egress rules for existing security group
# ----------------------------------------------------------------------
resource "aws_security_group_rule" "existing_egress" {
  for_each = var.create_module && !var.create_security_group ? { for idx, r in var.existing_egress_rules : idx => r } : {}

  type              = "egress"
  security_group_id = var.existing_security_group_id
  protocol          = each.value.ip_protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = each.value.cidr_ipv4 != "" ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != "" ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_ids          = each.value.prefix_list_id != "" ? [each.value.prefix_list_id] : (
    var.existing_prefix_list_id != "" ? [var.existing_prefix_list_id] : (
      var.create_prefix_list ? [aws_ec2_managed_prefix_list.this[0].id] : null
    )
  )

  description = "Existing egress rule ${each.key}"
}

# ----------------------------------------------------------------------
# Customer‑managed prefix list
# ----------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create_module && var.create_prefix_list ? 1 : 0

  name           = "module-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  tags = merge(local.common_tags, { Name = "module-prefix-list" })
}

resource "aws_ec2_managed_prefix_list_entry" "entries" {
  for_each = var.create_module && var.create_prefix_list ? { for idx, cidr in var.prefix_list_cidr_entries : idx => cidr } : {}

  prefix_list_id = aws_ec2_managed_prefix_list.this[0].id
  cidr           = each.value
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name for tagging and SSM paths"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
  }
}

# Table 1: near-app-actions-mapping
resource "aws_dynamodb_table" "near_app_actions_mapping" {
  name         = "near-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  tags = merge(local.common_tags, { Name = "near-app-actions-mapping" })

  lifecycle {
    prevent_destroy = true
  }
}

