# SSM Parameters for near-wallets
resource "aws_ssm_parameter" "near_wallets_arn" {
  name  = "/wallet-service/dynamodb/wallets/arn"
  type  = "String"
  value = aws_dynamodb_table.near_wallets.arn

  tags = merge(local.common_tags, { Name = "near-wallets-arn" })
}

resource "aws_ssm_parameter" "near_wallets_table_name" {
  name  = "/wallet-service/dynamodb/wallets/table-name"
  type  = "String"
  value = aws_dynamodb_table.near_wallets.name

  tags = merge(local.common_tags, { Name = "near-wallets-table-name" })
}

resource "aws_ssm_parameter" "near_wallets_stream_arn" {
  name  = "/wallet-service/dynamodb/wallets/stream-arn"
  type  = "String"
  value = aws_dynamodb_table.near_wallets.stream_arn

  tags = merge(local.common_tags, { Name = "near-wallets-stream-arn" })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Explicit name for the Transfer server and derived resources. A two-word random pet name is generated when null."
  type        = string
  default     = null
}

variable "endpoint_type" {
  description = "The type of endpoint that you want your Transfer server to use: PUBLIC, VPC, or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "The protocol(s) that the Transfer server supports (SFTP, FTPS, FTP, AS2)."
  type        = list(string)
  default     = ["SFTP"]
}

variable "identity_provider_type" {
  description = "The mode of authentication enabled for the Transfer server."
  type        = string
  default     = "SERVICE_MANAGED"

  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE", "AWS_LAMBDA"], var.identity_provider_type)
    error_message = "identity_provider_type must be one of: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, AWS_LAMBDA."
  }
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM role that the Transfer server uses for logging. When null a role is created and AWSTransferLoggingAccess is attached."
  type        = string
  default     = null
}

variable "security_policy_name" {
  description = "Specifies the name of the security policy that is attached to the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "certificate_arn" {
  description = "ARN of the ACM certificate used for the FTPS/AS2 endpoint. Required when FTPS or AS2 protocols are enabled."
  type        = string
  default     = null
}

variable "pre_authentication_login_banner" {
  description = "A custom message that is displayed before authentication."
  type        = string
  default     = null
}

variable "post_authentication_login_banner" {
  description = "A custom message that is displayed after authentication."
  type        = string
  default     = null
}

variable "protocol_details" {
  description = "Protocol specific configuration for the Transfer server (as2_transports, passive_ip, set_stat_option, tls_session_resumption_mode)."
  type        = any
  default     = {}
}

variable "sftp_users" {
  description = "Map of SFTP user names to their configuration. Each user is provisioned an IAM role, IAM policy, and aws_transfer_user."
  type = map(object({
    home_directory = string
  }))
  default = {}
}

variable "sftp_user_keys" {
  description = "Map of SFTP user names to a list of SSH public keys that should be associated with the user."
  type        = map(list(string))
  default     = {}
}

variable "hosted_zone_name" {
  description = "Name of the Route 53 hosted zone used to create the CNAME record for the Transfer server. When null no DNS record is created."
  type        = string
  default     = null
}

variable "subdomain" {
  description = "Sub-domain used when creating the Route 53 CNAME record."
  type        = string
  default     = "sftp"
}

variable "tags" {
  description = "A map of tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "vpc_cidr" {
  description = "CIDR block used when the module creates a dedicated VPC for VPC/VPC_ENDPOINT endpoints."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks used when the module creates the public subnets for VPC/VPC_ENDPOINT endpoints."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "endpoint_details" {
  description = "Pre-existing VPC endpoint details (vpc_id, subnet_ids, security_group_ids, address_allocation_ids, vpc_endpoint_id). When supplied no network resources are created."
  type        = any
  default     = {}
}

variable "api_gateway_url" {
  description = "URL of an existing API Gateway used for API_GATEWAY identity provider authentication. When null an API Gateway is provisioned."
  type        = string
  default     = null
}

variable "api_gateway_execution_arn" {
  description = "Execution ARN of an existing API Gateway used for API_GATEWAY identity provider authentication (required when api_gateway_url is supplied)."
  type        = string
  default     = null
}

###############################################################################
# Locals
###############################################################################

locals {
  server_name = var.name != null ? var.name : one(random_pet.name[*].id)

  common_tags = merge(var.tags, {
    Name = local.server_name
  })

  # Network resources are only created for VPC/VPC_ENDPOINT endpoints when the
  # caller did not supply pre-existing endpoint details.
  create_network = length(var.endpoint_details) == 0 && contains(["VPC", "VPC_ENDPOINT"], var.endpoint_type)
  create_vpc     = local.create_network && var.endpoint_type == "VPC"

  # API Gateway identity provider handling.
  api_gateway_enabled = var.identity_provider_type == "API_GATEWAY"
  create_api_gateway  = local.api_gateway_enabled && var.api_gateway_url == null

  effective_logging_role_arn = var.logging_role_arn != null ? var.logging_role_arn : try(aws_iam_role.logging[0].arn, null)

  # Endpoint details derived from resources created by this configuration.
  generated_endpoint_details = var.endpoint_type == "VPC" ? {
    vpc_id                 = one(aws_vpc.main[*].id)
    subnet_ids             = aws_subnet.public[*].id
    security_group_ids     = aws_security_group.transfer[*].id
    address_allocation_ids = aws_eip.transfer[*].id
    } : var.endpoint_type == "VPC_ENDPOINT" ? {
    vpc_endpoint_id = one(aws_vpc_endpoint.transfer[*].id)
  } : {}

  effective_endpoint_details = length(var.endpoint_details) > 0 ? var.endpoint_details : local.generated_endpoint_details

  api_gateway_url = var.api_gateway_url != null ? var.api_gateway_url : try(
    "https://${aws_api_gateway_rest_api.this[0].id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_api_gateway_stage.this[0].stage_name}",
    null
  )

  api_gateway_execution_arn = var.api_gateway_execution_arn != null ? var.api_gateway_execution_arn : try(aws_api_gateway_rest_api.this[0].execution_arn, null)

  # Flatten the user -> public keys map into a unique key per user/key index.
  ssh_keys = {
    for item in flatten([
      for user, keys in var.sftp_user_keys : [
        for idx, key in keys : {
          user_name      = user
          index          = idx
          ssh_public_key = key
        }
      ]
    ]) : "${item.user_name}-${item.index}" => {
      user_name      = item.user_name
      ssh_public_key = item.ssh_public_key
    }
  }

  # ARNs of the SFTP user roles for the KMS key policy.
  sftp_user_role_arns = [for role in aws_iam_role.sftp_user : role.arn]

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

###############################################################################
# Naming
###############################################################################

resource "random_pet" "name" {
  count     = var.name == null ? 1 : 0
  length    = 2
  separator = "-"
}

###############################################################################
# SSH Host Key
###############################################################################

resource "tls_private_key" "host_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

###############################################################################
# Customer Managed KMS Key for the S3 home directory bucket
###############################################################################

resource "aws_kms_key" "home" {
  description             = "Customer managed key for the ${local.server_name} SFTP home directory bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "home" {
  key_id = aws_kms_key.home.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "EnableRootAccountAdmin"
          Effect = "Allow"
          Principal = {
            AWS = local.account_root_arn
          }
          Action   = "kms:*"
          Resource = "*"
        },
        {
          Sid    = "AllowS3ServiceUse"
          Effect = "Allow"
          Principal = {
            Service = "s3.amazonaws.com"
          }
          Action = [
            "kms:Decrypt",
            "kms:GenerateDataKey",
            "kms:GenerateDataKeyWithoutPlaintext",
            "kms:DescribeKey"
          ]
          Resource = "*"
        }
      ],
      length(local.sftp_user_role_arns) > 0 ? [
        {
          Sid    = "AllowSFTPUserRolesUse"
          Effect = "Allow"
          Principal = {
            AWS = local.sftp_user_role_arns
          }
          Action = [
            "kms:Decrypt",
            "kms:GenerateDataKey",
            "kms:GenerateDataKeyWithoutPlaintext",
            "kms:DescribeKey"
          ]
          Resource = "*"
        }
      ] : []
    )
  })
}

###############################################################################
# S3 Home Directory Bucket
###############################################################################

resource "aws_s3_bucket" "home" {
  bucket = local.server_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "home" {
  bucket = aws_s3_bucket.home.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "home" {
  bucket = aws_s3_bucket.home.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.home.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "home" {
  bucket                  = aws_s3_bucket.home.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Transfer Logging Role (created only when no explicit role ARN is supplied)
###############################################################################

resource "aws_iam_role" "logging" {
  count = var.logging_role_arn == null ? 1 : 0

  name = "${local.server_name}-transfer-logging"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "logging" {
  count = var.logging_role_arn == null ? 1 : 0

  role       = aws_iam_role.logging[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

###############################################################################
# CloudWatch Log Group for structured logging
###############################################################################

resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = 30
  tags              = local.common_tags
}

###############################################################################
# API Gateway Authorization (only for API_GATEWAY identity provider)
###############################################################################

resource "aws_iam_role" "api_gateway_cloudwatch" {
  count = local.api_gateway_enabled ? 1 : 0

  name = "${local.server_name}-apigw-cloudwatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch" {
  count = local.api_gateway_enabled ? 1 : 0

  name = "${local.server_name}-apigw-cloudwatch"
  role = aws_iam_role.api_gateway_cloudwatch[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"
      }
    ]
  })
}

resource "aws_api_gateway_account" "this" {
  count = local.api_gateway_enabled ? 1 : 0

  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch[0].arn
}

resource "aws_iam_role" "transfer_invocation" {
  count = local.api_gateway_enabled ? 1 : 0

  name = "${local.server_name}-transfer-invocation"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "transfer_invocation" {
  count = local.api_gateway_enabled && local.api_gateway_execution_arn != null ? 1 : 0

  name = "${local.server_name}-transfer-invocation"
  role = aws_iam_role.transfer_invocation[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "execute-api:Invoke"
        Resource = "${local.api_gateway_execution_arn}/*"
      }
    ]
  })
}

resource "aws_api_gateway_rest_api" "this" {
  count = local.create_api_gateway ? 1 : 0

  name        = "${local.server_name}-auth"
  description = "Authentication API for AWS Transfer Family server ${local.server_name}"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "this" {
  count = local.create_api_gateway ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  parent_id   = aws_api_gateway_rest_api.this[0].root_resource_id
  path_part   = "auth"
}

resource "aws_api_gateway_method" "this" {
  count = local.create_api_gateway ? 1 : 0

  rest_api_id   = aws_api_gateway_rest_api.this[0].id
  resource_id   = aws_api_gateway_resource.this[0].id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "this" {
  count = local.create_api_gateway ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  resource_id = aws_api_gateway_resource.this[0].id
  http_method = aws_api_gateway_method.this[0].http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_api_gateway_method_response" "this" {
  count = local.create_api_gateway ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  resource_id = aws_api_gateway_resource.this[0].id
  http_method = aws_api_gateway_method.this[0].http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "this" {
  count = local.create_api_gateway ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  resource_id = aws_api_gateway_resource.this[0].id
  http_method = aws_api_gateway_method.this[0].http_method
  status_code = aws_api_gateway_method_response.this[0].status_code

  response_templates = {
    "application/json" = ""
  }

  depends_on = [aws_api_gateway_integration.this]
}

resource "aws_api_gateway_deployment" "this" {
  count = local.create_api_gateway ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.this[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.this[0].id,
      aws_api_gateway_method.this[0].id,
      aws_api_gateway_integration.this[0].id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "this" {
  count = local.create_api_gateway ? 1 : 0

  deployment_id = aws_api_gateway_deployment.this[0].id
  rest_api_id   = aws_api_gateway_rest_api.this[0].id
  stage_name    = "prod"

  tags = local.common_tags
}

###############################################################################
# Networking (only for VPC / VPC_ENDPOINT endpoints)
###############################################################################

resource "aws_vpc" "main" {
  count = local.create_network ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = local.create_network ? length(var.public_subnet_cidrs) : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-public-${count.index}"
  })
}

resource "aws_internet_gateway" "main" {
  count = local.create_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = local.common_tags
}

resource "aws_route_table" "public" {
  count = local.create_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = local.common_tags
}

resource "aws_route_table_association" "public" {
  count = local.create_network ? length(var.public_subnet_cidrs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_security_group" "transfer" {
  count = local.create_network ? 1 : 0

  name        = "${local.server_name}-transfer"
  description = "Security group for the AWS Transfer Family endpoint (SFTP)"
  vpc_id      = aws_vpc.main[0].id

  ingress {
    description = "SFTP access"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-transfer"
  })
}

resource "aws_eip" "transfer" {
  count = local.create_vpc ? length(var.public_subnet_cidrs) : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-eip-${count.index}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_vpc_endpoint" "transfer" {
  count = local.create_network && var.endpoint_type == "VPC_ENDPOINT" ? 1 : 0

  vpc_id              = aws_vpc.main[0].id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.transfer"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.transfer[0].id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-transfer-endpoint"
  })
}

###############################################################################
# AWS Transfer Server
###############################################################################

resource "aws_transfer_server" "this" {
  endpoint_type          = var.endpoint_type
  protocols              = var.protocols
  security_policy_name   = var.security_policy_name
  identity_provider_type = var.identity_provider_type

  logging_role = local.effective_logging_role_arn
  certificate  = var.certificate_arn
  host_key     = tls_private_key.host_key.private_key_pem

  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner

  structured_log_destinations = [aws_cloudwatch_log_group.transfer.arn]

  invocation_role = try(aws_iam_role.transfer_invocation[0].arn, null)
  url             = local.api_gateway_enabled ? local.api_gateway_url : null

  tags = local.common_tags

  dynamic "protocol_details" {
    for_each = length(var.protocol_details) > 0 ? [var.protocol_details] : []

    content {
      as2_transports              = lookup(protocol_details.value, "as2_transports", null)
      passive_ip                  = lookup(protocol_details.value, "passive_ip", null)
      set_stat_option             = lookup(protocol_details.value, "set_stat_option", null)
      tls_session_resumption_mode = lookup(protocol_details.value, "tls_session_resumption_mode", null)
    }
  }

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "PUBLIC" ? [] : [local.effective_endpoint_details]

    content {
      vpc_id                 = lookup(endpoint_details.value, "vpc_id", null)
      subnet_ids             = lookup(endpoint_details.value, "subnet_ids", null)
      security_group_ids     = lookup(endpoint_details.value, "security_group_ids", null)
      address_allocation_ids = lookup(endpoint_details.value, "address_allocation_ids", null)
      vpc_endpoint_id        = lookup(endpoint_details.value, "vpc_endpoint_id", null)
    }
  }
}

###############################################################################
# Route 53 DNS Mapping
###############################################################################

resource "aws_route53_zone" "this" {
  count = var.hosted_zone_name != null ? 1 : 0

  name = var.hosted_zone_name
  tags = local.common_tags
}

resource "aws_route53_record" "this" {
  count = var.hosted_zone_name != null ? 1 : 0

  zone_id = aws_route53_zone.this[0].zone_id
  name    = "${var.subdomain}.${var.hosted_zone_name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.this.endpoint]
}

###############################################################################
# SFTP Users
###############################################################################

resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users

  name = "${local.server_name}-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    User = each.key
  })
}

resource "aws_iam_policy" "sftp_user" {
  for_each = var.sftp_users

  name        = "${local.server_name}-${each.key}-s3"
  description = "S3 home directory access for SFTP user ${each.key}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListHomeBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.home.arn]
      },
      {
        Sid    = "ManageHomeDirectoryObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = ["${aws_s3_bucket.home.arn}/${trim(each.value.home_directory, "/")}/*"]
      },
      {
        Sid    = "UseHomeEncryptionKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.home.arn]
      }
    ]
  })

  tags = merge(local.common_tags, {
    User = each.key
  })
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each = var.sftp_users

  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id           = aws_transfer_server.this.id
  user_name           = each.key
  role                = aws_iam_role.sftp_user[each.key].arn
  home_directory      = "/${aws_s3_bucket.home.bucket}/${trim(each.value.home_directory, "/")}"
  home_directory_type = "PATH"

  tags = merge(local.common_tags, {
    User = each.key
  })

  depends_on = [aws_iam_role_policy_attachment.sftp_user]
}

resource "aws_transfer_ssh_key" "this" {
  for_each = local.ssh_keys

  server_id = aws_transfer_server.this.id
  user_name = each.value.user_name
  body      = trimspace(each.value.ssh_public_key)

  depends_on = [aws_transfer_user.this]
}

###############################################################################
# Outputs
###############################################################################

output "transfer_server_id" {
  description = "Identifier of the AWS Transfer Family server."
  value       = aws_transfer_server.this.id
}

output "transfer_server_arn" {
  description = "ARN of the AWS Transfer Family server."
  value       = aws_transfer_server.this.arn
}

output "transfer_server_endpoint" {
  description = "Endpoint of the AWS Transfer Family server."
  value       = aws_transfer_server.this.endpoint
}

output "s3_home_bucket" {
  description = "Name of the S3 bucket used as the SFTP home directory."
  value       = aws_s3_bucket.home.bucket
}

output "s3_home_kms_key_arn" {
  description = "ARN of the customer managed KMS key used to encrypt the SFTP home directory bucket."
  value       = aws_kms_key.home.arn
}

output "logging_role_arn" {
  description = "ARN of the IAM role used by the Transfer server for logging."
  value       = local.effective_logging_role_arn
}

output "sftp_user_names" {
  description = "Names of the provisioned SFTP users."
  value       = keys(var.sftp_users)
}

output "dns_record_fqdn" {
  description = "FQDN of the created Route 53 CNAME record, if any."
  value       = var.hosted_zone_name != null ? aws_route53_record.this[0].fqdn : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC and related resources"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/18"
}

variable "az_count" {
  description = "Number of Availability Zones to use. Defaults to all available in the region."
  type        = number
  default     = null
}

variable "create_public_subnets" {
  description = "Toggle creation of public subnets and associated resources"
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Toggle creation of private subnets and associated resources"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Toggle creation of a NAT Gateway (requires public subnets)"
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_count = var.az_count != null ? var.az_count : length(data.aws_availability_zones.available.names)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "igw" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_eip" "nat" {
  count  = (var.create_nat_gateway && var.create_public_subnets) ? 1 : 0
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  count          = (var.create_nat_gateway && var.create_public_subnets) ? 1 : 0
  allocation_id  = aws_eip.nat[0].id
  subnet_id      = aws_subnet.public[0].id
  depends_on     = [aws_internet_gateway.igw]

  tags = {
    Name = "${var.vpc_name}-nat"
  }
}

resource "aws_subnet" "public" {
  count                   = var.create_public_subnets ? local.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count                   = var.create_private_subnets ? local.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, local.az_count + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-private-${count.index}"
  }
}

resource "aws_route_table" "public" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw[0].id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
  count  = var.create_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

resource "aws_route" "private_nat" {
  count                  = (var.create_private_subnets && var.create_nat_gateway) ? 1 : 0
  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[0].id
}

resource "aws_route_table_association" "public" {
  count          = var.create_public_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  count          = var.create_private_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_network_acl" "public" {
  count  = var.create_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  ingress {
    rule_no    = 100
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "allow"
  }

  ingress {
    rule_no    = 32766
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "deny"
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "allow"
  }

  egress {
    rule_no    = 32766
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "deny"
  }

  tags = {
    Name = "${var.vpc_name}-public-nacl"
  }
}

resource "aws_network_acl" "private" {
  count  = var.create_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  ingress {
    rule_no    = 100
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "allow"
  }

  ingress {
    rule_no    = 32766
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "deny"
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "allow"
  }

  egress {
    rule_no    = 32766
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    action     = "deny"
  }

  tags = {
    Name = "${var.vpc_name}-private-nacl"
  }
}

resource "aws_network_acl_association" "public" {
  count          = var.create_public_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  network_acl_id = aws_network_acl.public[0].id
}

resource "aws_network_acl_association" "private" {
  count          = var.create_private_subnets ? local.az_count : 0
  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private[0].id
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the main VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  description = "Assign an Amazon-provided IPv6 CIDR block to the VPC and build dual-stack subnets/routes."
  type        = bool
  default     = true
}

variable "sn_details" {
  description = "Subnet definitions: name, index into the available AZ list, and whether the subnet is public."
  type = list(object({
    name     = string
    az_index = number
    public   = bool
  }))

  default = [
    { name = "web-1", az_index = 0, public = true },
    { name = "web-2", az_index = 1, public = true },
    { name = "web-3", az_index = 2, public = true },
    { name = "app-1", az_index = 0, public = false },
    { name = "app-2", az_index = 1, public = false },
    { name = "app-3", az_index = 2, public = false },
    { name = "db-1", az_index = 0, public = false },
    { name = "db-2", az_index = 1, public = false },
    { name = "db-3", az_index = 2, public = false },
    { name = "reserved-1", az_index = 0, public = false },
    { name = "reserved-2", az_index = 1, public = false },
    { name = "reserved-3", az_index = 2, public = false },
  ]
}

variable "tags" {
  description = "Common tags applied to every resource in this configuration."
  type        = map(string)
  default = {
    Project   = "three-tier"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  sn_map = { for s in var.sn_details : s.name => s }

  public_sn_map = {
    for s in var.sn_details : s.name => s
    if s.public
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = merge(var.tags, {
    Name = "main-vpc"
  })
}

###############################################################################
# Subnet CIDR calculation (IPv4 + IPv6)
###############################################################################

module "subnets_ipv4" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block

  networks = [
    for i, s in var.sn_details : {
      name     = s.name
      netnum   = i
      new_bits = 4
    }
  ]
}

module "subnets_ipv6" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.ipv6_cidr_block

  networks = [
    for i, s in var.sn_details : {
      name     = s.name
      netnum   = i
      new_bits = 8
    }
  ]
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "this" {
  for_each = module.subnets_ipv4.network_cidr_blocks

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value
  ipv6_cidr_block   = var.is_ipv6_enabled ? module.subnets_ipv6.network_cidr_blocks[each.key] : null
  availability_zone = data.aws_availability_zones.available.names[local.sn_map[each.key].az_index]

  map_public_ip_on_launch         = local.sn_map[each.key].public
  assign_ipv6_address_on_creation = var.is_ipv6_enabled

  tags = merge(var.tags, {
    Name = each.key
    Tier = local.sn_map[each.key].public ? "public" : "private"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  })
}

###############################################################################
# Public route table and routes
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "public-rt-web"
  })
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  count = var.is_ipv6_enabled ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

###############################################################################
# Public subnet associations (public subnets only)
###############################################################################

resource "aws_route_table_association" "public" {
  for_each = local.public_sn_map

  subnet_id      = aws_subnet.this[each.value.name].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Web tier security group: TLS from the internet, SSH from the VPC, egress TLS to the app tier."
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "web_sg"
    Tier = "web"
  })
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "Application tier security group: TLS from the web tier, egress TLS to the database tier."
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "app_sg"
    Tier = "app"
  })
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Database tier security group: TLS from the application tier only, no egress."
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "db_sg"
    Tier = "db"
  })
}

###############################################################################
# web_sg rules
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "web_sg_https_ipv4" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow HTTPS (TLS) from anywhere on IPv4."
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"

  tags = merge(var.tags, {
    Name = "web_sg-https-ipv4"
  })
}

resource "aws_vpc_security_group_ingress_rule" "web_sg_https_ipv6" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow HTTPS (TLS) from anywhere on IPv6."
  cidr_ipv6         = "::/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"

  tags = merge(var.tags, {
    Name = "web_sg-https-ipv6"
  })
}

resource "aws_vpc_security_group_ingress_rule" "web_sg_ssh" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow SSH only from within the VPC IPv4 CIDR."
  cidr_ipv4         = var.vpc_cidr
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"

  tags = merge(var.tags, {
    Name = "web_sg-ssh"
  })
}

resource "aws_vpc_security_group_egress_rule" "web_sg_to_app_sg" {
  security_group_id            = aws_security_group.web_sg.id
  description                  = "Allow HTTPS egress to the application tier only."
  referenced_security_group_id = aws_security_group.app_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"

  tags = merge(var.tags, {
    Name = "web_sg-to-app_sg"
  })
}

###############################################################################
# app_sg rules
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "app_sg_from_web_sg" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "Allow HTTPS from the web tier only."
  referenced_security_group_id = aws_security_group.web_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"

  tags = merge(var.tags, {
    Name = "app_sg-from-web_sg"
  })
}

resource "aws_vpc_security_group_egress_rule" "app_sg_to_db_sg" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "Allow HTTPS egress to the database tier only."
  referenced_security_group_id = aws_security_group.db_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"

  tags = merge(var.tags, {
    Name = "app_sg-to-db_sg"
  })
}

###############################################################################
# db_sg rules (ingress only; no egress rules means default deny egress)
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "db_sg_from_app_sg" {
  security_group_id            = aws_security_group.db_sg.id
  description                  = "Allow HTTPS from the application tier only."
  referenced_security_group_id = aws_security_group.app_sg.id
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"

  tags = merge(var.tags, {
    Name = "db_sg-from-app_sg"
  })
}

variable "create_vpc" {
  description = "Whether to create the VPC"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to add to all resources"
  type        = map(string)
  default     = {}
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "main"
}

variable "azs" {
  description = "List of availability zone names or IDs (if empty, uses all available AZs)"
  type        = list(string)
  default     = []
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_cidrs" {
  description = "List of CIDR blocks for intra (isolated) subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix for public subnet Name tag"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix for private subnet Name tag"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix for intra subnet Name tag"
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Explicit list of names for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit list of names for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit list of names for intra subnets"
  type        = list(string)
  default     = []
}

variable "nat_gateway_enabled" {
  description = "Whether to create NAT Gateways for private subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Whether to create an Internet Gateway"
  type        = bool
  default     = true
}

variable "map_public_ip_on_launch" {
  description = "Assign public IP on launch to public subnets"
  type        = bool
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs_list = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names
  vpc_id   = var.create_vpc ? aws_vpc.this[0].id : null

  public_count  = length(var.public_subnet_cidrs)
  private_count = length(var.private_subnet_cidrs)
  intra_count   = length(var.intra_subnet_cidrs)
  nat_count     = var.nat_gateway_enabled ? min(local.public_count, local.private_count) : 0
}

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    var.tags,
    { Name = var.vpc_name }
  )
}

resource "aws_subnet" "public" {
  count = local.public_count

  vpc_id     = local.vpc_id
  cidr_block = var.public_subnet_cidrs[count.index]
  availability_zone = element(local.azs_list, count.index)

  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    var.tags,
    {
      Name = length(var.public_subnet_names) > 0 ? var.public_subnet_names[count.index] : "${var.vpc_name}-${var.public_subnet_suffix}-${element(local.azs_list, count.index)}"
    }
  )
}

resource "aws_subnet" "private" {
  count = local.private_count

  vpc_id     = local.vpc_id
  cidr_block = var.private_subnet_cidrs[count.index]
  availability_zone = element(local.azs_list, count.index)

  tags = merge(
    var.tags,
    {
      Name = length(var.private_subnet_names) > 0 ? var.private_subnet_names[count.index] : "${var.vpc_name}-${var.private_subnet_suffix}-${element(local.azs_list, count.index)}"
    }
  )
}

resource "aws_subnet" "intra" {
  count = local.intra_count

  vpc_id     = local.vpc_id
  cidr_block = var.intra_subnet_cidrs[count.index]
  availability_zone = element(local.azs_list, count.index)

  tags = merge(
    var.tags,
    {
      Name = length(var.intra_subnet_names) > 0 ? var.intra_subnet_names[count.index] : "${var.vpc_name}-${var.intra_subnet_suffix}-${element(local.azs_list, count.index)}"
    }
  )
}

resource "aws_internet_gateway" "this" {
  count = var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    { Name = "${var.vpc_name}-igw" }
  )
}

resource "aws_route_table" "public" {
  count = var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    { Name = "${var.vpc_name}-${var.public_subnet_suffix}" }
  )
}

resource "aws_route" "public_internet" {
  count = var.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = local.public_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_eip" "nat" {
  count = local.nat_count

  tags = merge(
    var.tags,
    { Name = "${var.vpc_name}-nat-${element(local.azs_list, count.index)}" }
  )
}

resource "aws_nat_gateway" "this" {
  count = local.nat_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.tags,
    { Name = "${var.vpc_name}-nat-${element(local.azs_list, count.index)}" }
  )
}

resource "aws_route_table" "private" {
  count = local.private_count

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    { Name = "${var.vpc_name}-${var.private_subnet_suffix}-${element(local.azs_list, count.index)}" }
  )
}

resource "aws_route" "private_nat" {
  count = local.nat_count

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id        = aws_nat_gateway.this[count.index].id
}

resource "aws_route_table_association" "private" {
  count = local.private_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table" "intra" {
  count = local.intra_count

  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    { Name = "${var.vpc_name}-${var.intra_subnet_suffix}-${element(local.azs_list, count.index)}" }
  )
}

resource "aws_route_table_association" "intra" {
  count = local.intra_count

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "api_type" {
  description = "Type of API Gateway: 'http' for HTTP API (v2) or 'rest' for REST API (v1)"
  type        = string
  default     = "http"
}

variable "api_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "benchmark-api"
}

variable "environment_name" {
  description = "Environment name used for stage naming"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.101.0/24", "10.0.102.0/24"]
}

variable "http_routes" {
  description = "Map of HTTP API routes (method, path, integration type, integration URI)"
  type = map(object({
    method             = string
    path               = string
    integration_type   = string
    integration_uri    = string
  }))
  default = {}
}

variable "rest_resource_paths" {
  description = "Map of REST API resource paths and methods"
  type = map(object({
    path   = string
    method = string
  }))
  default = {}
}

variable "enable_vpc_link" {
  description = "Enable VPC link for the API"
  type        = bool
  default     = false
}

variable "custom_domain" {
  description = "Custom domain name configuration"
  type = object({
    domain_name       = string
    hosted_zone_id    = string
    certificate_arn   = optional(string)
  })
  default = null
}

variable "lambda_authorizer_config" {
  description = "Configuration for custom Lambda authorizer (REST API only)"
  type = object({
    function_name    = string
    handler          = string
    source_code_hash = string
    runtime          = string
    memory_size      = optional(number, 128)
    timeout          = optional(number, 30)
    vpc_config = optional(object({
      subnet_ids         = list(string)
      security_group_ids = list(string)
    }))
  })
  default = null
}

variable "rest_api_source_ip_whitelist" {
  description = "List of source IP CIDRs to whitelist in REST API resource policy"
  type        = list(string)
  default     = []
}

variable "nlb_target_port" {
  description = "TCP port for NLB target group (default 443)"
  type        = number
  default     = 443
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  azs = data.aws_availability_zones.available.names

  # Stage name
  stage_name = "${var.environment_name}-stage"

  # Common tags
  common_tags = {
    Environment = var.environment_name
    ManagedBy   = "terraform"
  }

  # Determine if HTTP or REST
  is_http = var.api_type == "http"
  is_rest = var.api_type == "rest"

  # Lambda authorizer function name
  authorizer_function_name = var.lambda_authorizer_config != null ? var.lambda_authorizer_config.function_name : "api-authorizer"
}

# ------------------------------------------------------------------------------
# VPC and Networking
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "${var.api_name}-vpc"
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, {
    Name = "${var.api_name}-igw"
  })
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index % length(local.azs)]
  tags = merge(local.common_tags, {
    Name = "${var.api_name}-public-${count.index}"
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index % length(local.azs)]
  tags = merge(local.common_tags, {
    Name = "${var.api_name}-private-${count.index}"
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = merge(local.common_tags, {
    Name = "${var.api_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Security Groups
# ------------------------------------------------------------------------------
resource "aws_security_group" "vpc_link" {
  count       = var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-vpc-link-sg"
  description = "Security group for API Gateway VPC link"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.api_name}-vpc-link-sg"
  })
}

resource "aws_security_group" "lambda" {
  count       = local.is_rest && var.lambda_authorizer_config != null && var.lambda_authorizer_config.vpc_config != null ? 1 : 0
  name        = "${var.api_name}-lambda-authorizer-sg"
  description = "Security group for Lambda authorizer"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.api_name}-lambda-authorizer-sg"
  })
}

resource "aws_security_group" "alb" {
  count       = local.is_rest && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-alb-sg"
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow TCP from NLB"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.api_name}-alb-sg"
  })
}

resource "aws_security_group" "nlb" {
  count       = local.is_rest && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-nlb-sg"
  description = "Security group for internal NLB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow TCP from VPC"
    from_port   = var.nlb_target_port
    to_port     = var.nlb_target_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.api_name}-nlb-sg"
  })
}

# ------------------------------------------------------------------------------
# HTTP API (v2) Resources
# ------------------------------------------------------------------------------
resource "aws_apigatewayv2_api" "http" {
  count                = local.is_http ? 1 : 0
  name                 = var.api_name
  protocol_type        = "HTTP"
  disable_execute_api_endpoint = false
  tags                 = local.common_tags
}

resource "aws_apigatewayv2_integration" "http" {
  for_each           = local.is_http ? var.http_routes : {}
  api_id             = aws_apigatewayv2_api.http[0].id
  integration_type   = each.value.integration_type
  integration_uri    = each.value.integration_uri
  integration_method = each.value.method
}

resource "aws_apigatewayv2_route" "http" {
  for_each     = local.is_http ? var.http_routes : {}
  api_id       = aws_apigatewayv2_api.http[0].id
  route_key    = "${each.value.method} ${each.value.path}"
  target       = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
}

resource "aws_apigatewayv2_stage" "http" {
  count       = local.is_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true
  tags        = local.common_tags
}

# HTTP API VPC Link
resource "aws_apigatewayv2_vpc_link" "http" {
  count              = local.is_http && var.enable_vpc_link ? 1 : 0
  name               = "${var.api_name}-vpc-link"
  security_group_ids = [aws_security_group.vpc_link[0].id]
  subnet_ids         = aws_subnet.private[*].id
  tags               = local.common_tags
}

# HTTP API Custom Domain
resource "aws_acm_certificate" "http_custom_domain" {
  count             = local.is_http && var.custom_domain != null ? 1 : 0
  domain_name       = var.custom_domain.domain_name
  validation_method = "DNS"
  subject_alternative_names = []
  tags              = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "http_cert_validation" {
  count   = local.is_http && var.custom_domain != null ? 1 : 0
  zone_id = var.custom_domain.hosted_zone_id
  name    = tolist(aws_acm_certificate.http_custom_domain[0].domain_validation_options)[0].resource_record_name
  type    = tolist(aws_acm_certificate.http_custom_domain[0].domain_validation_options)[0].resource_record_type
  records = [tolist(aws_acm_certificate.http_custom_domain[0].domain_validation_options)[0].resource_record_value]
  ttl     = 60
}

resource "aws_acm_certificate_validation" "http_custom_domain" {
  count                   = local.is_http && var.custom_domain != null ? 1 : 0
  certificate_arn         = aws_acm_certificate.http_custom_domain[0].arn
  validation_record_fqdns = [aws_route53_record.http_cert_validation[0].fqdn]
}

resource "aws_apigatewayv2_domain_name" "http" {
  count       = local.is_http && var.custom_domain != null ? 1 : 0
  domain_name = var.custom_domain.domain_name
  domain_name_configuration {
    certificate_arn = aws_acm_certificate.http_custom_domain[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
  tags = local.common_tags
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count       = local.is_http && var.custom_domain != null ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = local.stage_name
}

resource "aws_route53_record" "http_alias" {
  count   = local.is_http && var.custom_domain != null ? 1 : 0
  zone_id = var.custom_domain.hosted_zone_id
  name    = var.custom_domain.domain_name
  type    = "A"
  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# ------------------------------------------------------------------------------
# REST API (v1) Resources
# ------------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "rest" {
  count = local.is_rest ? 1 : 0
  name  = var.api_name
  endpoint_configuration {
    types = ["REGIONAL"]
  }
  tags = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

# Resource policy for IP whitelist
resource "aws_api_gateway_rest_api_policy" "rest" {
  count       = local.is_rest && length(var.rest_api_source_ip_whitelist) > 0 ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "execute-api:Invoke"
        Resource = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*"
      },
      {
        Effect = "Deny"
        Principal = "*"
        Action = "execute-api:Invoke"
        Resource = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*"
        Condition = {
          NotIpAddress = {
            "aws:SourceIp" = var.rest_api_source_ip_whitelist
          }
        }
      }
    ]
  })
}

# Dynamic resources and methods
resource "aws_api_gateway_resource" "rest" {
  for_each    = local.is_rest ? var.rest_resource_paths : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.value.path
}

resource "aws_api_gateway_method" "rest" {
  for_each      = local.is_rest ? var.rest_resource_paths : {}
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = aws_api_gateway_resource.rest[each.key].id
  http_method   = each.value.method
  authorization = "NONE"
}

# Deployment with trigger
resource "aws_api_gateway_deployment" "rest" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  triggers = {
    redeployment = sha256(jsonencode(var.rest_resource_paths))
  }
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count         = local.is_rest ? 1 : 0
  stage_name    = local.stage_name
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id
  tags          = local.common_tags
}

# Usage Plan and API Key
resource "aws_api_gateway_usage_plan" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = "${var.api_name}-usage-plan"
  description = "Usage plan for ${var.api_name}"
  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = local.stage_name
  }
  tags = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_api_gateway_api_key" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = "${var.api_name}-api-key"
  description = "API key for ${var.api_name}"
  enabled     = true
  tags        = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "api_key" {
  count       = local.is_rest ? 1 : 0
  name        = "/${var.api_name}/api-key"
  description = "API key for ${var.api_name}"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.rest[0].value
  tags        = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count          = local.is_rest ? 1 : 0
  usage_plan_id  = aws_api_gateway_usage_plan.rest[0].id
  key_id         = aws_api_gateway_api_key.rest[0].id
  key_type       = "API_KEY"
}

# Lambda Authorizer for REST API
resource "aws_iam_role" "lambda_authorizer" {
  count = local.is_rest && var.lambda_authorizer_config != null ? 1 : 0
  name  = "${var.api_name}-lambda-authorizer-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_authorizer_basic" {
  count      = local.is_rest && var.lambda_authorizer_config != null ? 1 : 0
  role       = aws_iam_role.lambda_authorizer[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy_attachment" "lambda_authorizer_vpc" {
  count      = local.is_rest && var.lambda_authorizer_config != null && var.lambda_authorizer_config.vpc_config != null ? 1 : 0
  role       = aws_iam_role.lambda_authorizer[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

resource "aws_lambda_function" "authorizer" {
  count            = local.is_rest && var.lambda_authorizer_config != null ? 1 : 0
  function_name    = local.authorizer_function_name
  role             = aws_iam_role.lambda_authorizer[0].arn
  handler          = var.lambda_authorizer_config.handler
  runtime          = var.lambda_authorizer_config.runtime
  filename         = "function.zip" # Placeholder; user must provide
  source_code_hash = var.lambda_authorizer_config.source_code_hash
  memory_size      = var.lambda_authorizer_config.memory_size
  timeout          = var.lambda_authorizer_config.timeout
  vpc_config {
    subnet_ids         = var.lambda_authorizer_config.vpc_config != null ? var.lambda_authorizer_config.vpc_config.subnet_ids : []
    security_group_ids = var.lambda_authorizer_config.vpc_config != null ? var.lambda_authorizer_config.vpc_config.security_group_ids : []
  }
  tags = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_authorizer" "rest" {
  count          = local.is_rest && var.lambda_authorizer_config != null ? 1 : 0
  name           = "${var.api_name}-authorizer"
  rest_api_id    = aws_api_gateway_rest_api.rest[0].id
  type           = "TOKEN"
  authorizer_uri = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials = aws_iam_role.lambda_authorizer[0].arn
}

resource "aws_lambda_permission" "api_gateway_invoke_authorizer" {
  count         = local.is_rest && var.lambda_authorizer_config != null ? 1 : 0
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[0].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*"
}

# REST API VPC Link with NLB and ALB
resource "aws_lb" "alb" {
  count              = local.is_rest && var.enable_vpc_link ? 1 : 0
  name               = "${var.api_name}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb[0].id]
  subnets            = aws_subnet.private[*].id
  tags               = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_target_group" "alb_default" {
  count       = local.is_rest && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-alb-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"
  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }
  tags = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener" "alb" {
  count             = local.is_rest && var.enable_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.alb[0].arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb_default[0].arn
  }
}

resource "aws_lb" "nlb" {
  count              = local.is_rest && var.enable_vpc_link ? 1 : 0
  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = aws_subnet.private[*].id
  tags               = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_target_group" "nlb" {
  count       = local.is_rest && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-nlb-tg"
  port        = var.nlb_target_port
  protocol    = "TCP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"
  health_check {
    protocol = "HTTPS"
    port     = var.nlb_target_port
    interval = 30
    timeout  = 10
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }
  tags = local.common_tags
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener" "nlb" {
  count             = local.is_rest && var.enable_vpc_link ? 1 : 0
  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.nlb_target_port
  protocol          = "TCP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }
}

# Retrieve ALB network interfaces
data "aws_network_interface" "alb" {
  count = local.is_rest && var.enable_vpc_link ? length(aws_lb.alb[0].subnets) : 0
  filter {
    name   = "description"
    values = ["ELB app/${aws_lb.alb[0].arn_suffix}/*"]
  }
  depends_on = [aws_lb.alb]
}

resource "aws_lb_target_group_attachment" "nlb" {
  count            = local.is_rest && var.enable_vpc_link ? length(data.aws_network_interface.alb) : 0
  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = data.aws_network_interface.alb[count.index].private_ip
  port             = var.nlb_target_port
}

resource "aws_api_gateway_vpc_link" "rest" {
  count       = local.is_rest && var.enable_vpc_link ? 1 : 0
  name        = "${var.api_name}-vpc-link"
  target_arns = [aws_lb.nlb[0].arn]
  description = "VPC Link for REST API"
  tags        = local.common_tags
}

# Lambda permission for HTTP API authorizer (if any)
resource "aws_lambda_permission" "http_api_gateway_invoke" {
  count         = local.is_http && var.lambda_authorizer_config != null ? 1 : 0
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = var.lambda_authorizer_config.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http[0].execution_arn}/*"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "s3_bucket_name" {
  description = "Name of the S3 bucket that stores CloudTrail log files. When empty, a unique name is generated from the account ID, region and a random suffix."
  type        = string
  default     = ""
}

variable "s3_key_prefix" {
  description = "Optional prefix (folder) inside the CloudTrail S3 bucket under which log files are delivered."
  type        = string
  default     = ""
}

variable "s3_force_destroy" {
  description = "Whether all objects in the CloudTrail S3 bucket are deleted when the bucket is destroyed."
  type        = bool
  default     = true
}

variable "s3_versioning_enabled" {
  description = "Whether versioning is enabled on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "kms_deletion_window_in_days" {
  description = "Number of days before the CloudTrail KMS key is permanently deleted after destruction."
  type        = number
  default     = 30
}

variable "kms_key_rotation_enabled" {
  description = "Whether automatic annual rotation of the CloudTrail KMS key is enabled."
  type        = bool
  default     = true
}

variable "kms_alias_prefix" {
  description = "Prefix used for the CloudTrail KMS key alias."
  type        = string
  default     = "cloudtrail"
}

variable "cloudwatch_log_retention_days" {
  description = "Retention period, in days, for the CloudTrail CloudWatch log group."
  type        = number
  default     = 90
}

variable "include_global_service_events" {
  description = "Whether global service events (for example IAM) are included in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail applies to all AWS regions."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether logging is enabled for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail."
  type        = bool
  default     = false
}

variable "event_selector_read_write_type" {
  description = "Read/write type of the default event selector (All, ReadOnly or WriteOnly)."
  type        = string
  default     = "All"

  validation {
    condition     = contains(["All", "ReadOnly", "WriteOnly"], var.event_selector_read_write_type)
    error_message = "The event selector read/write type must be one of: All, ReadOnly, WriteOnly."
  }
}

variable "include_management_events" {
  description = "Whether management events are recorded by the default event selector."
  type        = bool
  default     = true
}

variable "event_selectors" {
  description = "Explicit list of CloudTrail event selectors. When empty, a single selector is built from the read/write type, management events and data resource variables."
  type = list(object({
    read_write_type           = string
    include_management_events = bool
    data_resources = list(object({
      type   = string
      values = list(string)
    }))
  }))
  default = []
}

variable "data_resources" {
  description = "Data resource definitions (for example S3 object level events) added to the dynamically generated event selector."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_types" {
  description = "CloudTrail insight types to enable (for example ApiCallRateInsight or ApiErrorRateInsight). Empty disables insights."
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Whether an SNS topic for CloudTrail log delivery notifications is created by this configuration."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of an externally managed SNS topic used for CloudTrail notifications when no topic is created here."
  type        = string
  default     = ""
}

variable "cloudtrail_kms_decrypt_role_arn" {
  description = "Optional IAM role ARN granted decrypt permissions on the CloudTrail KMS key."
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment name applied to the tags of every resource."
  type        = string
  default     = "prod"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Random suffix for the dynamically generated bucket name
###############################################################################

resource "random_string" "suffix" {
  length  = 8
  lower   = true
  upper   = false
  numeric = true
  special = false
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  trail_name = "cloudtrail"
  trail_arn  = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${local.trail_name}"

  bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : "${local.account_id}-${local.region}-cloudtrail-${random_string.suffix.result}"

  s3_key_prefix = var.s3_key_prefix == "" ? "" : "${trimsuffix(var.s3_key_prefix, "/")}/"

  cloudwatch_log_group_name = "/aws/cloudtrail/${local.trail_name}"
  cloudwatch_log_group_arn  = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.cloudwatch_log_group_name}"

  event_selectors = length(var.event_selectors) > 0 ? var.event_selectors : [
    {
      read_write_type           = var.event_selector_read_write_type
      include_management_events = var.include_management_events
      data_resources            = var.data_resources
    }
  ]

  sns_topic_arn  = var.create_sns_topic ? one(aws_sns_topic.cloudtrail_alerts[*].arn) : (var.sns_topic_arn != "" ? var.sns_topic_arn : null)
  sns_topic_name = var.create_sns_topic ? one(aws_sns_topic.cloudtrail_alerts[*].name) : (var.sns_topic_arn != "" ? var.sns_topic_arn : null)

  common_tags = merge(var.tags, {
    Name        = local.trail_name
    Environment = var.environment
  })
}

###############################################################################
# KMS key used to encrypt CloudTrail log files and the CloudWatch log group
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAccountKeyAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowCloudTrailLogEncryption"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["${local.cloudwatch_log_group_arn}*"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["${local.cloudwatch_log_group_arn}*"]
    }
  }

  statement {
    sid       = "AllowS3BucketEncryption"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.cloudtrail_logs.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  dynamic "statement" {
    for_each = var.cloudtrail_kms_decrypt_role_arn != "" ? [var.cloudtrail_kms_decrypt_role_arn] : []

    content {
      sid       = "AllowLogDecryptionForProvidedRole"
      effect    = "Allow"
      actions   = ["kms:Decrypt", "kms:DescribeKey", "kms:GenerateDataKey*", "kms:ReEncrypt*"]
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail log files and CloudWatch log data for ${local.trail_name}"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = var.kms_key_rotation_enabled
  is_enabled              = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${var.kms_alias_prefix}-cloudtrail"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

###############################################################################
# S3 bucket for CloudTrail log file storage
###############################################################################

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = var.s3_force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = var.s3_versioning_enabled ? "Enabled" : "Suspended"
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/${local.s3_key_prefix}AWSLogs/${local.account_id}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

###############################################################################
# CloudWatch log group and IAM role/policy used for log ingestion
###############################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.cloudwatch_log_group_name
  retention_in_days = var.cloudwatch_log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid     = "AllowCloudTrailToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name                 = "${local.trail_name}-cloudwatch-logs-role"
  description          = "Role assumed by CloudTrail to deliver events to the CloudWatch log group ${local.cloudwatch_log_group_name}"
  assume_role_policy   = data.aws_iam_policy_document.cloudtrail_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch" {
  statement {
    sid       = "AllowCloudTrailCreateLogStream"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream"]
    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }

  statement {
    sid       = "AllowCloudTrailPutLogEvents"
    effect    = "Allow"
    actions   = ["logs:PutLogEvents"]
    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:log-stream:*"]
  }
}

resource "aws_iam_policy" "cloudtrail_cloudwatch" {
  name        = "${local.trail_name}-cloudwatch-logs-policy"
  description = "Allows CloudTrail to create log streams and publish log events to ${local.cloudwatch_log_group_name}"
  policy      = data.aws_iam_policy_document.cloudtrail_cloudwatch.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch" {
  role       = aws_iam_role.cloudtrail_cloudwatch.name
  policy_arn = aws_iam_policy.cloudtrail_cloudwatch.arn
}

###############################################################################
# Optional SNS topic for CloudTrail notifications
###############################################################################

resource "aws_sns_topic" "cloudtrail_alerts" {
  count = var.create_sns_topic ? 1 : 0

  name = "${local.trail_name}-alerts"

  tags = local.common_tags
}

data "aws_iam_policy_document" "sns" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid       = "AllowCloudTrailToPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.cloudtrail_alerts[0].arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid       = "AllowTopicOwnerAdministration"
    effect    = "Allow"
    actions   = ["sns:GetTopicAttributes", "sns:SetTopicAttributes", "sns:AddPermission", "sns:RemovePermission", "sns:DeleteTopic", "sns:Subscribe", "sns:ListSubscriptionsByTopic", "sns:Publish"]
    resources = [aws_sns_topic.cloudtrail_alerts[0].arn]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_sns_topic_policy" "cloudtrail_alerts" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.cloudtrail_alerts[0].arn
  policy = data.aws_iam_policy_document.sns[0].json
}

###############################################################################
# CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "main" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_key_prefix                 = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  enable_log_file_validation    = true
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_name

  tags = local.common_tags

  dynamic "event_selector" {
    for_each = local.event_selectors

    content {
      read_write_type           = event_selector.value.read_write_type
      include_management_events = event_selector.value.include_management_events

      dynamic "data_resource" {
        for_each = event_selector.value.data_resources

        content {
          type   = data_resource.value.type
          values = data_resource.value.values
        }
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_types

    content {
      insight_type = insight_selector.value
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_iam_role_policy_attachment.cloudtrail_cloudwatch,
    aws_sns_topic_policy.cloudtrail_alerts,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "s3_bucket_id" {
  description = "ID (name) of the CloudTrail log storage bucket."
  value       = aws_s3_bucket.cloudtrail_logs.id
}

output "s3_bucket_arn" {
  description = "ARN of the CloudTrail log storage bucket."
  value       = aws_s3_bucket.cloudtrail_logs.arn
}

output "cloudtrail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.main.arn
}

output "cloudtrail_id" {
  description = "ID (name) of the CloudTrail trail."
  value       = aws_cloudtrail.main.id
}

output "cloudtrail_home_region" {
  description = "Home region of the CloudTrail trail."
  value       = aws_cloudtrail.main.home_region
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for CloudTrail encryption."
  value       = aws_kms_key.cloudtrail.arn
}

output "kms_key_id" {
  description = "ID of the KMS key used for CloudTrail encryption."
  value       = aws_kms_key.cloudtrail.key_id
}

output "kms_alias_name" {
  description = "Name of the KMS alias for the CloudTrail key."
  value       = aws_kms_alias.cloudtrail.name
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch log group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.cloudtrail.name
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch log group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.cloudtrail.arn
}

output "cloudtrail_cloudwatch_role_arn" {
  description = "ARN of the IAM role assumed by CloudTrail to write to CloudWatch Logs."
  value       = aws_iam_role.cloudtrail_cloudwatch.arn
}

output "cloudtrail_cloudwatch_policy_arn" {
  description = "ARN of the IAM policy granting CloudTrail CloudWatch Logs ingestion permissions."
  value       = aws_iam_policy.cloudtrail_cloudwatch.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic used for CloudTrail notifications (created by this configuration or provided)."
  value       = local.sns_topic_arn
}

output "sns_topic_name" {
  description = "Name of the SNS topic used for CloudTrail notifications, if any."
  value       = local.sns_topic_name
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  type        = string
  default     = "legion"
  description = "Name of the EKS cluster"
}

# Data sources for AWS managed policies
data "aws_iam_policy" "eks_cluster" {
  name = "AmazonEKSClusterPolicy"
}

data "aws_iam_policy" "eks_service" {
  name = "AmazonEKSServicePolicy"
}

data "aws_iam_policy" "eks_worker_node" {
  name = "AmazonEKSWorkerNodePolicy"
}

data "aws_iam_policy" "eks_cni" {
  name = "AmazonEKS_CNI_Policy"
}

data "aws_iam_policy" "ecr_readonly" {
  name = "AmazonEC2ContainerRegistryReadOnly"
}

# Assume role policy documents
data "aws_iam_policy_document" "master_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "worker_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Custom autoscaling policy document
data "aws_iam_policy_document" "worker_autoscaling" {
  statement {
    sid    = "DescribeAutoScaling"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchTemplateVersions"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ModifyAutoScaling"
    effect = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

# Master IAM role
resource "aws_iam_role" "master" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.master_assume.json
}

# Attach managed policies to master role
resource "aws_iam_role_policy_attachment" "master_eks_cluster" {
  role       = aws_iam_role.master.name
  policy_arn = data.aws_iam_policy.eks_cluster.arn
}

resource "aws_iam_role_policy_attachment" "master_eks_service" {
  role       = aws_iam_role.master.name
  policy_arn = data.aws_iam_policy.eks_service.arn
}

# Worker IAM role
resource "aws_iam_role" "worker" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.worker_assume.json
}

# Attach managed policies to worker role
resource "aws_iam_role_policy_attachment" "worker_eks_worker_node" {
  role       = aws_iam_role.worker.name
  policy_arn = data.aws_iam_policy.eks_worker_node.arn
}

resource "aws_iam_role_policy_attachment" "worker_eks_cni" {
  role       = aws_iam_role.worker.name
  policy_arn = data.aws_iam_policy.eks_cni.arn
}

resource "aws_iam_role_policy_attachment" "worker_ecr_readonly" {
  role       = aws_iam_role.worker.name
  policy_arn = data.aws_iam_policy.ecr_readonly.arn
}

# Custom autoscaling policy
resource "aws_iam_policy" "worker_autoscaling" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "Custom policy for EKS cluster autoscaler"
  policy      = data.aws_iam_policy_document.worker_autoscaling.json
}

# Attach custom autoscaling policy to worker role
resource "aws_iam_role_policy_attachment" "worker_autoscaling" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.worker_autoscaling.arn
}

# Instance profile for worker nodes
resource "aws_iam_instance_profile" "worker" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.worker.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Reusable policy documents
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_full" {
  statement {
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "github_inline" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "acm:RequestCertificate",
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:GetDistributionConfig",
      "cloudfront:ListDistributions",
      "cloudfront:UpdateDistribution",
      "iam:GetRole",
      "iam:ListRoles",
      "iam:PassRole",
      "lambda:CreateFunction",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:InvokeFunction",
      "lambda:ListFunctions",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "route53:ListHostedZones",
      "route53:ListResourceRecordSets",
      "s3:GetBucketPolicy",
      "s3:GetBucketPolicyStatus",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutBucketPolicy",
      "s3:PutObject",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:ListQueues",
      "sqs:ReceiveMessage",
      "sqs:SendMessage"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "serverless_policy" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "acm:RequestCertificate",
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:GetDistributionConfig",
      "cloudfront:ListDistributions",
      "cloudfront:UpdateDistribution",
      "iam:GetRole",
      "iam:ListRoles",
      "iam:PassRole",
      "lambda:CreateFunction",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:InvokeFunction",
      "lambda:ListFunctions",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "route53:ListHostedZones",
      "route53:ListResourceRecordSets",
      "s3:GetBucketPolicy",
      "s3:GetBucketPolicyStatus",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutBucketPolicy",
      "s3:PutObject",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:ListQueues",
      "sqs:ReceiveMessage",
      "sqs:SendMessage"
    ]
    resources = ["*"]
  }
}

# ------------------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ------------------------------------------------------------------------------
# Inline group policies
# ------------------------------------------------------------------------------
resource "aws_iam_group_policy" "admin" {
  name   = "admin-full"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin_full.json
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-terraform-cloud-full"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = data.aws_iam_policy_document.admin_full.json
}

resource "aws_iam_group_policy" "github" {
  name   = "github-inline"
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github_inline.json
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless-inline"
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless_policy.json
}

# ------------------------------------------------------------------------------
# IAM Users
# ------------------------------------------------------------------------------
resource "aws_iam_user" "admin" {
  name = "admin"
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
}

resource "aws_iam_user" "github" {
  name = "github"
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
}

# ------------------------------------------------------------------------------
# User group memberships
# ------------------------------------------------------------------------------
resource "aws_iam_user_group_membership" "admin_members" {
  user = aws_iam_user.admin.name
  groups = [
    aws_iam_group.admin.name
  ]
}

resource "aws_iam_user_group_membership" "admin_macbook_pro_members" {
  user = aws_iam_user.admin_macbook_pro.name
  groups = [
    aws_iam_group.admin.name
  ]
}

resource "aws_iam_user_group_membership" "admin_terraform_cloud_members" {
  user = aws_iam_user.admin_terraform_cloud.name
  groups = [
    aws_iam_group.admin_terraform_cloud.name
  ]
}

resource "aws_iam_user_group_membership" "github_members" {
  user = aws_iam_user.github.name
  groups = [
    aws_iam_group.github.name
  ]
}

resource "aws_iam_user_group_membership" "serverless_members" {
  user = aws_iam_user.serverless.name
  groups = [
    aws_iam_group.serverless.name
  ]
}

# ------------------------------------------------------------------------------
# Access keys (for admin-macbook-pro and admin-terraform-cloud)
# ------------------------------------------------------------------------------
resource "aws_iam_access_key" "admin_macbook_pro" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

# ------------------------------------------------------------------------------
# Secrets Manager – store access keys
# ------------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "admin_macbook_pro" {
  name = "access-key/admin-macbook-pro"
}

resource "aws_secretsmanager_secret_version" "admin_macbook_pro" {
  secret_id = aws_secretsmanager_secret.admin_macbook_pro.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_macbook_pro.id
    secret_access_key = aws_iam_access_key.admin_macbook_pro.secret
  })
}

resource "aws_secretsmanager_secret" "admin_terraform_cloud" {
  name = "access-key/admin-terraform-cloud"
}

resource "aws_secretsmanager_secret_version" "admin_terraform_cloud" {
  secret_id = aws_secretsmanager_secret.admin_terraform_cloud.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_terraform_cloud.id
    secret_access_key = aws_iam_access_key.admin_terraform_cloud.secret
  })
}

# ------------------------------------------------------------------------------
# Serverless IAM Role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "serverless_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com", "edgelambda.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "serverless" {
  name               = "serverless"
  path               = "/serverless/"
  assume_role_policy = data.aws_iam_policy_document.serverless_assume_role.json
}

# ------------------------------------------------------------------------------
# Customer managed policy for serverless role
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Policy for serverless workloads"
  policy      = data.aws_iam_policy_document.serverless_policy.json
}

# ------------------------------------------------------------------------------
# Attach the customer managed policy to the serverless role
# ------------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

# Data sources
data "aws_caller_identity" "current" {}

# Variables
variable "namespace" {
  type        = string
  default     = "default"
  description = "Namespace for resource labeling"
}

variable "environment" {
  type        = string
  default     = "dev"
  description = "Environment for resource labeling"
}

variable "name" {
  type        = string
  default     = "iam-mfa"
  description = "Name for resource labeling"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes for resource labeling"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags applied to all resources"
}

variable "admin_users" {
  type        = list(string)
  default     = []
  description = "List of IAM users to be added to the admin group"
}

variable "non_admin_users" {
  type        = list(string)
  default     = []
  description = "List of IAM users to be added to the non-admin group"
}

# CloudPosse labels
module "label_admin" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  namespace  = var.namespace
  environment = var.environment
  name       = var.name
  attributes = concat(var.attributes, ["admin"])
  tags       = var.tags
}

module "label_non_admin" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  namespace  = var.namespace
  environment = var.environment
  name       = var.name
  attributes = concat(var.attributes, ["non-admin"])
  tags       = var.tags
}

# IAM groups
resource "aws_iam_group" "admin" {
  name = module.label_admin.id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group" "non_admin" {
  name = module.label_non_admin.id

  lifecycle {
    prevent_destroy = true
  }
}

# Self-management policy document
data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowSelfManagement"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:GetUser",
      "iam:ListAccessKeys",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:ListMFADevices",
      "iam:ListAccountPasswordPolicies",
      "iam:GetAccountPasswordPolicy",
      "iam:GetCredentialReport",
    ]
    resources = ["arn:aws:iam::*:user/aws:username"]
  }

  statement {
    sid    = "AllowDeactivateMFAWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice"
    ]
    resources = ["arn:aws:iam::*:user/aws:username"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.label_admin.id}-self-management"
  description = "Policy allowing users to manage their own IAM credentials with MFA enforcement"
  policy      = data.aws_iam_policy_document.self_management.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy_attachment" "self_management_admin" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "self_management_non_admin" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

# Admin role assume policy document
data "aws_iam_policy_document" "admin_role_assume" {
  statement {
    sid    = "AllowAdminRoleAssume"
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    resources = [
      aws_iam_role.admin.arn
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_role_assume" {
  name        = "${module.label_admin.id}-admin-role-assume"
  description = "Policy allowing admin group members to assume the admin role with MFA"
  policy      = data.aws_iam_policy_document.admin_role_assume.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy_attachment" "admin_role_assume" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_role_assume.arn
}

# Admin role
data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid    = "AllowRootAssumeWithMFA"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = "${module.label_admin.id}-admin-role"
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  description        = "Admin role requiring MFA to assume"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

# IAM users
resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_users)
  name     = each.key

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_users)
  name     = each.key

  lifecycle {
    prevent_destroy = true
  }
}

# Group memberships
resource "aws_iam_user_group_membership" "admin" {
  for_each = toset(var.admin_users)
  user     = aws_iam_user.admin[each.key].name
  groups   = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "non_admin" {
  for_each = toset(var.non_admin_users)
  user     = aws_iam_user.non_admin[each.key].name
  groups   = [aws_iam_group.non_admin.name]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "enabled" {
  description = "Main enable toggle for the module"
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "Toggle to create a new security group or use an existing one"
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to attach rules to (required when create_security_group is false)"
  type        = string
  default     = null
  validation {
    condition     = var.create_security_group ? true : var.existing_security_group_id != null
    error_message = "existing_security_group_id must be provided when create_security_group is false."
  }
}

variable "vpc_id" {
  description = "VPC ID for the new security group (if not provided and create_security_group is true, a fallback VPC is created)"
  type        = string
  default     = null
}

variable "namespace" {
  description = "Namespace for the label module"
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment for the label module"
  type        = string
  default     = ""
}

variable "name" {
  description = "Name for the label module"
  type        = string
  default     = ""
}

variable "attributes" {
  description = "Additional attributes for the label module"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags for the label module"
  type        = map(string)
  default     = {}
}

variable "create_prefix_list" {
  description = "Toggle to create a managed prefix list"
  type        = bool
  default     = false
}

variable "ingress_rules" {
  description = "List of ingress rules"
  type = list(object({
    cidr_blocks              = list(string)
    self                     = bool
    source_security_group_id = string
    prefix_list_id           = string
    description              = string
    from_port                = number
    to_port                  = number
    protocol                 = string
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rules"
  type = list(object({
    cidr_blocks              = list(string)
    self                     = bool
    source_security_group_id = string
    prefix_list_id           = string
    description              = string
    from_port                = number
    to_port                  = number
    protocol                 = string
  }))
  default = []
}

# Locals
locals {
  create_sg = var.enabled && var.create_security_group

  # Separate locals for label module outputs to avoid type mismatch
  labels_id   = var.enabled ? module.labels[0].id : ""
  labels_tags = var.enabled ? module.labels[0].tags : {}

  # Safely get fallback VPC ID (null if not created)
  fallback_vpc_id = one(aws_vpc.fallback[*].id)

  # Determine VPC ID for the security group
  vpc_id_for_sg = local.create_sg ? (
    var.vpc_id != null && var.vpc_id != "" ? var.vpc_id : local.fallback_vpc_id
  ) : null

  # Security group ID to attach rules to
  sg_id = local.create_sg ? aws_security_group.main[0].id : var.existing_security_group_id

  # Default prefix list ID (null if not created)
  default_prefix_list_id = var.enabled && var.create_prefix_list ? aws_ec2_managed_prefix_list.main[0].id : null
}

# Label module
module "labels" {
  source      = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  count       = var.enabled ? 1 : 0
  name        = "${var.namespace}-${var.environment}-${var.name}"
  environment = var.environment
  attributes  = var.attributes
}

# Fallback VPC (only when creating a new SG and no VPC ID provided)
resource "aws_vpc" "fallback" {
  count      = local.create_sg && (var.vpc_id == null || var.vpc_id == "") ? 1 : 0
  cidr_block = "10.0.0.0/16"

  tags = merge(
    local.labels_tags,
    var.tags,
    { Name = "${local.labels_id}-vpc" }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Managed prefix list (optional)
resource "aws_ec2_managed_prefix_list" "main" {
  count          = var.enabled && var.create_prefix_list ? 1 : 0
  name           = "${local.labels_id}-prefix-list"
  address_family = "IPv4"
  max_entries    = 5

  tags = merge(local.labels_tags, var.tags)
}

# Security group (new)
resource "aws_security_group" "main" {
  count       = local.create_sg ? 1 : 0
  name        = "${local.labels_id}-sg"
  description = "${local.labels_id}-sg"
  vpc_id      = local.vpc_id_for_sg

  tags = merge(local.labels_tags, var.tags)
}

# Ingress rules
resource "aws_security_group_rule" "ingress" {
  for_each = var.enabled ? { for idx, rule in var.ingress_rules : idx => rule } : {}

  security_group_id = local.sg_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  self              = each.value.self
  cidr_blocks       = each.value.self ? null : each.value.cidr_blocks
  source_security_group_id = each.value.self ? null : each.value.source_security_group_id
  prefix_list_ids   = each.value.self ? null : (
    each.value.prefix_list_id != null ? [each.value.prefix_list_id] : (
      local.default_prefix_list_id != null ? [local.default_prefix_list_id] : null
    )
  )
}

# Egress rules
resource "aws_security_group_rule" "egress" {
  for_each = var.enabled ? { for idx, rule in var.egress_rules : idx => rule } : {}

  security_group_id = local.sg_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = each.value.description
  self              = each.value.self
  cidr_blocks       = each.value.self ? null : each.value.cidr_blocks
  source_security_group_id = each.value.self ? null : each.value.source_security_group_id
  prefix_list_ids   = each.value.self ? null : (
    each.value.prefix_list_id != null ? [each.value.prefix_list_id] : (
      local.default_prefix_list_id != null ? [local.default_prefix_list_id] : null
    )
  )
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/2/amazon-linux-2/recommended/image_id"
}

# VPC and networking
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name                                = "demo-eks-vpc"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name                                = "demo-eks-igw"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.128.0/20"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = {
    Name                                = "demo-eks-public-subnet"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"
  tags = {
    Name                                = "demo-eks-nat-eip"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  tags = {
    Name                                = "demo-eks-nat-gw"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
  tags = {
    Name                                = "demo-eks-public-rt"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = ["10.0.0.0/19", "10.0.32.0/19", "10.0.64.0/19"][count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name                                = "demo-eks-private-subnet-${count.index + 1}"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }
  tags = {
    Name                                = "demo-eks-private-rt"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Node security group
resource "aws_security_group" "eks_node_sg" {
  name        = "demo-eks-node-sg"
  description = "Node security group"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name                                = "demo-eks-node-sg"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

# Node internal communication
resource "aws_security_group_rule" "node_ingress_self" {
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.eks_node_sg.id
}

# Node egress restricted to VPC CIDR
resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.eks_node_sg.id
}

# Node IAM role and instance profile
resource "aws_iam_role" "node" {
  name = "eks-demo-node"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
  tags = {
    "kubernetes.io/cluster/demo-eks" = "owned"
  }
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_readonly" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node-instance-profile"
  role = aws_iam_role.node.name
  tags = {
    "kubernetes.io/cluster/demo-eks" = "owned"
  }
}

# SSH key pair
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh
  tags = {
    "kubernetes.io/cluster/demo-eks" = "owned"
  }
}

# User data for nodes (placeholder – no cluster to bootstrap)
locals {
  node_user_data = ""
}

# Launch template
resource "aws_launch_template" "node" {
  name          = "eks-demo-node-lt"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name

  metadata_options {
    http_tokens             = "required"
    http_put_response_hop_limit = 2
  }

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  user_data = base64encode(local.node_user_data)

  vpc_security_group_ids = [aws_security_group.eks_node_sg.id]

  iam_instance_profile {
    arn = aws_iam_instance_profile.node.arn
  }

  tag_specifications {
    resource_type = "instance"
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }

  tag_specifications {
    resource_type = "volume"
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }

  tags = {
    Name                                = "eks-demo-node-lt"
    "kubernetes.io/cluster/demo-eks"   = "owned"
  }
}

# Auto Scaling Group for worker nodes
resource "aws_autoscaling_group" "eks" {
  name                      = "eks-demo-node-asg"
  wait_for_capacity_timeout = "0"
  launch_template {
    id      = aws_launch_template.node.id
    version = "$Default"
  }
  vpc_zone_identifier = aws_subnet.private[*].id
  min_size            = 1
  max_size            = 4
  desired_capacity    = 3

  tag {
    key                 = "kubernetes.io/cluster/demo-eks"
    value               = "owned"
    propagate_at_launch = true
  }
}

# Outputs
output "node_instance_role_arn" {
  value = aws_iam_role.node.arn
}

output "node_security_group_id" {
  value = aws_security_group.eks_node_sg.id
}

output "auto_scaling_group_id" {
  value = aws_autoscaling_group.eks.id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
  }
}

# Variables
variable "replica_region" {
  description = "Secondary AWS region for replica S3 bucket"
  type        = string
  default     = "us-west-2"
}

variable "stacks" {
  description = "Map of stack names to their respective AWS regions"
  type        = map(string)
  default = {
    eks-dev  = "us-east-1"
    eks-prod = "eu-west-1"
  }
}

# Data sources
data "aws_caller_identity" "current" {}

# Locals
locals {
  account_id          = data.aws_caller_identity.current.account_id
  primary_bucket_name = "terraform-state-${local.account_id}"
  replica_bucket_name = "terraform-state-${local.account_id}-replica"
  common_tags = {
    Environment = "Production"
    Terraform   = "true"
    Purpose     = "State Management"
  }
}

# Provider alias for replica region
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# Primary S3 Bucket (us-east-1)
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name
  tags   = local.common_tags
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "primary_ssl" {
  statement {
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary_ssl" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_ssl.json
}

# Primary KMS Key
resource "aws_kms_key" "primary" {
  description             = "KMS key for S3 state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags
}

resource "aws_kms_alias" "primary" {
  name          = "alias/terraform-state-primary"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Replica S3 Bucket (replica region)
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket_name
  tags     = local.common_tags
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "replica_ssl" {
  provider = aws.replica
  statement {
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica_ssl" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy   = data.aws_iam_policy_document.replica_ssl.json
}

# Replica KMS Key
resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "KMS key for replica S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags
}

resource "aws_kms_alias" "replica" {
  provider    = aws.replica
  name        = "alias/terraform-state-replica"
  target_key_id = aws_kms_key.replica.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# IAM Role and Policy for Replication
data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-state-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "replication_policy" {
  statement {
    actions = [
      "s3:GetObjectVersion",
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*"
    ]
  }
  statement {
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.primary.arn]
  }
  statement {
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:PutObject"
    ]
    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*"
    ]
  }
  statement {
    actions   = ["kms:Encrypt"]
    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name   = "s3-state-replication-policy"
  policy = data.aws_iam_policy_document.replication_policy.json
  tags   = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# S3 Replication Configuration
resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [aws_s3_bucket_versioning.primary, aws_iam_role_policy_attachment.replication]
  bucket     = aws_s3_bucket.primary.id
  role       = aws_iam_role.replication.arn

  rule {
    id       = "cross-region-replication"
    status   = "Enabled"
    filter {}

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# DynamoDB Tables for each stack (all in us-east-1)
resource "aws_dynamodb_table" "lock" {
  for_each     = var.stacks
  name         = "${each.key}-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
  tags = merge(local.common_tags, { Stack = each.key })
}

# IAM policies for each stack
data "aws_iam_policy_document" "stack_state_policy" {
  for_each = var.stacks
  statement {
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/eks-stacks/${each.key}/*"
    ]
  }
  statement {
    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem"
    ]
    resources = [aws_dynamodb_table.lock[each.key].arn]
  }
  statement {
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.primary.arn]
  }
}

resource "aws_iam_policy" "stack_state" {
  for_each = var.stacks
  name     = "eks-state-policy-${each.key}"
  policy   = data.aws_iam_policy_document.stack_state_policy[each.key].json
  tags     = local.common_tags
}

# Local backend files for each stack
resource "local_file" "backend" {
  for_each = var.stacks
  filename = "eks-stacks/${each.key}/backend.tf"
  content  = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${local.primary_bucket_name}"
        key            = "eks-stacks/${each.key}/terraform.tfstate"
        region         = "us-east-1"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.primary.arn}"
        dynamodb_table = "${each.key}-lock"
        dynamodb_region = "us-east-1"
      }
    }
  EOT
  file_permission = "0644"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

locals {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Naming (two-word pet name shared by the API and the queue)
# ---------------------------------------------------------------------------
resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

# ---------------------------------------------------------------------------
# Dedicated customer-managed KMS key with automatic rotation
# ---------------------------------------------------------------------------
resource "aws_kms_key" "sqs" {
  description             = "Customer managed key for the ${random_pet.name.id} WebSocket message queue"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${random_pet.name.id}-sqs"
  target_key_id = aws_kms_key.sqs.key_id
}

# ---------------------------------------------------------------------------
# SQS queue encrypted with the dedicated CMK
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "messages" {
  name                              = random_pet.name.id
  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# API Gateway execution role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "apigw" {
  name = "${random_pet.name.id}-apigw-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw" {
  name = "${random_pet.name.id}-apigw-policy"
  role = aws_iam_role.apigw.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SendMessagesToQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = aws_sqs_queue.messages.arn
      },
      {
        Sid      = "UseQueueEncryptionKey"
        Effect   = "Allow"
        Action   = ["kms:GenerateDataKey", "kms:Decrypt"]
        Resource = aws_kms_key.sqs.arn
      },
      {
        Sid    = "WriteApiGatewayLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.apigw.arn}:*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# WebSocket API
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_api" "websocket" {
  name                       = random_pet.name.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# $connect -> MOCK integration returning HTTP 200
resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.websocket.id
  integration_type = "MOCK"

  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_route_response" "connect" {
  api_id             = aws_apigatewayv2_api.websocket.id
  route_id           = aws_apigatewayv2_route.connect.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.websocket.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "/200/"
}

# $default -> SQS SendMessage with the raw message body
resource "aws_apigatewayv2_integration" "default" {
  api_id             = aws_apigatewayv2_api.websocket.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = "arn:aws:apigateway:${local.region}:sqs:path/${aws_sqs_queue.messages.name}"
  credentials_arn    = aws_iam_role.apigw.arn

  request_templates = {
    "application/json" = jsonencode({
      MessageBody = "$input.body"
    })
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.websocket.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "/200/"
}

# $disconnect -> SQS SendMessage with a fixed body
resource "aws_apigatewayv2_integration" "disconnect" {
  api_id             = aws_apigatewayv2_api.websocket.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = "arn:aws:apigateway:${local.region}:sqs:path/${aws_sqs_queue.messages.name}"
  credentials_arn    = aws_iam_role.apigw.arn

  request_templates = {
    "application/json" = jsonencode({
      MessageBody = "Client disconnected"
    })
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

# ---------------------------------------------------------------------------
# Access logging and auto-deployed "dev" stage
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "apigw" {
  name              = "/aws/apigateway/${random_pet.name.id}"
  retention_in_days = 1
}

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.websocket.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw.arn

    format = jsonencode({
      requestId        = "$context.requestId"
      ip               = "$context.identity.sourceIp"
      requestTime      = "$context.requestTime"
      routeKey         = "$context.routeKey"
      status           = "$context.status"
      protocol         = "$context.protocol"
      responseLength   = "$context.responseLength"
      integrationError = "$context.integrationErrorMessage"
    })
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "websocket_endpoint_url" {
  description = "Full WebSocket endpoint URL including the stage name"
  value       = "${aws_apigatewayv2_api.websocket.api_endpoint}/${aws_apigatewayv2_stage.dev.name}"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The default (us-east-1) provider is injected by the deployment harness.
# Only the aliased provider required for the Multi-Region Access Point
# control plane (us-west-2) is declared here.
provider "aws" {
  alias  = "secondary"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "bucket_name_primary" {
  description = "Base name of the primary S3 bucket (AWS account ID is appended)."
  type        = string
  default     = "example1"
}

variable "bucket_name_secondary" {
  description = "Base name of the secondary S3 bucket (AWS account ID is appended)."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

locals {
  account_id            = data.aws_caller_identity.current.account_id
  partition             = data.aws_partition.current.partition
  root_arn              = "arn:${local.partition}:iam::${local.account_id}:root"
  primary_bucket_name   = "${var.bucket_name_primary}-${local.account_id}"
  secondary_bucket_name = "${var.bucket_name_secondary}-${local.account_id}"
  common_tags = merge(
    var.tags,
    {
      ManagedBy = "terraform"
    }
  )
}

###############################################################################
# Buckets
###############################################################################

resource "aws_s3_bucket" "primary" {
  bucket        = local.primary_bucket_name
  force_destroy = false
  tags          = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "secondary" {
  provider      = aws.secondary
  bucket        = local.secondary_bucket_name
  force_destroy = false
  tags          = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Versioning (required for replication and for MRAP backing buckets)
###############################################################################

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Object ownership (ACLs disabled, bucket owner preferred)
###############################################################################

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

###############################################################################
# Public access blocks
###############################################################################

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Customer managed KMS keys (one per bucket / region)
###############################################################################

data "aws_iam_policy_document" "kms_primary" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceAccess"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "kms_secondary" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceAccess"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "primary" {
  description             = "SSE-KMS key for ${local.primary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_primary.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "SSE-KMS key for ${local.secondary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_secondary.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${local.primary_bucket_name}"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_alias" "secondary" {
  provider      = aws.secondary
  name          = "alias/${local.secondary_bucket_name}"
  target_key_id = aws_kms_key.secondary.key_id
}

###############################################################################
# Default bucket encryption (SSE-KMS with each bucket's own CMK)
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }
  }
}

###############################################################################
# IAM role assumed by S3 for cross-region replication
###############################################################################

data "aws_iam_policy_document" "s3_replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  name               = "s3-replication-role"
  description        = "Role assumed by Amazon S3 to replicate objects between the primary and secondary buckets"
  assume_role_policy = data.aws_iam_policy_document.s3_replication_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "s3_replication" {
  statement {
    sid    = "SourceBucketReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "SourceObjectReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "DestinationBucketWritePermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    sid    = "PrimaryKeyDecryptPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "SecondaryKeyEncryptPermissions"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Least-privilege policy used by the S3 replication role"
  policy      = data.aws_iam_policy_document.s3_replication.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

###############################################################################
# Replication configuration on the primary bucket
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_iam_role_policy_attachment.s3_replication,
  ]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id     = "replicate-all-objects"
    status = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Multi-Region Access Point (control plane lives in us-west-2)
###############################################################################

resource "aws_s3control_multi_region_access_point" "this" {
  provider = aws.secondary

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_server_side_encryption_configuration.primary,
    aws_s3_bucket_server_side_encryption_configuration.secondary,
    aws_s3_bucket_public_access_block.primary,
    aws_s3_bucket_public_access_block.secondary,
    aws_s3_bucket_ownership_controls.primary,
    aws_s3_bucket_ownership_controls.secondary,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "mrap" {
  statement {
    sid    = "AllowOwningAccountGetPut"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_id]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3control_multi_region_access_point.this.arn}/object/*"]
  }

  statement {
    sid    = "DenyAllOtherPrincipals"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3control_multi_region_access_point.this.arn}/object/*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "this" {
  provider = aws.secondary

  details {
    name   = aws_s3control_multi_region_access_point.this.details[0].name
    policy = data.aws_iam_policy_document.mrap.json
  }

  depends_on = [
    aws_s3control_multi_region_access_point.this,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "primary_bucket_name" {
  description = "Name of the primary S3 bucket."
  value       = aws_s3_bucket.primary.id
}

output "primary_bucket_arn" {
  description = "ARN of the primary S3 bucket."
  value       = aws_s3_bucket.primary.arn
}

output "secondary_bucket_name" {
  description = "Name of the secondary S3 bucket."
  value       = aws_s3_bucket.secondary.id
}

output "secondary_bucket_arn" {
  description = "ARN of the secondary S3 bucket."
  value       = aws_s3_bucket.secondary.arn
}

output "s3_replication_role_arn" {
  description = "ARN of the IAM role used by S3 for replication."
  value       = aws_iam_role.s3_replication.arn
}

output "primary_kms_key_arn" {
  description = "ARN of the primary bucket's customer managed KMS key."
  value       = aws_kms_key.primary.arn
}

output "secondary_kms_key_arn" {
  description = "ARN of the secondary bucket's customer managed KMS key."
  value       = aws_kms_key.secondary.arn
}

output "multi_region_access_point_alias" {
  description = "Alias of the Multi-Region Access Point."
  value       = aws_s3control_multi_region_access_point.this.alias
}

output "multi_region_access_point_arn" {
  description = "ARN of the Multi-Region Access Point."
  value       = aws_s3control_multi_region_access_point.this.arn
}

data "aws_iam_policy_document" "lambda_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "create_ddb_backup_policy" {
  statement {
    actions   = ["dynamodb:CreateBackup"]
    resources = ["arn:aws:dynamodb:*:*:table/*"]
  }
}

data "aws_iam_policy_document" "remove_ddb_backup_policy" {
  statement {
    actions   = ["dynamodb:DeleteBackup"]
    resources = ["arn:aws:dynamodb:*:*:table/*/backup/*"]
  }

  statement {
    actions   = ["dynamodb:ListBackups"]
    resources = ["arn:aws:dynamodb:*:*:table/*"]
  }
}

data "aws_iam_policy_document" "lambda_logging_policy" {
  statement {
    actions   = ["logs:CreateLogGroup"]
    resources = ["arn:aws:logs:*:*:*"]
  }

  statement {
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["arn:aws:logs:*:*:log-group:/aws/lambda/*:*"]
  }
}

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role_policy.json
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role_policy.json
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name   = "create_ddb_backup_policy"
  policy = data.aws_iam_policy_document.create_ddb_backup_policy.json
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name   = "remove_ddb_backup_policy"
  policy = data.aws_iam_policy_document.remove_ddb_backup_policy.json
}

resource "aws_iam_policy" "lambda_logging" {
  name   = "lambda_logging"
  policy = data.aws_iam_policy_document.lambda_logging_policy.json
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_policy_attachment" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_policy_attachment" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "lambda_logging_attachment_create" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "lambda_logging_attachment_remove" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

output "create_ddb_backup_role_arn" {
  value = aws_iam_role.create_ddb_backup_role.arn
}

output "remove_ddb_backup_role_arn" {
  value = aws_iam_role.remove_ddb_backup_role.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  vpc_name    = "projectvpc"
  environment = "dev"

  common_tags = {
    Name        = local.vpc_name
    Environment = local.environment
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-subnet"
    Tier = "private"
  })
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-igw"
  })
}

# ---------------------------------------------------------------------------
# NAT Gateway (Elastic IP + NAT in the public subnet)
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "nat" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public.id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-gateway"
  })

  depends_on = [aws_internet_gateway.igw]
}

# ---------------------------------------------------------------------------
# Route Tables and Routes
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat.id
}

# ---------------------------------------------------------------------------
# Route Table Associations
# ---------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Environment = "production"
    Project     = "endpoint-backup"
  }
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

data "aws_iam_policy_document" "endpoint_backup_kms" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowEndpointBackupUserDataKeyAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_user.endpoint_backup.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer-managed key for endpoint-backup S3 bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.endpoint_backup_kms.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup/s3"
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "endpoint_backup_bucket" {
  statement {
    sid    = "DenyInsecureConnections"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyOutdatedTLS"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyExcessiveComplianceRetention"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
      "s3:PutObjectLegalHold",
      "s3:BypassGovernanceRetention",
    ]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "ForAnyValue:StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.endpoint_backup,
  ]
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"

  tags = local.common_tags
}

data "aws_iam_policy_document" "endpoint_backup_bucket_read_write_access" {
  statement {
    sid    = "BucketLevelListAccess"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
    ]
  }

  statement {
    sid    = "ObjectLevelReadWriteAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectVersion",
      "s3:DeleteObjectVersion",
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObjectLegalHold",
      "s3:GetObjectAttributes",
      "s3:RestoreObject",
    ]

    resources = [
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]
  }

  statement {
    sid    = "S3KmsDataKeyAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.endpoint_backup.arn,
    ]
  }
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Read, write, delete, version, retention, and restore access to the endpoint-backup S3 bucket, plus data-key access on the customer-managed KMS key used for bucket encryption."
  policy      = data.aws_iam_policy_document.endpoint_backup_bucket_read_write_access.json

  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "endpoint_backup_bucket_read_write_access" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write_access.arn
}

# main.tf

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables for region configuration
variable "source_region_2" {
  description = "Second source region for S3 buckets"
  type        = string
  default     = "us-west-2"
}

variable "replica_region_1" {
  description = "First replica region"
  type        = string
  default     = "eu-west-1"
}

variable "replica_region_2" {
  description = "Second replica region"
  type        = string
  default     = "ap-southeast-1"
}

# Data source for current AWS account ID
data "aws_caller_identity" "current" {}

# Local values for reuse
locals {
  account_id = data.aws_caller_identity.current.account_id
  common_tags = {
    Env = "dev"
  }
}

# Provider aliases (default provider is injected by harness for us-east-1)
provider "aws" {
  alias  = "source2"
  region = var.source_region_2
}

provider "aws" {
  alias  = "replica1"
  region = var.replica_region_1
}

provider "aws" {
  alias  = "replica2"
  region = var.replica_region_2
}

# ------------------------------------------------------------------------------
# KMS Keys and Aliases
# ------------------------------------------------------------------------------

# Source region 1 (us-east-1)
resource "aws_kms_key" "source1" {
  provider                = aws
  description             = "KMS key for source buckets in us-east-1"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source1" {
  provider      = aws
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.arn
}

# Source region 2
resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "KMS key for source buckets in ${var.source_region_2}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.arn
}

# Replica region 1
resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "KMS key for replica buckets in ${var.replica_region_1}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.arn
}

# Replica region 2
resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "KMS key for replica buckets in ${var.replica_region_2}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
