# ------------------------------------------------------------------------------
# IAM Role and Policy for S3 Replication
# ------------------------------------------------------------------------------

resource "aws_iam_role" "s3_replication_role" {
  provider = aws
  name     = "s3-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "s3_replication_policy" {
  provider    = aws
  name        = "s3-replication-policy"
  description = "Policy for S3 cross-region replication"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersionForReplication",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::log1a.veerum-${local.account_id}",
          "arn:aws:s3:::log1a.veerum-${local.account_id}/*",
          "arn:aws:s3:::log1b.veerum-${local.account_id}",
          "arn:aws:s3:::log1b.veerum-${local.account_id}/*",
          "arn:aws:s3:::log2a.veerum-${local.account_id}",
          "arn:aws:s3:::log2a.veerum-${local.account_id}/*",
          "arn:aws:s3:::log2b.veerum-${local.account_id}",
          "arn:aws:s3:::log2b.veerum-${local.account_id}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = [
          "arn:aws:s3:::log1a.veerum-${local.account_id}-replica1-${local.account_id}",
          "arn:aws:s3:::log1a.veerum-${local.account_id}-replica1-${local.account_id}/*",
          "arn:aws:s3:::log1b.veerum-${local.account_id}-replica1-${local.account_id}",
          "arn:aws:s3:::log1b.veerum-${local.account_id}-replica1-${local.account_id}/*",
          "arn:aws:s3:::log2a.veerum-${local.account_id}-replica1-${local.account_id}",
          "arn:aws:s3:::log2a.veerum-${local.account_id}-replica1-${local.account_id}/*",
          "arn:aws:s3:::log2b.veerum-${local.account_id}-replica1-${local.account_id}",
          "arn:aws:s3:::log2b.veerum-${local.account_id}-replica1-${local.account_id}/*",
          "arn:aws:s3:::log1a.veerum-${local.account_id}-replica2-${local.account_id}",
          "arn:aws:s3:::log1a.veerum-${local.account_id}-replica2-${local.account_id}/*",
          "arn:aws:s3:::log1b.veerum-${local.account_id}-replica2-${local.account_id}",
          "arn:aws:s3:::log1b.veerum-${local.account_id}-replica2-${local.account_id}/*",
          "arn:aws:s3:::log2a.veerum-${local.account_id}-replica2-${local.account_id}",
          "arn:aws:s3:::log2a.veerum-${local.account_id}-replica2-${local.account_id}/*",
          "arn:aws:s3:::log2b.veerum-${local.account_id}-replica2-${local.account_id}",
          "arn:aws:s3:::log2b.veerum-${local.account_id}-replica2-${local.account_id}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = "kms:Decrypt"
        Resource = [
          aws_kms_key.source1.arn,
          aws_kms_key.source2.arn
        ]
      },
      {
        Effect = "Allow"
        Action = "kms:Encrypt"
        Resource = [
          aws_kms_key.replica1.arn,
          aws_kms_key.replica2.arn
        ]
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  provider   = aws
  role       = aws_iam_role.s3_replication_role.name
  policy_arn = aws_iam_policy.s3_replication_policy.arn
}

# ------------------------------------------------------------------------------
# Replication Configuration for Each Source Bucket
# ------------------------------------------------------------------------------

# us-east-1 source buckets
resource "aws_s3_bucket_replication_configuration" "log1a" {
  provider = aws
  bucket   = aws_s3_bucket.log1a.id
  role     = aws_iam_role.s3_replication_role.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1

    filter {
      prefix = ""
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica1.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2

    filter {
